  Stage_118133_Desc = {
    Text = "긴 조사 말미에는, 조사원의 피곤한 혼을 위로하기 위해 미사그 대학교에는 전통이 있습니다: 그들에게 바다 바람과 햇볕이 초대하는 여유로운 휴가를 제공합니다.\n\n 오늘, 비밀 지키는 사람의 선물은 신모를 위해 준비되었습니다."
  },
  Stage_118133_Name = {
