  },
  Stage_118134_Desc = {
    Text = "긴 조사 말미에는, 조사원의 피곤한 혼을 위로하기 위해 미사그 대학교에는 전통이 있습니다: 그들에게 바다 바람과 햇볕이 초대하는 여유로운 휴가를 제공합니다.\n\n 오늘, 비밀 지키는 사람의 선물은 신모를 위해 준비되었습니다."
  },
  Stage_118134_Name = {
    Text = "신모의 휴일"
  },
  Stage_118135_Desc = {
    Text = "소용돌이의 경계를 자유롭게 떠다니는 것은 단지 연약한 배의 환상일 뿐.\n육안으로는 보이지 않는 소용돌이 줄기 속에, 모든 행운을 바라는 자를 집어 삼키고 조여들 수 있는 엄청난 끌림이 숨겨져 있다."
  },
  Stage_118135_Name = {
    Text = "소용돌이"
