  Stage_118136_Desc = {
    Text = "점프해, 뛰어내려, 사랑하는 긴 머리 공주야.\n그곳에 떨어지면, 따뜻하고 강한 기사님의 품이 기다릴 것이다."
  },
  Stage_118136_Name = {
    Text = "탑의 공주"
  },
  Stage_118137_Desc = {
    Text = "여기는「낙원호」로 알려져 있으며, 바다를 건너는 자 교회의 영원하고 유일한 해상 거점입니다.\n그녀의 영혼이 의탁된 곳으로, 손에 닿을 수 있는 이상향입니다."
  },
  Stage_118137_Name = {
    Text = "「파라다이스 호」"
  },
  Stage_118138_Desc = {
