  },
  Stage_118138_Name = {Text = "외부인"},
  Stage_118139_Desc = {
    Text = "성녀는 제단 위에 높이 서서 타오르는 화염을 바라본다.\n그녀의 눈에 비치는 뛰는 불꽃은 두려움이 아니라 마침내 도래한 운명이다.\n그녀는 장작이 터지는 소리와 내부의 신탁이 사라져가는 회상을 들을 수 있다.\n이 순간, 그녀는 더 이상 얽매인 죄수가 아니다."
  },
  Stage_118139_Name = {
    Text = "항해 의식"
