  Stage_119838_Desc = {
    Text = "이 무한한 우주 속에서, 당신은 별들의 노래를 들었다.\n하지만, 진공에서는 소리가 전달되지 않기에, 당신의 외침도, 그들의 광기어린 포효도, 완전한 침묵을 이룰 뿐이었다."
