    Text = "무형의 혼돈 속에서, 당신은 은열쇠를 단단히 쥐었다.\n그것은 이 혼란한 세계 속에서, 당신의 유일한 무기이자 동료이다."
  },
  Stage_120984_Name = {
    Text = "무질서한 전주"
  },
  Stage_120985_Desc = {
    Text = "별들은 고독하지 않고, 당신 역시 그러하다.\n당신의 곁을 지키고 있는 무수한 형체들이야말로, 당신의 「별들」이다."
