  Stage_122179_Name = {
    Text = "자신을 희생으로 바치다"
  },
  Stage_122180_Desc = {
    Text = "사고로 사고를 분석하더라도 여전히 사고에 지배받습니다.\n모든 것을 본능에 맡기세요~"
  },
  Stage_122180_Name = {
    Text = "본능적 사고·세 번째"
  },
  Stage_122181_Desc = {
    Text = "사고로 사고를 분석하더라도 여전히 사고에 지배받습니다.\n모든 것을 본능에 맡기세요~"
  },
  Stage_122181_Name = {
    Text = "본능적 사고·지네"
  },
  Stage_122182_Desc = {
    Text = "새로운 것은 종종 오래된 것의 폐허 위에 서 있습니다.\n그러니 그 오래되고 지루한 마음을 부숴버리세요!"
  },
  Stage_122182_Name = {
    Text = "심장을 부수다·광기"
  },
  Stage_122183_Desc = {
    Text = "언어에 힘이 담겨 있다면, 언어를 통제하면 힘도 통제할 수 있는 건가요? \n 내가 한번 해볼게요…… 와! 정말 잘 쓰인다!"
  },
  Stage_122183_Name = {
    Text = "제어 언어·광기"
  },
  Stage_122184_Desc = {
    Text = "언어에 힘이 담겨 있다면, 언어를 통제하면 힘도 통제할 수 있는 건가요? \n 내가 한번 해볼게요…… 와! 정말 잘 쓰인다!"
  },
  Stage_122184_Name = {
    Text = "언어 제어·육"
  },
  Stage_122185_Desc = {
    Text = "평범한 일상은 쓸모없는 맹장과 같아, 이제 잘라내야 할 때야~"
  },
  Stage_122185_Name = {
    Text = "맹장 절제·여섯 번째"
  },
  Stage_122186_Desc = {
    Text = "평범한 일상은 쓸모없는 맹장과 같아, 이제 잘라내야 할 때야~"
  },
  Stage_122186_Name = {
    Text = "막대 절단·중 하나"
  },
  Stage_122601_Name = {
    Text = "모샤 트라이얼 스테이지"
  },
  Stage_123112_Desc = {
    Text = "안개가 내 눈을 가려 나와 내 세계의 연결을 잃게 했지만, 당신의 두 눈을 통해 나는 다시 돌아갈 수 없는 과거와 다시는 만날 수 없는 사람들을 보았습니다.\n우리는 비슷합니다."
  },
  Stage_123112_Name = {
    Text = "당신의 두 눈을 통해"
  },
  Stage_123113_Desc = {
    Text = "안개가 내 눈을 가려 나와 내 세계의 연결을 잃게 했지만, 당신의 두 눈을 통해 나는 다시 돌아갈 수 없는 과거와 다시는 만날 수 없는 사람들을 보았습니다.\n우리는 비슷합니다."
  },
  Stage_123113_Name = {
    Text = "당신의 두 눈을 통해"
  },
  Stage_125199_Desc = {
    Text = "오직 사랑에 빠진 벌레만이 이렇게 손상되고, 이렇게 단단하며, 이렇게 우스꽝스럽고, 또 이렇게 비범하다.\n어라, 나와 함께 더 멋진 것을 보러 가자. 너희는 서로를 보살피고, 이제부터는 긴밀히 연결될 것이다."
  },
  Stage_125199_Name = {
    Text = "로직·세 번째"
  },
  Stage_125200_Desc = {
    Text = "열정은 항상 귀결이 있지만, 항상 늙어 함께하는 것만은 아닙니다. 억울하게 죽는 경우가 더 많을지도 모릅니다.\n가끔은 사랑이 억울하게 죽고, 가끔은 당신이 억울하게 죽습니다."
  },
  Stage_125200_Name = {
    Text = "억울하게 죽다·광기"
  },
  Stage_125201_Desc = {
    Text = "옛 사랑은 이미 당신을 떠났는데, 왜 지금에서야 후회하기 시작하나요?\n히히, 늦지 않았고, 급할 것도 없어요, 보세요——랑군. 해가 지면, 모든 등불과 모든 빨간 촛불이 창 뒤에 그녀의 형체, 그녀의 그림자를 비출 것입니다."
  },
  Stage_125201_Name = {
    Text = "창 뒤의 그림자·둘째"
  },
  Stage_125202_Desc = {
    Text = "「……매미의 허물을 벗고 뼈를 바꾸는 것을 시체 해탈이라 하여선에 오르다……」\n오, 사실타래은 그렇지 않아, 그것은 한편의 황당한 괴담이지만, 무슨 상관이 있을까? 그녀들은 피눈물로 소원하였고, 그래서 섬뜩한 아름다움과 공포가 그 안에서 다시 태어났다."
  },
  Stage_125202_Name = {
    Text = "시체 해탈·육"
  },
  Stage_125203_Desc = {
    Text = "옛 사랑은 이미 당신을 떠났는데, 왜 지금에서야 후회하기 시작하나요?\n히히, 늦지 않았고, 급할 것도 없어요, 보세요——랑군. 해가 지면, 모든 등불과 모든 빨간 촛불이 창 뒤에 그녀의 형체, 그녀의 그림자를 비출 것입니다."
  },
  Stage_125203_Name = {
    Text = "창 뒤의 그림자·중 하나"
  },
  Stage_125204_Desc = {
    Text = "그들은 함께 향안 제단 아래 무릎을 꿇고 있었고, 그 무형의 현녀는 알 수 없고, 정의할 수 없으며, 거역할 수 없었다. \n 모든 것을 바치고, 모든 것에 따르며, 유일한 극락에 오르고, 영원한 혼란에 이른다."
  },
  Stage_125204_Name = {
    Text = "극락·광기"
  },
  Stage_125205_Desc = {
    Text = "저는 당신의 향기가 좋아요, 저는 당신의 원수를 맛보아 드릴게요."
  },
  Stage_125205_Name = {
    Text = "향기를 따라·둘째"
  },
  Stage_125206_Desc = {
    Text = "그 신비한 결사는 동방 고국의 역사서 밖에 떠돌고 있으며, 그것은 탐지할 수 없고 정의할 수 없다. 오직 극소수의 지금까지도 사라지지 않고, 꿈 없는 땅에 영원히 거주하는 개체들만이 그들이 숭배했던 신의 이름을 알았었다. \n 그녀는 「@4」라고 불린다."
  },
  Stage_125206_Name = {
    Text = "부풀어 오른 군중·중 하나"
  },
  Stage_125207_Desc = {
