    Text = "기억 외에, 우리에게는 아무것도 없다."
  },
  Stage_125641_Name = {
    Text = "지난날의 환영"
  },
  Stage_125642_Desc = {
    Text = "배우 등장, 작자 미상."
  },
  Stage_125642_Name = {Text = "제2막"},
  Stage_125643_Desc = {
    Text = "무대의 환영 인사는: 편히 쉬다 가세요."
  },
  Stage_125643_Name = {
    Text = "안개 도시가 깨어나기 전"
  },
  Stage_125644_Desc = {
    Text = "연민과 기만으로부터 돌아오렴, 사랑하는 아이들아.\n그 빛 없는 버림받은 곳이야말로, 진정 너희가 있을 자리란다."
  },
  Stage_125644_Name = {Text = "재회"},
  Stage_125645_Desc = {
    Text = "사실타래, 먼 곳의 신은 결코 깨어나길 갈망하지 않는다."
  },
  Stage_125645_Name = {
    Text = "신성의 그림자"
  },
  Stage_125646_Desc = {
    Text = "막은 이미 내려졌으나, 헌신적인 배우는 결코 퇴장하지 않는다."
  },
  Stage_125646_Name = {Text = "폐막"},
  Stage_125647_Desc = {
    Text = "연민과 기만으로부터 돌아오렴, 사랑하는 아이들아.\n그 빛 없는 버림받은 곳이야말로, 진정 너희가 있을 자리란다."
  },
  Stage_125647_Name = {Text = "재회"},
  Stage_125648_Desc = {
    Text = "사랑하는 죄수여, 모든 것에 작별을 고하라. 운명의 판결에는 법률이 필요치 않다."
  },
  Stage_125648_Name = {Text = "판결"},
  Stage_125649_Desc = {
    Text = "대양 건너편의 허리케인은, 사실타래 그 나비의 선택과는 아무런 관련이 없었다."
  },
  Stage_125649_Name = {Text = "총성"},
  Stage_125650_Desc = {
    Text = "사실타래, 먼 곳의 신은 결코 깨어나길 갈망하지 않는다."
  },
  Stage_125650_Name = {
    Text = "신성의 그림자"
  },
  Stage_125651_Desc = {
    Text = "첨예한 가시와 화염보다 더 혹독한 형벌."
  },
  Stage_125651_Name = {
    Text = "부드러운 족쇄"
  },
  Stage_125652_Desc = {
    Text = "가장 아름다운 춤사위는, 언제나 죽음과 파멸 속에서 피어난다."
  },
  Stage_125652_Name = {
    Text = "날아오르는 백조"
  },
  Stage_125653_Desc = {
    Text = "90분의 자정, 15인치 가면, 10갤런의 꿈, 2온스의 알코올——행복의 유일한 배합법."
  },
  Stage_125653_Name = {
    Text = "가면 파티"
  },
  Stage_125654_Desc = {
    Text = "정성껏 리허설한 신작, 무료 관람, 이석 금지."
  },
  Stage_125654_Name = {
    Text = "극중 인물"
  },
  Stage_125655_Desc = {
    Text = "웃어라! 노래하라! 나의 벗이여! 운명의 무대 위에서, 환희만이 유일한 주인공이다."
  },
  Stage_125655_Name = {
    Text = "즉흥 희극"
  },
  Stage_125656_Desc = {
    Text = "극장에 발을 들인 순간, 우리의 배역은 이미 선택할 수 없었다."
  },
  Stage_125656_Name = {
    Text = "관객, 배우, 작가"
  },
  Stage_125657_Desc = {
    Text = "첨예한 가시와 화염보다 더 혹독한 형벌."
  },
  Stage_125657_Name = {
    Text = "부드러운 족쇄"
  },
  Stage_125658_Desc = {
    Text = "가장 아름다운 춤사위는, 언제나 죽음과 파멸 속에서 피어난다."
  },
  Stage_125658_Name = {
    Text = "날아오르는 백조"
  },
  Stage_125659_Desc = {
    Text = "90분의 자정, 15인치 가면, 10갤런의 꿈, 2온스의 알코올——행복의 유일한 배합법."
  },
  Stage_125659_Name = {
    Text = "가면 파티"
  },
  Stage_125660_Desc = {
    Text = "카드린 장원은 영광과 몰락의 연극을 즐겨 관람한다. 장원을 기쁘게 할 줄 아는 자만이 초대장을 받을 수 있다."
  },
  Stage_125660_Name = {
    Text = "저택의 초대장"
  },
  Stage_125661_Desc = {
    Text = "배우 등장, 작자 미상."
  },
  Stage_125661_Name = {Text = "제2막"},
  Stage_125662_Desc = {
    Text = "대양 건너편의 허리케인은, 사실타래 그 나비의 선택과는 아무런 관련이 없었다."
  },
  Stage_125662_Name = {Text = "총성"},
  Stage_125663_Desc = {
    Text = "불멸의 감옥은, 죄수의 손으로 직접 엮어낸 것.\n그녀들은 영원히 엮는다. 그녀들은 결코 벗어나지 못한다."
  },
  Stage_125663_Name = {Text = "고치"},
  Stage_126202_Desc = {
    Text = "꽃다발, 환호, 박수. 세상이 다시 그의 곁으로 돌아온다.\n서사의 마술사가 공연을 마치고, 관객의 기억은 우아한 커튼콜 속에서 흩어진다.\n어떠한 비밀도, 무대의 폐허를 벗어날 수 없다."
  },
  Stage_126202_Name = {
    Text = "스포일러 금지·네 번째"
  },
  Stage_126203_Desc = {
    Text = "맞이하라, 이야기의 클라이맥스를! 모든 복선은 연료이며, 모든 준비는 무대를 불태울 이 순간을 위한 것이었다."
  },
  Stage_126203_Name = {
    Text = "연소·네 번째"
  },
  Stage_126204_Desc = {
    Text = "지루함은 꼭두각시의 사형 선고다."
  },
  Stage_126204_Name = {
    Text = "반전, 반전·네 번째"
  },
  Stage_126208_Desc = {
    Text = "막이 오르고, 관객도 박수도 더 이상 존재하지 않는다.\n세상은 텅 비어 있고, 오직 유일한 조명만이 이 유일한 무대를 비춘다."
  },
  Stage_126208_Name = {
    Text = "입장·여섯 번째"
  },
