  Stage_129500_Desc = {
    Text = "판룡 고국의 매 기세절마다, 천남해북을 막론하고, 집집마다 다 함께 모인다.\n그들은 기세절이 다가올 때 먼 곳으로 가는 기차에 올라, 그리워하던 재회의 순간을 기대하며 설레는 마음을 안고 있다."
  },
  Stage_129500_Name = {
    Text = "기원 열차"
  },
  Stage_129501_Desc = {
    Text = "두려워하지 마, 이건 단지 게임이야.\n잔인하고 악랄한 게임."
  },
  Stage_129501_Name = {
    Text = "게임 시작"
  },
  Stage_129502_Desc = {
    Text = "멈추지 마세요, 물러서지 마세요.\n선의의 사람이 손에 든 총을 내려놓는다면, 악은 승승장구할 것입니다."
  },
  Stage_129502_Name = {
    Text = "두 번째 사망자"
  },
  Stage_129503_Desc = {
    Text = "이것은 정의의 절지 반격…인가?"
  },
  Stage_129503_Name = {
    Text = "숨겨진 필살기"
  },
  Stage_129504_Desc = {
    Text = "그 지팡이는 자주 당신의 꿈에 나타납니다.\n그것을 밀어야 할지, 아니면 당겨야 할지, 이것이 문제입니다."
  },
  Stage_129504_Name = {
    Text = "상시 어두운 방"
  },
  Stage_129505_Desc = {
    Text = "하늘을 가득 채운 불꽃이 옛 해를 떠나보내고, 과거의 재는 추적할 수 없다."
  },
  Stage_129505_Name = {
    Text = "과거의 불꽃"
  },
  Stage_130109_Desc = {
    Text = "사람도 학교에 다니고, 깨어남체도 학교에 다닌다.\n이제 그녀는 깨어남체가 되었으니, 당연히 학교에 다녀야 한다.\n안전에 각별히 유의하시기 바랍니다."
  },
  Stage_130109_Name = {
    Text = "학교·둘째"
  },
  Stage_130110_Desc = {
    Text = "어떻게 전설적인 조사관이 될 수 있을까? 우선, 모든 깊은 우물에는 수많은 비밀이 숨겨져 있다.\n그리고 우물 밑으로 뛰어들기 전에, 산탄총을 꼭 합법적으로 소지할 필요는 없다는 걸 기억하라."
  },
  Stage_130110_Name = {
    Text = "우물· 육"
  },
  Stage_130111_Desc = {
    Text = "어떻게 전설적인 조사관이 될 수 있을까? 우선, 모든 깊은 우물에는 수많은 비밀이 숨겨져 있다.\n그리고 우물 밑으로 뛰어들기 전에, 산탄총을 꼭 합법적으로 소지할 필요는 없다는 걸 기억하라."
  },
  Stage_130111_Name = {
    Text = "우물·둘째"
  },
  Stage_130112_Desc = {
    Text = "맞아요, 전설적인 조사원이라도 매번 승리할 수 있는 건 아니죠.\n……하지만 괜찮아요, 보드카가 마지막 한 방울 남아 있으니까요."
  },
  Stage_130112_Name = {
    Text = "마지막 한 잔·지네"
  },
  Stage_130113_Desc = {
    Text = "사랑하는 사람들이 함께 저녁 식사를 하며 서로의 마음을 털어놓습니다.\n음식은 많은 비밀을 들었지만, 당연하게도 그들은 결코 말하지 않습니다."
  },
  Stage_130113_Name = {
    Text = "식탁·지네"
  },
  Stage_130114_Desc = {
    Text = "사람도 학교에 다니고, 깨어남체도 학교에 다닌다.\n이제 그녀는 깨어남체가 되었으니, 당연히 학교에 다녀야 한다.\n안전에 각별히 유의하시기 바랍니다."
  },
  Stage_130114_Name = {
    Text = "학교·광기"
  },
  Stage_130115_Desc = {
    Text = "사람도 학교에 다니고, 깨어남체도 학교에 다닌다.\n이제 그녀는 깨어남체가 되었으니, 당연히 학교에 다녀야 한다.\n안전에 각별히 유의하시기 바랍니다."
  },
  Stage_130115_Name = {
    Text = "학교· 세 번째"
  },
  Stage_130116_Desc = {
    Text = "천장을 좋아하는 색으로 칠하고, 벽도 좋아하는 색으로 칠하세요.\n냉장고를 좋아하는 음식으로 가득 채우고, 우리 둘 다 좋아하는 반려동물을 키우세요.\n이곳은 오직 당신과 나만의 집입니다."
  },
  Stage_130116_Name = {
    Text = "집·여섯 번째"
  },
  Stage_130117_Desc = {
    Text = "사랑하는 사람들이 함께 저녁 식사를 하며 서로의 마음을 털어놓습니다.\n음식은 많은 비밀을 들었지만, 당연하게도 그들은 결코 말하지 않습니다."
  },
  Stage_130117_Name = {
    Text = "식탁· 세 번째"
  },
  Stage_130118_Desc = {
    Text = "병원은 믿기 어려운 곳으로, 신생, 이별, 재생, 세상에서 가장 큰 고통과 세상에서 가장 큰 기쁨이 한데 모여 있습니다.\n그러나 사람들의 기쁨, 슬픔, 그리고 모든 감정은 서로 간에 전혀 통하지 않습니다."
  },
