  },
  Stage_130124_Desc = {
    Text = "세계가 순식간에 지옥으로 변한다——정말 그런 걸까?\n어쩌면 세계는 한 번도 변한 적이 없고, 단지 그 전까지 당신이 줄곧 참아왔던 것은 아닐까."
