  },
  Stage_130147_Desc = {
    Text = "어떻게 전설적인 조사관이 될 수 있을까? 우선, 모든 깊은 우물에는 수많은 비밀이 숨겨져 있다.\n그리고 우물 밑으로 뛰어들기 전에, 산탄총을 꼭 합법적으로 소지할 필요는 없다는 걸 기억하라."
  },
  Stage_130147_Name = {
    Text = "우물·중 하나"
  },
  Stage_130148_Desc = {
    Text = "모든 비는 그치고, 모든 꿈은 끝난다.\n한 모금만 더 축축한 공기를 들이마시며, 비의 여운이 조금 더 늦게 떠나도록 하자."
  },
  Stage_130148_Name = {
    Text = "비 갠 후"
  },
  Stage_130149_Desc = {
    Text = "맞아요, 전설적인 조사원이라도 매번 승리할 수 있는 건 아니죠.\n……하지만 괜찮아요, 보드카가 마지막 한 방울 남아 있으니까요."
  },
  Stage_130149_Name = {
    Text = "마지막 한 잔·중 하나"
  },
  Stage_130150_Desc = {
    Text = "맞아요, 전설적인 조사원이라도 매번 승리할 수 있는 건 아니죠.\n……하지만 괜찮아요, 보드카가 마지막 한 방울 남아 있으니까요."
  },
  Stage_130150_Name = {
    Text = "마지막 한 잔· 세 번째"
  },
  Stage_130151_Desc = {
    Text = "맞아요, 전설적인 조사원이라도 매번 승리할 수 있는 건 아니죠.\n……하지만 괜찮아요, 보드카가 마지막 한 방울 남아 있으니까요."
  },
  Stage_130151_Name = {
    Text = "마지막 한 잔· 다섯"
  },
  Stage_130152_Desc = {
    Text = "사랑하는 사람들이 함께 저녁 식사를 하며 서로의 마음을 털어놓습니다.\n음식은 많은 비밀을 들었지만, 당연하게도 그들은 결코 말하지 않습니다."
  },
  Stage_130152_Name = {
    Text = "식탁·중 하나"
  },
  Stage_130153_Desc = {
    Text = "씨앗은 텍스트에서 사랑의 정의를 탐구한다.\n하지만 누구도 사랑이 무엇인지 명확히 말할 수 없고, 다만 사랑이 아닌 감정들을 부정할 수 있을 뿐.\n그것에 맹렬히 관통당하는 찰나까지는."
  },
  Stage_130153_Name = {
    Text = "「사랑」"
  },
  Stage_130154_Desc = {
    Text = "세계가 순식간에 지옥으로 변한다——정말 그런 걸까?\n어쩌면 세계는 한 번도 변한 적이 없고, 단지 그 전까지 당신이 줄곧 참아왔던 것은 아닐까."
  },
  Stage_130154_Name = {
    Text = "뇌 손상·광기"
  },
  Stage_130155_Desc = {
    Text = "노래처럼, 시처럼, 꿈처럼."
  },
  Stage_130155_Name = {
    Text = "심상풍경"
  },
  Stage_130156_Desc = {
    Text = "천장을 좋아하는 색으로 칠하고, 벽도 좋아하는 색으로 칠하세요.\n냉장고를 좋아하는 음식으로 가득 채우고, 우리 둘 다 좋아하는 반려동물을 키우세요.\n이곳은 오직 당신과 나만의 집입니다."
  },
  Stage_130156_Name = {
    Text = "집·세 번째"
  },
  Stage_130157_Desc = {
    Text = "천장을 좋아하는 색으로 칠하고, 벽도 좋아하는 색으로 칠하세요.\n냉장고를 좋아하는 음식으로 가득 채우고, 우리 둘 다 좋아하는 반려동물을 키우세요.\n이곳은 오직 당신과 나만의 집입니다."
  },
  Stage_130157_Name = {
    Text = "집·다섯 번째"
  },
  Stage_130158_Desc = {
    Text = "병원은 믿기 어려운 곳으로, 신생, 이별, 재생, 세상에서 가장 큰 고통과 세상에서 가장 큰 기쁨이 한데 모여 있습니다.\n그러나 사람들의 기쁨, 슬픔, 그리고 모든 감정은 서로 간에 전혀 통하지 않습니다."
  },
  Stage_130158_Name = {
    Text = "병원·여섯 번째"
  },
  Stage_130159_Desc = {
    Text = "사람도 학교에 다니고, 깨어남체도 학교에 다닌다.\n이제 그녀는 깨어남체가 되었으니, 당연히 학교에 다녀야 한다.\n안전에 각별히 유의하시기 바랍니다."
  },
  Stage_130159_Name = {
    Text = "학교·지네"
  },
  Stage_130160_Desc = {
    Text = "병원은 믿기 어려운 곳으로, 신생, 이별, 재생, 세상에서 가장 큰 고통과 세상에서 가장 큰 기쁨이 한데 모여 있습니다.\n그러나 사람들의 기쁨, 슬픔, 그리고 모든 감정은 서로 간에 전혀 통하지 않습니다."
  },
  Stage_130160_Name = {
    Text = "병원·세 번째"
  },
  Stage_130161_Desc = {
    Text = "천만 개의 꿈속에서, 당신은 그녀의 손을 잡는다.\n은밀한 전류가 당신들의 연결을 관통하며, 영원히 사라지지 않는 순환을 이룬다.\n그 부름에 귀를 기울여라, 그녀를 찾아라, 그녀를 발견하라.\n설령 혈육에 삼켜질지라도."
  },
  Stage_130161_Name = {
    Text = "피ﾝ와ｲw살ｮ"
  },
  Stage_130162_Desc = {
    Text = "사람도 학교에 다니고, 깨어남체도 학교에 다닌다.\n이제 그녀는 깨어남체가 되었으니, 당연히 학교에 다녀야 한다.\n안전에 각별히 유의하시기 바랍니다."
  },
  Stage_130162_Name = {
    Text = "학교· 육"
  },
  Stage_130163_Desc = {
    Text = "세계가 순식간에 지옥으로 변한다——정말 그런 걸까?\n어쩌면 세계는 한 번도 변한 적이 없고, 단지 그 전까지 당신이 줄곧 참아왔던 것은 아닐까."
  },
  Stage_130163_Name = {
    Text = "뇌 손상· 육"
  },
  Stage_130372_Name = {
    Text = "사토구야 트라이얼 스테이지"
  },
  Stage_130373_Name = {
    Text = "사야 트라이얼 스테이지"
  },
  Stage_130784_Desc = {
    Text = "친구, 친구! 헤헤, 친구! 너에게, 고기"
  },
  Stage_130784_Name = {
    Text = "동료 발견·세 번째"
  },
  Stage_130785_Desc = {
    Text = "검고, 부드럽고, 좋아요"
  },
  Stage_130785_Name = {
    Text = "떠다니는 보물·광기"
  },
  Stage_130786_Desc = {
    Text = "친구, 친구! 헤헤, 친구! 너에게, 고기"
  },
  Stage_130786_Name = {
    Text = "동료 발견·둘째"
  },
  Stage_130787_Desc = {
    Text = "모든 것, 끝, 모스크, 실타래패, 모스크, 승리! 모스크, … 집에 가야 해."
  },
  Stage_130787_Name = {
