  },
  Stage_130790_Name = {
    Text = "동료 발견·중 하나"
  },
  Stage_130791_Desc = {
    Text = "물고기 잡기, 먹기, 열매, 먹기, 조개 주워서, 숨기기, 자"
  },
  Stage_130791_Name = {
    Text = "평범한 매일·육"
  },
  Stage_130792_Desc = {
    Text = "모든 것, 끝, 모스크, 실타래패, 모스크, 승리! 모스크, … 집에 가야 해."
  },
  Stage_130792_Name = {
    Text = "귀환의 길·중 하나"
  },
  Stage_130793_Desc = {
    Text = "폭우가 왔다, 모스크는 두렵지 않다! 천둥소리가 정말 크다, 모스크는 두렵지 않다! 친구가 말한다, 이것은 승리의 전조다"
  },
  Stage_130793_Name = {
    Text = "우레의 포효·광기"
  },
  Stage_130794_Desc = {
    Text = "꿀꿀——꿀꿀——\n배가 너무 고파, 큰 녀석은 어디 갔어?\n너가 고기를 한 덩어리 가져왔다고? \n고기, 고기가 움직였어! 큰 녀석!\n"
  },
  Stage_130794_Name = {
    Text = "글루——글루——"
  },
  Stage_130795_Desc = {
    Text = "폭우가 왔다, 모스크는 두렵지 않다! 천둥소리가 정말 크다, 모스크는 두렵지 않다! 친구가 말한다, 이것은 승리의 전조다"
  },
  Stage_130795_Name = {
