  Stage_130816_Desc = {
    Text = "Mosk 출발! 친구 출발! 작은 석탄 공, 출발"
  },
  Stage_130816_Name = {
    Text = "출항 시각·세 번째"
  },
  Stage_130817_Desc = {
    Text = "심연이 포효하고, 소용돌이가 호출하지만, Mosk는 친구를 위해, 전·진·해"
  },
  Stage_130817_Name = {
    Text = "대·소용·돌이·둘째"
  },
  Stage_130818_Desc = {
    Text = "친구, 친구! 헤헤, 친구! 너에게, 고기"
  },
  Stage_130818_Name = {
    Text = "동료 발견·육"
  },
  Stage_130819_Desc = {
    Text = "햇살이 창문을 통과해 오크 나무 향이 나는 책상에 내리쬐었다.\n책들이 한쪽에 흩어져 있고, Mosk가 느긋하게 책상에 엎드려 있었다.\n「노틸라 Zzz……작은 석탄 공 Zzz……기뻐~」\n오랫동안 계속된 추위와 외로움은 끝났다.\n다음은 더 더 좋은 내일이다."
  },
  Stage_130819_Name = {
    Text = "좋아, 더 좋아, 더더 좋아"
  },
  Stage_130820_Desc = {
    Text = "물고기 잡기, 먹기, 열매, 먹기, 조개 주워서, 숨기기, 자"
  },
  Stage_130820_Name = {
    Text = "평범한 매일·지네"
  },
  Stage_130821_Desc = {
    Text = "모든 것, 끝, 모스크, 실타래패, 모스크, 승리! 모스크, … 집에 가야 해."
  },
  Stage_130821_Name = {
    Text = "귀환의 길·둘째"
  },
  Stage_130823_Desc = {
    Text = "모든 것, 끝, 모스크, 실타래패, 모스크, 승리! 모스크, … 집에 가야 해."
  },
  Stage_130823_Name = {
    Text = "귀환의 길·지오"
  },
  Stage_130824_Desc = {
    Text = "탁. \n 비가 배에 떨어져서 소리가 너무 크다. \n 모스크, 이런 게 싫어. \n 탁."
  },
  Stage_130824_Name = {Text = "탁, 탁."},
  Stage_130825_Desc = {
    Text = "화라~화라~\n「찍!(잡아라, 큰 녀석!)」\n「흥흥, 작은 석탄 공, 천천히!」\n화라~화라~\n「Mosk! 기다려, 잠깐, 시원해.」\n「친구, 놀러 와!」\n"
  },
  Stage_130825_Name = {
    Text = "화라~화라~"
  },
  Stage_130826_Desc = {
