  },
  Stage_130836_Name = {
    Text = "동료 발견·지오"
  },
  Stage_130837_Desc = {
    Text = "친구, 친구! 헤헤, 친구! 너에게, 고기"
  },
  Stage_130837_Name = {
    Text = "동료 발견·지네"
  },
  Stage_130838_Desc = {
    Text = "모든 것, 끝, 모스크, 실타래패, 모스크, 승리! 모스크, … 집에 가야 해."
