  Stage_130838_Name = {
    Text = "귀환의 길·육"
  },
  Stage_130839_Desc = {
    Text = "검고, 부드럽고, 좋아요"
  },
  Stage_130839_Name = {
    Text = "떠내려가는 보물·지오"
  },
  Stage_130840_Desc = {
    Text = "심연이 포효하고, 소용돌이가 호출하지만, Mosk는 친구를 위해, 전·진·해"
  },
  Stage_130840_Name = {
    Text = "대·소용돌이·세 번째"
  },
  Stage_131105_Desc = {
    Text = "불멸의 감옥은, 죄수의 손으로 직접 엮어낸 것.\n그녀들은 영원히 엮는다. 그녀들은 결코 벗어나지 못한다."
  },
  Stage_131105_Name = {Text = "고치"},
  Stage_132466_Desc = {
    Text = "내부 테스트 전용"
  },
  Stage_132466_Name = {
    Text = "테스트 환경·망각편"
  },
  Stage_139577_Desc = {
    Text = "너무 좋아, 이것들은……아니아니, 이 검은 고양이들은 너무 나쁘다고!"
  },
  Stage_139577_Name = {
    Text = "블랙 골드 러시"
  },
  Stage_139578_Desc = {
    Text = "은심과 금권으로 주머니를 가득 채우고, 승리한 장군은 만선으로 돌아간다."
  },
  Stage_139578_Name = {
    Text = "만선의 귀환"
  },
  Stage_139579_Desc = {
    Text = "네가 가장 큰 고양이를 노렸고, 그 녀석도 너를 노리고 있었다."
  },
  Stage_139579_Name = {
    Text = "거대한 놈"
  },
  Stage_139580_Desc = {
    Text = "하지만 고양이는 아직 많다, 다시 한번……마지막으로?"
  },
  Stage_139580_Name = {
    Text = "한 번 더"
  },
  Stage_139581_Desc = {
    Text = "칠흑의 바다에서 첫 줄기 은빛이 빛나는 순간, 네 손의 고양이 포획망이 더욱 힘차게 휘둘러졌다."
  },
  Stage_139581_Name = {
    Text = "첫 번째 은심 한 통"
  },
  Stage_139582_Desc = {
    Text = "검은 고양이가 너에게 저항한다면, 네가 제대로 하고 있다는 뜻이다."
  },
  Stage_139582_Name = {
    Text = "체포 거부"
  },
  Stage_139583_Desc = {
    Text = "그물이 클수록 고양이도 많아진다. 큰 고양이에겐 큰 그물을, 올려!"
  },
  Stage_139583_Name = {
    Text = "그물 올려! 그물 올려!"
  },
  Stage_140299_Desc = {
    Text = "피어나라, 날아올라라.\n앞길이 아무리 험난하더라도, 그녀의 손을 놓지 않겠다고 결심했다.\n우리가 이별하는 순간, 뒤틀린 세계를 「진실타래」로 가득 채우리라."
  },
  Stage_140299_Name = {Text = "작별"},
  Stage_140300_Desc = {
    Text = "기억은 하나의 씨앗과 같아, 만물을 품고 있으나 비밀에 부친다.\n물을 주어 뿌리내리고 싹을 틔울 때까지, 대지가 그것을 받아들이고 포용하여 현실타래에서 힘을 끌어올리도록 허락할 때까지."
  },
  Stage_140300_Name = {
    Text = "「기억」"
  },
  Stage_140301_Desc = {
    Text = "기억은 하나의 씨앗과 같아, 만물을 품고 있으나 비밀에 부친다.\n물을 주어 뿌리내리고 싹을 틔울 때까지, 대지가 그것을 받아들이고 포용하여 현실타래에서 힘을 끌어올리도록 허락할 때까지."
  },
  Stage_140301_Name = {
