  },
  Stage_141235_Desc = {
    Text = "너는 놀음을 하는 걸 좋아하고, 모든 것을 희극으로 여기지. \n그러니 우리는 그 신도들의 목을 베고 척추를 짓밟아, 그들이 얼마나 우스꽝스러운 더러운 대상을 믿고 있었는지 깨닫게 해주겠다. \n계속 도망치거라, 그렇지 않으면 멸망조차 아름다운 망상에 불과하다는 것을 알게 될 테니."
  },
  Stage_141235_Name = {
    Text = "추격 게임·중 하나"
  },
  Stage_141236_Desc = {
    Text = "쉽게 얻을 수 있고, 맛있고, 단단하고, 촘촘하고, 숨 막히는 것.\n그러나 연약하다.\n그것이 바로 여기에 존재한다."
  },
  Stage_141236_Name = {
    Text = "늑연골· 육"
  },
  Stage_141237_Desc = {
    Text = "그래, 당연히 알고 있었다. 처음부터 끝까지, 「나」만 있었을 뿐, 「우리」는 없었으니까."
  },
  Stage_141237_Name = {
    Text = "고백·매드니스"
  },
  Stage_141238_Desc = {
    Text = "사냥꾼과 사냥감의 입장은 순식간에 뒤바뀐다. 그 순환은 한쪽이 도구를 사용하는 법을 배우고, 다른 한쪽이 진정한 힘을 터득할 때까지 수천 년동안 이어지며 반복되었다."
  },
  Stage_141238_Name = {
    Text = "숲의 법전· 다섯"
  },
  Stage_141239_Desc = {
    Text = "그는 바다보다 더 오래된 존재에게 선택받았고, 결코 돌아갈 수 없는 그곳에 남겨졌다."
  },
  Stage_141239_Name = {
    Text = "호루라기 소리· 육"
  },
  Stage_141240_Desc = {
    Text = "가장 화려한 축제를 위한 가장 활기찬 음식, 우리는 잔을 들고 함께 모인다.\n아무도 그 육체들 뒤에 같은 의지가 있는지 신경 쓰지 않으며, 속이 빈 껍데기 안에 영혼이 남아 있는지도 묻지 않는다."
  },
  Stage_141240_Name = {
    Text = "맥주와 향신료·지네"
  },
  Stage_141241_Desc = {
    Text = "가장 화려한 축제를 위한 가장 활기찬 음식, 우리는 잔을 들고 함께 모인다.\n아무도 그 육체들 뒤에 같은 의지가 있는지 신경 쓰지 않으며, 속이 빈 껍데기 안에 영혼이 남아 있는지도 묻지 않는다."
  },
  Stage_141241_Name = {
    Text = "맥주와 향신료· 세 번째"
  },
  Stage_141242_Desc = {
