  },
  Stage_141245_Desc = {
    Text = "너는 놀음을 하는 걸 좋아하고, 모든 것을 희극으로 여기지. \n그러니 우리는 그 신도들의 목을 베고 척추를 짓밟아, 그들이 얼마나 우스꽝스러운 더러운 대상을 믿고 있었는지 깨닫게 해주겠다. \n계속 도망치거라, 그렇지 않으면 멸망조차 아름다운 망상에 불과하다는 것을 알게 될 테니."
