  },
  Stage_141248_Desc = {
    Text = "「자유의지」. 그는 저 재미있는 단어를 눈여겨보고는, 펜끝으로 그걸 살짝 지워버렸다.\n그러고선 다른 글귀를 남겼다.\n@2의 것은 @2로 돌아가고, @2의 것은 @2로 돌아간다."
