    Text = "사냥꾼과 사냥감의 입장은 순식간에 뒤바뀐다. 그 순환은 한쪽이 도구를 사용하는 법을 배우고, 다른 한쪽이 진정한 힘을 터득할 때까지 수천 년동안 이어지며 반복되었다."
