  Stage_141251_Desc = {
    Text = "아이들이 듣기에 적합하지 않은 또 다른 이야기 속에서, 어린 야거 역시 영원히 행복한 결말을 맞이합니다."
  },
  Stage_141251_Name = {Text = "거짓말"},
  Stage_141252_Desc = {
    Text = "그래, 당연히 알고 있었다. 처음부터 끝까지, 「나」만 있었을 뿐, 「우리」는 없었으니까."
  },
  Stage_141252_Name = {
    Text = "고백· 육"
  },
  Stage_141253_Desc = {
    Text = "너는 놀음을 하는 걸 좋아하고, 모든 것을 희극으로 여기지. \n그러니 우리는 그 신도들의 목을 베고 척추를 짓밟아, 그들이 얼마나 우스꽝스러운 더러운 대상을 믿고 있었는지 깨닫게 해주겠다. \n계속 도망치거라, 그렇지 않으면 멸망조차 아름다운 망상에 불과하다는 것을 알게 될 테니."
  },
  Stage_141253_Name = {
    Text = "추격 게임· 세 번째"
  },
  Stage_141254_Desc = {
    Text = "그는 그녀에게 한 가지 실타래수를 저질렀습니다.\n그는 그에게 같은 실타래수를 절대 반복하지 않을 것입니다."
  },
  Stage_141254_Name = {
    Text = "그녀와 그"
  },
  Stage_141255_Desc = {
