  },
  Stage_141263_Name = {
    Text = "호루라기 소리·지네"
  },
  Stage_141264_Desc = {
    Text = "사냥꾼과 사냥감의 입장은 순식간에 뒤바뀐다. 그 순환은 한쪽이 도구를 사용하는 법을 배우고, 다른 한쪽이 진정한 힘을 터득할 때까지 수천 년동안 이어지며 반복되었다."
  },
  Stage_141264_Name = {
    Text = "숲의 법전·둘째"
  },
  Stage_141265_Desc = {
    Text = "이웃의 수군거림, 부모의 말 못 다 한 표정, 낯선 이의 깊은 침묵.\n오해하지 마세요, 당신의 출생에는 아무런 의혹도 없습니다.\n하지만 그 전에—당신은 길들임을 생각해본 적 있나요, 하나를, 아니, 제가 말하는 건 용이 아닙니다."
