  },
  Stage_141288_Name = {
    Text = "호루라기 소리· 세 번째"
  },
  Stage_141289_Desc = {
    Text = "그는 쉽게 눈에 띄지 않고, 그는 소리 없이 다가오며, 그는 갑작스럽게 찾아옵니다.\n사람들은 활기찬 나날 속에서 남의 일처럼 그의 이름을 입에 올리다가, 어느새 깨닫습니다—그는 이미 그림자처럼 따라다니는 친구가 되어 있었습니다."
  },
  Stage_141289_Name = {Text = "원인"},
  Stage_141290_Desc = {
    Text = "가장 활기찬 음식, 축하에 가장 어울리는 음식, 우리는 잔을 들고, 우리는 모인다.\n아무도 신경 쓰지 않는다, 하나하나의 몸뚱이 아래 같은 의지가 있는지, 아무도 신경 쓰지 않는다, 하나하나의 빈 껍질 아래 아직 영혼이 있는지."
  },
  Stage_141290_Name = {
    Text = "맥주와 향신료·중 하나"
  },
  Stage_141291_Desc = {
    Text = "사냥꾼과 사냥감의 입장은 순식간에 뒤바뀐다. 그 순환은 한쪽이 도구를 사용하는 법을 배우고, 다른 한쪽이 진정한 힘을 터득할 때까지 수천 년동안 이어지며 반복되었다."
  },
  Stage_141291_Name = {
    Text = "숲의 법전·지네"
  },
  Stage_141742_Desc = {
    Text = "♪~~🎵~~♪~~🎵~~♪~~🎵~~\n외로운 새 한 마리가 있었네. 짝을 찾아 울부짖는 새, 그의 짝은 날개를 잃었고, 그의 짝은 깃털이 모두 뽑혀버렸네. 그는 이루어질 수 없는 소원을 빌었고, 그의 짝은 그와의 추억조차 잊어버리게 됐다네.\n\n♪~~🎵~~♪~~🎵~~♪~~🎵~~\n괜찮아, 괜찮아. 그들에게는 여전히 달콤하고 달콤한 함께할 안식처가 있어. 그들은 평온하고 더 평온한, 영원히 방해받지 않을 꿈속으로 빠져들 거야."
  },
  Stage_141742_Name = {
    Text = "깃털· 세 번째"
  },
  Stage_141743_Desc = {
    Text = "♪~~🎵~~♪~~🎵~~♪~~🎵~~\n외로운 새 한 마리가 있었네. 짝을 찾아 울부짖는 새, 그의 짝은 날개를 잃었고, 그의 짝은 깃털이 모두 뽑혀버렸네. 그는 이루어질 수 없는 소원을 빌었고, 그의 짝은 그와의 추억조차 잊어버리게 됐다네.\n\n♪~~🎵~~♪~~🎵~~♪~~🎵~~\n괜찮아, 괜찮아. 그들에게는 여전히 달콤하고 달콤한 함께할 안식처가 있어. 그들은 평온하고 더 평온한, 영원히 방해받지 않을 꿈속으로 빠져들 거야."
  },
  Stage_141743_Name = {
    Text = "깃털· 육"
  },
  Stage_141744_Desc = {
    Text = "내 이야기, 마음에 들었어? 마음에 안 든다고? 엥?! 도대체 어떻게 말해야 너를 믿게 할 수 있을까—— 좋아, 더 이상 캐묻지 마, 그런 건 정말 마음에 상처거든? 자, 이 사과 한 입 베어물어봐, 엄청 달아, 진짜라고 약속해! 이 이야기의 모든 글자만큼이나 진짜야!"
  },
  Stage_141744_Name = {
    Text = "사과·광기"
  },
  Stage_141745_Desc = {
    Text = "내 이야기, 마음에 들었어? 마음에 안 든다고? 엥?! 도대체 어떻게 말해야 너를 믿게 할 수 있을까—— 좋아, 더 이상 캐묻지 마, 그런 건 정말 마음에 상처거든? 자, 이 사과 한 입 베어물어봐, 엄청 달아, 진짜라고 약속해! 이 이야기의 모든 글자만큼이나 진짜야!"
  },
  Stage_141745_Name = {
    Text = "사과·둘째"
  },
  Stage_141746_Desc = {
    Text = "내 이야기, 마음에 들었어? 마음에 안 든다고? 엥?! 도대체 어떻게 말해야 너를 믿게 할 수 있을까—— 좋아, 더 이상 캐묻지 마, 그런 건 정말 마음에 상처거든? 자, 이 사과 한 입 베어물어봐, 엄청 달아, 진짜라고 약속해! 이 이야기의 모든 글자만큼이나 진짜야!"
  },
  Stage_141746_Name = {
    Text = "사과·중 하나"
  },
  Stage_141747_Desc = {
    Text = "그래, 그래, 사람은 이 정도로 불행할 수 있다. 그녀의 인생은 거짓말 외에는 아무것도 없었고, 이번엔 믿었고 다음에도 또 믿을 것이다, 그녀는 단 한 점의 희망 때문에 모든 거짓말의 쓴 열매를 삼켰다. 그리하여 이 모든 거짓말의 끝에서, 그녀 인생의 끝에서…… 우리는 그녀의 눈에서 증오 외에는 아무것도 찾을 수 없었다."
  },
  Stage_141747_Name = {
    Text = "눈·광기"
  },
  Stage_141748_Desc = {
    Text = "이야기가 여기까지 오면서, 당신은 조금 망설이기 시작했다. 단서는 분명 처음부터 있었는데, 운명이 당신을 이곳으로 이끈 것은 무엇을 목격하라는 것일까? 실타래타래의 저편에는 어떤 진실타래이 연결되어 있는 것일까? 눈 아래에는 무엇이 묻혀 있고, 과연 몇 명이나 자신이 원하는 것을 얻을 수 있을까? 당신은 알지 못한다. 여정은 아직 반도 지나지 않았고, 당신은 그 인도에 따를 수밖에 없으니."
  },
  Stage_141748_Name = {
    Text = "실타래· 육"
  },
  Stage_141749_Desc = {
    Text = "♪~~🎵~~♪~~🎵~~♪~~🎵~~\n외로운 새 한 마리가 있었네. 짝을 찾아 울부짖는 새, 그의 짝은 날개를 잃었고, 그의 짝은 깃털이 모두 뽑혀버렸네. 그는 이루어질 수 없는 소원을 빌었고, 그의 짝은 그와의 추억조차 잊어버리게 됐다네.\n\n♪~~🎵~~♪~~🎵~~♪~~🎵~~\n괜찮아, 괜찮아. 그들에게는 여전히 달콤하고 달콤한 함께할 안식처가 있어. 그들은 평온하고 더 평온한, 영원히 방해받지 않을 꿈속으로 빠져들 거야."
  },
  Stage_141749_Name = {
    Text = "깃털·지네"
  },
  Stage_141750_Desc = {
    Text = "오, 작은 신의 파편이여, 카다스의 구원자여, 모든 파멸 속의 희망이여, 모든 절망 속의 새로운 생명이여, 미사그의 유일한 수호자여. 당신은 지금까지 함께해온 열쇠를 꼭 쥐었고, 너의 마음은 결의로 가득 차 있다. 좋아, 그 말이 어떻게 되었더라……? 은열쇠가 우리를 인도하길!"
  },
  Stage_141750_Name = {
    Text = "열쇠· 세 번째"
  },
  Stage_141751_Desc = {
    Text = "♪~~🎵~~♪~~🎵~~♪~~🎵~~\n조그만 소녀가 너무나 오랫동안 길을 걸어왔어, 외로움이 그녀의 어깨를 짓누르고, 그리움이 그녀의 마음을 갉아먹고 있어. 그녀는 어디서도 찾을 수 없어, 어떤 방법도 통하지 않아.\n\n♪~~🎵~~♪~~🎵~~♪~~🎵~~\n괜찮아, 괜찮아, 소녀가 찾는 모든 것은 거울 속에 있어, 거울은 하늘의 달을 비추고, 달은 거울 속 잔물결에 빠져들었어."
  },
  Stage_141751_Name = {
    Text = "거울·중 하나"
  },
  Stage_141752_Desc = {
    Text = "다른 모든 것은 우리가 잘 알지만, 왕관은 도대체 이 장소에 왜 나타난 것일까, 누가 그렇게 부주의해서 사기꾼의 꾀에 넘어간 것일까? 이것은 분명 이 부분에서 우리가 고려할 내용이 아니다, 앞으로의 이야기가 궁금하다면…… 다음 시간에 계속, 모리멘스 잠금!"
  },
  Stage_141752_Name = {
    Text = "왕관·지네"
