    Text = "오, 작은 신의 파편이여, 카다스의 구원자여, 모든 파멸 속의 희망이여, 모든 절망 속의 새로운 생명이여, 미사그의 유일한 수호자여. 당신은 지금까지 함께해온 열쇠를 꼭 쥐었고, 너의 마음은 결의로 가득 차 있다. 좋아, 그 말이 어떻게 되었더라……? 은열쇠가 우리를 인도하길!"
  },
  Stage_141768_Name = {
    Text = "열쇠·중 하나"
  },
  Stage_141769_Desc = {
    Text = "그래, 그래, 사람은 이 정도로 불행할 수 있다. 그녀의 인생은 거짓말 외에는 아무것도 없었고, 이번엔 믿었고 다음에도 또 믿을 것이다, 그녀는 단 한 점의 희망 때문에 모든 거짓말의 쓴 열매를 삼켰다. 그리하여 이 모든 거짓말의 끝에서, 그녀 인생의 끝에서…… 우리는 그녀의 눈에서 증오 외에는 아무것도 찾을 수 없었다."
  },
  Stage_141769_Name = {
    Text = "눈·둘째"
  },
  Stage_141770_Desc = {
    Text = "다른 모든 것은 우리가 잘 알지만, 왕관은 도대체 이 장소에 왜 나타난 것일까, 누가 그렇게 부주의해서 사기꾼의 꾀에 넘어간 것일까? 이것은 분명 이 부분에서 우리가 고려할 내용이 아니다, 앞으로의 이야기가 궁금하다면…… 다음 시간에 계속, 모리멘스 잠금!"
  },
  Stage_141770_Name = {
    Text = "왕관·중 하나"
  },
  Stage_141771_Desc = {
    Text = "그래, 그래, 사람은 이 정도로 불행할 수 있다. 그녀의 인생은 거짓말 외에는 아무것도 없었고, 이번엔 믿었고 다음에도 또 믿을 것이다, 그녀는 단 한 점의 희망 때문에 모든 거짓말의 쓴 열매를 삼켰다. 그리하여 이 모든 거짓말의 끝에서, 그녀 인생의 끝에서…… 우리는 그녀의 눈에서 증오 외에는 아무것도 찾을 수 없었다."
  },
  Stage_141771_Name = {
    Text = "눈·지네"
  },
  Stage_141772_Desc = {
    Text = "내 이야기, 마음에 들었어? 마음에 안 든다고? 엥?! 도대체 어떻게 말해야 너를 믿게 할 수 있을까—— 좋아, 더 이상 캐묻지 마, 그런 건 정말 마음에 상처거든? 자, 이 사과 한 입 베어물어봐, 엄청 달아, 진짜라고 약속해! 이 이야기의 모든 글자만큼이나 진짜야!"
  },
  Stage_141772_Name = {
    Text = "사과· 육"
  },
  Stage_141773_Desc = {
    Text = "이야기가 여기까지 오면서, 당신은 조금 망설이기 시작했다. 단서는 분명 처음부터 있었는데, 운명이 당신을 이곳으로 이끈 것은 무엇을 목격하라는 것일까? 실타래타래의 저편에는 어떤 진실타래이 연결되어 있는 것일까? 눈 아래에는 무엇이 묻혀 있고, 과연 몇 명이나 자신이 원하는 것을 얻을 수 있을까? 당신은 알지 못한다. 여정은 아직 반도 지나지 않았고, 당신은 그 인도에 따를 수밖에 없으니."
  },
  Stage_141773_Name = {
    Text = "실타래·중 하나"
  },
