  },
  Stage_141779_Desc = {
    Text = "이야기가 여기까지 오면서, 당신은 조금 망설이기 시작했다. 단서는 분명 처음부터 있었는데, 운명이 당신을 이곳으로 이끈 것은 무엇을 목격하라는 것일까? 실타래타래의 저편에는 어떤 진실타래이 연결되어 있는 것일까? 눈 아래에는 무엇이 묻혀 있고, 과연 몇 명이나 자신이 원하는 것을 얻을 수 있을까? 당신은 알지 못한다. 여정은 아직 반도 지나지 않았고, 당신은 그 인도에 따를 수밖에 없으니."
  },
  Stage_141779_Name = {
    Text = "실타래·지네"
  },
  Stage_141780_Desc = {
    Text = "이야기가 여기까지 오면서, 당신은 조금 망설이기 시작했다. 단서는 분명 처음부터 있었는데, 운명이 당신을 이곳으로 이끈 것은 무엇을 목격하라는 것일까? 실타래타래의 저편에는 어떤 진실타래이 연결되어 있는 것일까? 눈 아래에는 무엇이 묻혀 있고, 과연 몇 명이나 자신이 원하는 것을 얻을 수 있을까? 당신은 알지 못한다. 여정은 아직 반도 지나지 않았고, 당신은 그 인도에 따를 수밖에 없으니."
  },
  Stage_141780_Name = {
    Text = "실타래· 다섯"
  },
  Stage_141781_Desc = {
    Text = "♪~~🎵~~♪~~🎵~~♪~~🎵~~\n조그만 소녀가 너무나 오랫동안 길을 걸어왔어, 외로움이 그녀의 어깨를 짓누르고, 그리움이 그녀의 마음을 갉아먹고 있어. 그녀는 어디서도 찾을 수 없어, 어떤 방법도 통하지 않아.\n\n♪~~🎵~~♪~~🎵~~♪~~🎵~~\n괜찮아, 괜찮아, 소녀가 찾는 모든 것은 거울 속에 있어, 거울은 하늘의 달을 비추고, 달은 거울 속 잔물결에 빠져들었어."
  },
  Stage_141781_Name = {
    Text = "거울·광기"
  },
  Stage_141782_Desc = {
    Text = "내 이야기, 마음에 들었어? 마음에 안 든다고? 엥?! 도대체 어떻게 말해야 너를 믿게 할 수 있을까—— 좋아, 더 이상 캐묻지 마, 그런 건 정말 마음에 상처거든? 자, 이 사과 한 입 베어물어봐, 엄청 달아, 진짜라고 약속해! 이 이야기의 모든 글자만큼이나 진짜야!"
  },
  Stage_141782_Name = {
    Text = "사과·지네"
  },
  Stage_141783_Desc = {
    Text = "♪~~🎵~~♪~~🎵~~♪~~🎵~~\n외로운 새 한 마리가 있었네. 짝을 찾아 울부짖는 새, 그의 짝은 날개를 잃었고, 그의 짝은 깃털이 모두 뽑혀버렸네. 그는 이루어질 수 없는 소원을 빌었고, 그의 짝은 그와의 추억조차 잊어버리게 됐다네.\n\n♪~~🎵~~♪~~🎵~~♪~~🎵~~\n괜찮아, 괜찮아. 그들에게는 여전히 달콤하고 달콤한 함께할 안식처가 있어. 그들은 평온하고 더 평온한, 영원히 방해받지 않을 꿈속으로 빠져들 거야."
  },
  Stage_141783_Name = {
    Text = "깃털·광기"
  },
  Stage_141784_Desc = {
    Text = "♪~~🎵~~♪~~🎵~~♪~~🎵~~\n외로운 새 한 마리가 있었네. 짝을 찾아 울부짖는 새, 그의 짝은 날개를 잃었고, 그의 짝은 깃털이 모두 뽑혀버렸네. 그는 이루어질 수 없는 소원을 빌었고, 그의 짝은 그와의 추억조차 잊어버리게 됐다네.\n\n♪~~🎵~~♪~~🎵~~♪~~🎵~~\n괜찮아, 괜찮아. 그들에게는 여전히 달콤하고 달콤한 함께할 안식처가 있어. 그들은 평온하고 더 평온한, 영원히 방해받지 않을 꿈속으로 빠져들 거야."
