  Stage_142924_Desc = {
    Text = "모의 전투"
  },
  Stage_142924_Name = {
    Text = "모의전 테스트"
  },
  Stage_143314_Desc = {
    Text = "그는 그녀에게 한 가지 실타래수를 저질렀습니다.\n그는 그에게 같은 실타래수를 절대 반복하지 않을 것입니다."
  },
  Stage_143314_Name = {
    Text = "그녀와 그"
  },
  Stage_143315_Desc = {
    Text = "그는 그녀에게 한 가지 실타래수를 저질렀습니다.\n그는 그에게 같은 실타래수를 절대 반복하지 않을 것입니다."
  },
  Stage_143315_Name = {
    Text = "그녀와 그"
  },
  Stage_143876_Desc = {
    Text = "어떻게 전설적인 조사관이 될 수 있을까? 우선, 모든 깊은 우물에는 수많은 비밀이 숨겨져 있다.\n그리고 우물 밑으로 뛰어들기 전에, 산탄총을 꼭 합법적으로 소지할 필요는 없다는 걸 기억하라."
  },
  Stage_143876_Name = {
    Text = "우물· 육"
  },
  Stage_143877_Desc = {
    Text = "사람도 학교에 다니고, 깨어남체도 학교에 다닌다.\n이제 그녀는 깨어남체가 되었으니, 당연히 학교에 다녀야 한다.\n안전에 각별히 유의하시기 바랍니다."
  },
  Stage_143877_Name = {
    Text = "학교· 육"
  },
  Stage_143878_Desc = {
    Text = "맞아요, 전설적인 조사원이라도 매번 승리할 수 있는 건 아니죠.\n……하지만 괜찮아요, 보드카가 마지막 한 방울 남아 있으니까요."
  },
  Stage_143878_Name = {
    Text = "마지막 한 잔· 육"
  },
  Stage_143879_Desc = {
    Text = "세계가 순식간에 지옥으로 변한다——정말 그런 걸까?\n어쩌면 세계는 한 번도 변한 적이 없고, 단지 그 전까지 당신이 줄곧 참아왔던 것은 아닐까."
  },
  Stage_143879_Name = {
    Text = "뇌 손상·중 하나"
  },
  Stage_143880_Desc = {
    Text = "병원은 믿기 어려운 곳으로, 신생, 이별, 재생, 세상에서 가장 큰 고통과 세상에서 가장 큰 기쁨이 한데 모여 있습니다.\n그러나 사람들의 기쁨, 슬픔, 그리고 모든 감정은 서로 간에 전혀 통하지 않습니다."
  },
  Stage_143880_Name = {
    Text = "병원·여섯 번째"
  },
  Stage_143881_Desc = {
    Text = "병원은 믿기 어려운 곳으로, 신생, 이별, 재생, 세상에서 가장 큰 고통과 세상에서 가장 큰 기쁨이 한데 모여 있습니다.\n그러나 사람들의 기쁨, 슬픔, 그리고 모든 감정은 서로 간에 전혀 통하지 않습니다."
  },
  Stage_143881_Name = {
    Text = "병원·광기"
  },
  Stage_143882_Desc = {
    Text = "어떻게 전설적인 조사관이 될 수 있을까? 우선, 모든 깊은 우물에는 수많은 비밀이 숨겨져 있다.\n그리고 우물 밑으로 뛰어들기 전에, 산탄총을 꼭 합법적으로 소지할 필요는 없다는 걸 기억하라."
  },
  Stage_143882_Name = {
    Text = "우물·광기"
  },
  Stage_143883_Desc = {
    Text = "맞아요, 전설적인 조사원이라도 매번 승리할 수 있는 건 아니죠.\n……하지만 괜찮아요, 보드카가 마지막 한 방울 남아 있으니까요."
  },
  Stage_143883_Name = {
    Text = "마지막 한 잔·지네"
  },
  Stage_143884_Desc = {
    Text = "어떻게 전설적인 조사관이 될 수 있을까? 우선, 모든 깊은 우물에는 수많은 비밀이 숨겨져 있다.\n그리고 우물 밑으로 뛰어들기 전에, 산탄총을 꼭 합법적으로 소지할 필요는 없다는 걸 기억하라."
  },
  Stage_143884_Name = {
    Text = "우물· 다섯"
  },
  Stage_143885_Desc = {
    Text = "사람도 학교에 다니고, 깨어남체도 학교에 다닌다.\n이제 그녀는 깨어남체가 되었으니, 당연히 학교에 다녀야 한다.\n안전에 각별히 유의하시기 바랍니다."
  },
  Stage_143885_Name = {
    Text = "학교· 다섯"
  },
  Stage_143886_Desc = {
    Text = "사람도 학교에 다니고, 깨어남체도 학교에 다닌다.\n이제 그녀는 깨어남체가 되었으니, 당연히 학교에 다녀야 한다.\n안전에 각별히 유의하시기 바랍니다."
  },
  Stage_143886_Name = {
    Text = "학교·둘째"
  },
  Stage_143887_Desc = {
    Text = "세계가 순식간에 지옥으로 변한다——정말 그런 걸까?\n어쩌면 세계는 한 번도 변한 적이 없고, 단지 그 전까지 당신이 줄곧 참아왔던 것은 아닐까."
