    Text = "사랑하는 사람들이 함께 저녁 식사를 하며 서로의 마음을 털어놓습니다.\n음식은 많은 비밀을 들었지만, 당연하게도 그들은 결코 말하지 않습니다."
  },
  Stage_143921_Name = {
    Text = "식탁· 다섯"
  },
  Stage_143922_Desc = {
    Text = "어떻게 전설적인 조사관이 될 수 있을까? 우선, 모든 깊은 우물에는 수많은 비밀이 숨겨져 있다.\n그리고 우물 밑으로 뛰어들기 전에, 산탄총을 꼭 합법적으로 소지할 필요는 없다는 걸 기억하라."
  },
  Stage_143922_Name = {
    Text = "우물·중 하나"
  },
  Stage_143923_Desc = {
    Text = "어떻게 전설적인 조사관이 될 수 있을까? 우선, 모든 깊은 우물에는 수많은 비밀이 숨겨져 있다.\n그리고 우물 밑으로 뛰어들기 전에, 산탄총을 꼭 합법적으로 소지할 필요는 없다는 걸 기억하라."
  },
  Stage_143923_Name = {
    Text = "우물·지네"
  },
  Stage_143924_Desc = {
    Text = "천장을 좋아하는 색으로 칠하고, 벽도 좋아하는 색으로 칠하세요.\n냉장고를 좋아하는 음식으로 가득 채우고, 우리 둘 다 좋아하는 반려동물을 키우세요.\n이곳은 오직 당신과 나만의 집입니다."
  },
  Stage_143924_Name = {
    Text = "집·다섯 번째"
  },
  Stage_144347_Desc = {
    Text = "임시 텍스트"
  },
  Stage_144347_Name = {
    Text = "임시 텍스트"
  },
  Stage_144349_Desc = {
    Text = "임시 텍스트"
  },
  Stage_144349_Name = {
    Text = "임시 텍스트"
  },
  Stage_144350_Desc = {
    Text = "임시 텍스트"
  },
  Stage_144350_Name = {
    Text = "임시 텍스트"
  },
  Stage_144351_Desc = {
    Text = "임시 텍스트"
  },
  Stage_144351_Name = {
    Text = "임시 텍스트"
  },
  Stage_144352_Desc = {
    Text = "임시 텍스트"
  },
  Stage_144352_Name = {
    Text = "임시 텍스트"
  },
  Stage_144353_Desc = {
    Text = "임시 텍스트"
  },
  Stage_144353_Name = {
    Text = "임시 텍스트"
  },
  Stage_145312_Desc = {
    Text = "어서 와라! 별하늘의 고래의 투기장에 온 것을 환영한다! 이 살육의 전당에 겁없이 당도하였구나.\n장군, 암살자, 현상금 사냥꾼, 검투사…… 살아있는 모든 전설들이 이곳에 모여있다.\n살육하고, 동맹을 맺고, 배신하라. 네가 가진 모든 수단을 써보아라, 생존자여.\n규칙은 단 하나, 마지막까지 서 있는 자만이, 그 문을 열 수 있다."
  },
  Stage_145312_Name = {
    Text = "살육의 전당 · 4"
  },
  Stage_145313_Desc = {
    Text = "명예와 공정, 그리고 존엄…… 그런 것은 약자들이 자신을 가두기 위한 굴레일 뿐이다.\n그녀가 갈망하는 것은 오로지 더 강한 것일 뿐이다. 이 피로 물들어진 투기장 속, 그녀가 진지하게 마주할 가치가 있는 건, 단 하나밖에 없을지도 모른다."
  },
  Stage_145313_Name = {Text = "정벌"},
  Stage_145314_Desc = {
    Text = "별하늘의 고래를 기쁘게 하는 방법은 매우 간단하다. 충분히 많은 피, 충분히 강한 힘과 충분하게 강렬한 욕망들……\n만약 네가 수많은 자들의 시체를 밟고 지나왔다면, 축하한다. 네가 이 각축에 참여할 자격을 얻게 됐으니."
  },
  Stage_145314_Name = {
    Text = "근헌 · 3"
  },
  Stage_145315_Desc = {
    Text = "어서 와라! 별하늘의 고래의 투기장에 온 것을 환영한다! 이 살육의 전당에 겁없이 당도하였구나.\n장군, 암살자, 현상금 사냥꾼, 검투사…… 살아있는 모든 전설들이 이곳에 모여있다.\n살육하고, 동맹을 맺고, 배신하라. 네가 가진 모든 수단을 써보아라, 생존자여.\n규칙은 단 하나, 마지막까지 서 있는 자만이, 그 문을 열 수 있다."
  },
  Stage_145315_Name = {
    Text = "살육의 전당 · 3"
  },
  Stage_145316_Desc = {
    Text = "별하늘의 고래를 기쁘게 하는 방법은 매우 간단하다. 충분히 많은 피, 충분히 강한 힘과 충분하게 강렬한 욕망들……\n만약 네가 수많은 자들의 시체를 밟고 지나왔다면, 축하한다. 네가 이 각축에 참여할 자격을 얻게 됐으니."
  },
  Stage_145316_Name = {
    Text = "근헌 · 1"
  },
  Stage_145317_Desc = {
    Text = "모든 위험 중에서, 맹수는 가장 온화한 고리이다."
  },
  Stage_145317_Name = {
    Text = "갇혀진 짐승 · 5"
  },
  Stage_145318_Desc = {
    Text = "드디어, 너는 네가 원했던 모든 것을 얻었다. 힘, 부, 영광, 영원히 마르지 않는 권력.\n왕관에서 선혈이 흘러내려, 네 두 눈을 붉게 물들인다. 통쾌히 웃거라, 새롭게 권력에 오른 왕이여.\n이 권력의 선혈 속에는, 너를 기다리는 운명의 썩음이 도사리고 있을 것이다."
  },
  Stage_145318_Name = {
    Text = "권욕의 왕관 · 1"
  },
