  },
  Stage_145341_Desc = {
    Text = "별하늘의 고래를 기쁘게 하는 방법은 매우 간단하다. 충분히 많은 피, 충분히 강한 힘과 충분하게 강렬한 욕망들……\n만약 네가 수많은 자들의 시체를 밟고 지나왔다면, 축하한다. 네가 이 각축에 참여할 자격을 얻게 됐으니."
  },
  Stage_145341_Name = {
    Text = "근헌 · 5"
  },
  Stage_145342_Desc = {
    Text = "모든 위험 중에서, 맹수는 가장 온화한 고리이다."
  },
  Stage_145342_Name = {
    Text = "갇혀진 짐승 · 광란"
  },
  Stage_145343_Desc = {
    Text = "너는 거울 앞에 서서, 가장 사랑하는 그 사람을 본다. 부모, 아이, 가장 친한 벗, 혹은 너 자신을……\n사랑, 사실타래 레비아탄은 그 단어를 혐오한다. 대행자의 영혼은 한 점의 짐도 용납하지 않는다. 칼을 들어, 그것을 베어라.\n그 순간부터 너에게는 약점이란 존재하지 않을 것이다.\n그 순간부터 너에게는 돌아갈 길이란 존재하지 않을 것이다."
  },
  Stage_145343_Name = {
    Text = "아무도 없는 거울 · 5"
  },
  Stage_145344_Desc = {
    Text = "그 궁전의 벽은 황금으로 쌓았으며, 강에는 꿀과 술이 흐르고 있다.\n가장 강한 전사들이 이곳에 모여들었지만, 마지막 막이 울려 퍼질 때 그 모든 것을 누릴 자격이 있는 자는 오직 한 명밖에 남지 않을 것이다."
  },
  Stage_145344_Name = {
    Text = "유일한 규칙"
  },
  Stage_145345_Desc = {
    Text = "별하늘의 고래를 기쁘게 하는 방법은 매우 간단하다. 충분히 많은 피, 충분히 강한 힘과 충분하게 강렬한 욕망들……\n만약 네가 수많은 자들의 시체를 밟고 지나왔다면, 축하한다. 네가 이 각축에 참여할 자격을 얻게 됐으니."
  },
  Stage_145345_Name = {
    Text = "근헌 · 광란"
  },
  Stage_145346_Desc = {
    Text = "어서 와라! 별하늘의 고래의 투기장에 온 것을 환영한다! 이 살육의 전당에 겁없이 당도하였구나.\n장군, 암살자, 현상금 사냥꾼, 검투사…… 살아있는 모든 전설들이 이곳에 모여있다.\n살육하고, 동맹을 맺고, 배신하라. 네가 가진 모든 수단을 써보아라, 생존자여.\n규칙은 단 하나, 마지막까지 서 있는 자만이, 그 문을 열 수 있다."
  },
  Stage_145346_Name = {
    Text = "살육의 전당 · 6"
  },
  Stage_145347_Desc = {
    Text = "별하늘의 고래를 기쁘게 하는 방법은 매우 간단하다. 충분히 많은 피, 충분히 강한 힘과 충분하게 강렬한 욕망들……\n만약 네가 수많은 자들의 시체를 밟고 지나왔다면, 축하한다. 네가 이 각축에 참여할 자격을 얻게 됐으니."
  },
  Stage_145347_Name = {
    Text = "근헌 · 4"
  },
  Stage_145349_Desc = {
    Text = "모든 위험 중에서, 맹수는 가장 온화한 고리이다."
  },
  Stage_145349_Name = {
    Text = "갇혀진 짐승 · 4"
  },
  Stage_145350_Desc = {
    Text = "드디어, 너는 네가 원했던 모든 것을 얻었다. 힘, 부, 영광, 영원히 마르지 않는 권력.\n왕관에서 선혈이 흘러내려, 네 두 눈을 붉게 물들인다. 통쾌히 웃거라, 새롭게 권력에 오른 왕이여.\n이 권력의 선혈 속에는, 너를 기다리는 운명의 썩음이 도사리고 있을 것이다."
  },
  Stage_145350_Name = {
    Text = "권욕의 왕관 · 4"
  },
  Stage_145351_Desc = {
    Text = "모든 위험 중에서, 맹수는 가장 온화한 고리이다."
  },
  Stage_145351_Name = {
    Text = "갇혀진 짐승 · 1"
  },
  Stage_145352_Desc = {
    Text = "너는 거울 앞에 서서, 가장 사랑하는 그 사람을 본다. 부모, 아이, 가장 친한 벗, 혹은 너 자신을……\n사랑, 사실타래 레비아탄은 그 단어를 혐오한다. 대행자의 영혼은 한 점의 짐도 용납하지 않는다. 칼을 들어, 그것을 베어라.\n그 순간부터 너에게는 약점이란 존재하지 않을 것이다.\n그 순간부터 너에게는 돌아갈 길이란 존재하지 않을 것이다."
  },
  Stage_145352_Name = {
    Text = "아무도 없는 거울 · 3"
  },
  Stage_145353_Desc = {
    Text = "별하늘의 고래를 기쁘게 하는 방법은 매우 간단하다. 충분히 많은 피, 충분히 강한 힘과 충분하게 강렬한 욕망들……\n만약 네가 수많은 자들의 시체를 밟고 지나왔다면, 축하한다. 네가 이 각축에 참여할 자격을 얻게 됐으니."
  },
  Stage_145353_Name = {
    Text = "근헌 · 2"
  },
  Stage_145354_Desc = {
    Text = "별하늘의 고래를 기쁘게 하는 방법은 매우 간단하다. 충분히 많은 피, 충분히 강한 힘과 충분하게 강렬한 욕망들……\n만약 네가 수많은 자들의 시체를 밟고 지나왔다면, 축하한다. 네가 이 각축에 참여할 자격을 얻게 됐으니."
  },
  Stage_145354_Name = {
    Text = "근헌 · 6"
  },
  Stage_146229_Desc = {
    Text = "모든 자리가 채워졌고, 잠들어 있던 신이 마침내 웃음을 터뜨린다. 하지만, 당신들은 결코 이 잔치에 초대된 손님이 아니었다."
  },
  Stage_146229_Name = {
    Text = "잔치의 사람들"
  },
  Stage_146230_Desc = {
    Text = "설산에는 단 하나의 규칙만이 존재한다. 무슨 소리를 듣든, 대답하지 말 것."
  },
  Stage_146230_Name = {
    Text = "대답하지 말 것"
  },
  Stage_146231_Desc = {
    Text = "일곱 개의 제물, 일곱 개의 받침대, 세상의 기원으로 통하는 하나의 문. 소원은 결코 공짜로 주어지는 선물이 아니었다."
  },
  Stage_146231_Name = {
    Text = "소원 없는 첨탑"
  },
  Stage_146232_Desc = {
    Text = "새가 마침내 다른 새를 되찾았다.\n오늘 먼 길을 떠나며, 돌아올 날은 묻지 않는다."
  },
  Stage_146232_Name = {
    Text = "새들의 머나먼 여정의 시작점"
  },
  Stage_146233_Desc = {
    Text = "맑은 호수는 별빛을 비추고, 인정하기 싫은 갈망들도 비춘다. 거짓말은 불길에 던져지지만, 타고 남는 것이 반드시 진실타래인 것은 아니다."
  },
  Stage_146233_Name = {
    Text = "얼어붙지 않은 달"
  },
  Stage_146234_Desc = {
    Text = "고대 전설에 따르면, 저승의 왕은 오르페우스에게 경고했다. 절대 뒤돌아보지 말라, 돌아보면 사랑하는 아내를 영원히 잃으리라고. \n그러나 사랑하는 이의 목소리를 외면할 마음이 있었다면, 그가 어찌 그녀를 찾기 위해 수금을 안고 죽음의 강을 건너고, 어둠의 골짜기를 지나, 어두운 저승의 전당으로 걸어들어갔겠는가?"
  },
  Stage_146234_Name = {
    Text = "되돌아보다"
  },
  Stage_146235_Desc = {
    Text = "눈보라가 돌아갈 길을 막고, 낯선 동행자를 데려왔다. 어둠 깊은 곳에서 바스락거리는 소리가 났다. 마치 설산 전체가 길을 잃은 사람들을 훔쳐보고 있는 듯이."
  },
  Stage_146235_Name = {
    Text = "일곱 번째 여행자"
  },
  Stage_146236_Desc = {
    Text = "동행자는 처음부터 선행자였다. 그녀는 당신들보다 훨씬 먼저 설선 위에 도달해 있었다.\n직면하라. 처음부터, 그녀는 결코 피할 수 없는 존재였음을."
  },
  Stage_146236_Name = {Text = "선행자"},
  Stage_146237_Desc = {
    Text = "망토가 눈보라에 벗겨지며, 오랫동안 감춰온 비밀이 마침내 날개를 펼쳤다. 어떤 날개는 날기 위해만 태어난 것이 아니다."
  },
  Stage_146237_Name = {Text = "이소일"},
  Stage_146238_Desc = {
    Text = "눈보라가 돌아갈 길을 막고, 낯선 동행자를 데려왔다. 어둠 깊은 곳에서 바스락거리는 소리가 났다. 마치 설산 전체가 길을 잃은 사람들을 훔쳐보고 있는 듯이."
  },
  Stage_146238_Name = {
    Text = "일곱 번째 여행자"
  },
  Stage_146239_Desc = {
    Text = "사람들은 식량과 연료, 밧줄과 산소를 꼼꼼히 세지만서도, 행낭 속에 숨겨진 소원을 저울질하는 이는 없다."
  },
  Stage_146239_Name = {Text = "행낭"},
  Stage_146240_Desc = {
    Text = "불빛이 모든 이의 얼굴을 비추고, 각자가 품은 소원들도 비춘다. 긴 밤이 아직 끝나지 않았으니, 우리 함께 잠시 더 쉬어가자."
  },
  Stage_146240_Name = {
    Text = "화롯가의 밤이야기"
  },
  Stage_146241_Desc = {
    Text = "그 안온한 밤에 온순히 들어가지 말라."
  },
  Stage_146241_Name = {
    Text = "안온한 밤"
  },
  Stage_146242_Desc = {
    Text = "동행자는 처음부터 선행자였다. 그녀는 당신들보다 훨씬 먼저 설선 위에 도달해 있었다.\n직면하라. 처음부터, 그녀는 결코 피할 수 없는 존재였음을."
  },
  Stage_146242_Name = {Text = "선행자"},
  Stage_146243_Desc = {
    Text = "진실타래은 신의 복부를 가를 만큼 날카롭지 않다. 그리하여 거짓말쟁이와 속은 자들은 어둠 속에 함께 둘러앉아, 돌아갈 길을 찢어발길 거짓말 하나를 함께 엮어냈다."
  },
  Stage_146243_Name = {
    Text = "거짓말의 동맹"
  },
  Stage_146244_Desc = {
    Text = "망토가 눈보라에 벗겨지며, 오랫동안 감춰온 비밀이 마침내 날개를 펼쳤다. 어떤 날개는 날기 위해만 태어난 것이 아니다."
  },
  Stage_146244_Name = {Text = "이소일"},
  Stage_146245_Desc = {
    Text = "그것은 그녀가 다시는 찾을 수 없는, 본래 그녀의 것이었어야 할 봄이었다."
  },
  Stage_146245_Name = {
    Text = "또 다른 봄"
  },
  Stage_146246_Desc = {
    Text = "진실타래은 신의 복부를 가를 만큼 날카롭지 않다. 그리하여 거짓말쟁이와 속은 자들은 어둠 속에 함께 둘러앉아, 돌아갈 길을 찢어발길 거짓말 하나를 함께 엮어냈다."
