  Stage_146355_Desc = {
    Text = "모든 긴 꿈은 결국 사라진다. 모두가 동경했던 것, 모두가 갈망했던 것, 모두가 우러러보았던 것, 모두가 서 있던 것…… 꿈의 끝에서, 그것들은 모두 옛적의 재로 흩어질 것이다."
