  Stage_146928_Desc = {
    Text = "위기에 처한 공주를 기사가 구한다는 것은 누구나 아는 전통적인 이야기다."
  },
  Stage_146928_Name = {Text = "공주"},
  Stage_146929_Desc = {
    Text = "거대한 용이 깨어나고, 증오가 다시 불타오른다. 야수의 숨결이 바위 사이에서 분출되고, 전쟁의 독이 활활 타올라 지금도 꺼지지 않는다.\n대지가 우렁차게 울부짖는다."
  },
  Stage_146929_Name = {
    Text = "용의 둥지"
  },
  Stage_146930_Desc = {
    Text = "기사는 낯선 길을 걸었다. 황량한 들판과 언덕을 지나며, 오직 그림자만이 함께했다.\n어쩌면 그는 이미 죽었을지도 모른다. 그러나 증인이 없으니, 잊혀지기도 했다.\n세상은 이토록 고요하다."
  },
  Stage_146930_Name = {Text = "무덤"},
  Stage_146931_Desc = {
    Text = "사십 주야의 폭우가 땅 위에 쏟아졌다. 우리는 나아갈 수 없다, 그래도 우리는 계속 나아갈 것이다."
  },
  Stage_146931_Name = {Text = "사과 섬"},
  Stage_146932_Desc = {
    Text = "거대한 용이 깨어나고, 증오가 다시 불타오른다. 야수의 숨결이 바위 사이에서 분출되고, 전쟁의 독이 활활 타올라 지금도 꺼지지 않는다.\n대지가 우렁차게 울부짖는다."
  },
  Stage_146932_Name = {
    Text = "용의 둥지"
  },
  Stage_146933_Desc = {
    Text = "그것은 천국 정원의 뿌리와 꽃, 세상 모든 소원의 왕관, 결코 마르지 않는 풍요로움.\n잔 속의 술을 마셔라, 그러면 네가 가장 갈망하는 것을 보게 될 것이다."
  },
  Stage_146933_Name = {Text = "성배"},
  Stage_146934_Desc = {
    Text = "거대한 용이 깨어나고, 증오가 다시 불타오른다. 야수의 숨결이 바위 사이에서 분출되고, 전쟁의 독이 활활 타올라 지금도 꺼지지 않는다.\n대지가 우렁차게 울부짖는다."
  },
  Stage_146934_Name = {
    Text = "용의 둥지"
  },
