  Stage_20089_Desc = {
    Text = "그녀는 자신의 약속을 지켰고, 이제 여러분은 마침내 함께 집으로 돌아갈 수 있습니다."
  },
  Stage_20089_Name = {
    Text = "황금 머리"
  },
  Stage_20090_Desc = {
    Text = "살롱 전시회는 서대에서 가장 중요한 예술 행사입니다. \n여기서 무명의 이들은 성공을 갈망하고. 이미 성공한 이들은 영원함을 추구합니다."
  },
  Stage_20090_Name = {
    Text = "산호 여인의 죽음"
  },
  Stage_20091_Desc = {
    Text = "답은 바닷물의 중앙에 있습니다."
  },
  Stage_20091_Name = {
    Text = "바다 한가운데에서"
  },
  Stage_20092_Desc = {
    Text = "엔스트 클라우델은 과거 베산송의 영주였습니다. \n현재까지 이 가문은 여전히 현지에서 명망이 높습니다."
  },
  Stage_20092_Name = {
    Text = "안녕하세요"
  },
  Stage_20426_Desc = {
    Text = "결말은 이미 정해져 있다. 네가 어떻게 시도하든 그녀가 어떻게 발버둥 쳐도 과거는 바꿀 수 없다."
  },
  Stage_20426_Name = {
    Text = "화려한 종말"
  },
  Stage_20427_Desc = {
    Text = "꿈은 언제나 완벽하지 않으며, 아름다운 노래가 언제나 울리지 않는 것처럼."
  },
  Stage_20427_Name = {
    Text = "곡이 끝나고 사람들이 흩어지다"
  },
  Stage_20428_Desc = {
    Text = "왕은 높은 왕좌에 갇혀 있다. \n세상이 변해도 그의 슬픔은 여전히 한결같다."
  },
  Stage_20428_Name = {
    Text = "그녀의 왕국"
  },
  Stage_20429_Desc = {
    Text = "그녀는 목적 없이 기억의 단편 속을 걷고 있었다. \n아무것도 모르고, 아무 감정도 느끼지 못하며, 반복되는 일상…"
  },
  Stage_20429_Name = {
    Text = "기억의 장벽"
  },
  Stage_20430_Desc = {
    Text = "미로의 끝은 무엇인가? 낮, 밤, 아니면 끝없는 공허인가? \n그녀는 스스로 답을 찾아야 한다."
  },
  Stage_20430_Name = {
    Text = "미궁의 끝"
  },
  Stage_20431_Desc = {
    Text = "자식, 더 많은 자식, 끊임없이 이어지는 자식……\n그들은 그녀의 유일한 사랑이었다."
  },
  Stage_20431_Name = {
    Text = "의식 군집"
  },
  Stage_20432_Desc = {
    Text = "영원히 당신의 것이 아닌 그 문을 열지 하지 말아요……"
  },
  Stage_20432_Name = {Text = "문"},
