  Stage_20445_Name = {
    Text = "의식 군집"
  },
  Stage_20697_Desc = {
    Text = "매 순간마다 한 사람이 죽고, 매 순간마다 한 사람이 태어납니다. \n그러나 그림자는 다릅니다. 그것은 시간에 흡수되고, 이 고통의 대지에 속박되어 있습니다. \n세세토록, 죽지도 않고, 태어나지도 않습니다."
  },
  Stage_20697_Name = {
    Text = "그림자의 송가"
  },
  Stage_20698_Desc = {
    Text = "신은 말한다, 그들이 태어날 때부터 고난을 겪고 피를 흘려야 한다고. \n태양이 떠오르고 비가 떨어져야 함처럼. \n모든 것이 가장 좋은 안배다."
  },
  Stage_20698_Name = {Text = "고우지"},
  Stage_20699_Desc = {
    Text = "우리는 전진합니다, 승리의 귀환을 위해. \n우리는 살아갑니다, 완벽한 죽음을 위해."
  },
  Stage_20699_Name = {
    Text = "먼 곳에서 온 자"
  },
  Stage_20700_Desc = {
    Text = "그것은 이곳에서 유일한 생명체이며, 그것이 보는 모든 것은 그것의 지배를 받습니다. \n—그것은 최고의 왕입니다."
  },
  Stage_20700_Name = {
    Text = "야수의 왕국"
  },
  Stage_20701_Desc = {
    Text = "그들은 생사의 경계를 넘어서, 묘비를 사이에 두고 다시 재회했다. \n얼굴을 맞대고, 손을 잡으며, 숨 쉬는 순간에도 부패한 냄새가 감돌았다."
  },
  Stage_20701_Name = {
    Text = "고독한 재회"
  },
  Stage_20702_Desc = {
    Text = "우리는 벌레, 뼈 그리고 눈물의 집합입니다. \n오늘 밤 우리는 무수한 무지개가 흐르는 강을 보기 위해 이곳에 모였습니다."
  },
  Stage_20702_Name = {
    Text = "수렵두개 집회"
  },
