  },
  Stage_23630_Desc = {
    Text = "가장 화려한 환경, 가장 아름다운 소망을 담고 있습니다."
  },
  Stage_23630_Name = {
    Text = "가장 성대한 환영"
  },
  Stage_23631_Desc = {
    Text = "물물교환, 천경지의입니다."
  },
  Stage_23631_Name = {
    Text = "상인의 관대함"
  },
  Stage_23632_Desc = {
    Text = "모든 사람이 스토리를 간직하고 있지만, 모든 사람이 이야기하려는 욕망을 가지고 있는 것은 아니다."
  },
  Stage_23632_Name = {
    Text = "이야기를 찾아서"
  },
  Stage_23633_Desc = {
    Text = "어떤 이들은 모험의 주인공으로 태어나고, 어떤 이들은 자신을 아름다운 사랑 이야기로 포장합니다. \n하지만 결국에는 모두가 자신의 감독자입니다."
  },
  Stage_23633_Name = {
    Text = "앤디·존슨의 힘"
  },
  Stage_23634_Desc = {
    Text = "가장 화려한 환경, 가장 아름다운 소망을 담고 있습니다."
  },
  Stage_23634_Name = {
    Text = "가장 성대한 환영"
  },
  Stage_23635_Desc = {
    Text = "최고로 만족스러운 결말…아마도 완벽하지는 않지만, 적어도 이 순간, 누구도 결말을 위해 웃지 않는 사람은 없다."
  },
  Stage_23635_Name = {
    Text = "가장 완벽한 결말"
  },
  Stage_23636_Desc = {
    Text = "가장 좋은 꽃, 낳아내는 가장 아름다운 시."
  },
  Stage_23636_Name = {
    Text = "가장 좋은 꽃"
