  Stage_23662_Name = {
    Text = "혈육의 늪지·회전 간격Ⅳ"
  },
  Stage_24183_Name = {
    Text = "붉은 여인 체험 스테이지"
  },
  Stage_24184_Name = {
    Text = "진흙 속의 꽃 체험 스테이지"
  },
  Stage_24423_Desc = {
    Text = "각 렌티니언 사람은 신선하게 끓여낸 따뜻한 차 한 잔을 거절하지 않을 것입니다. \n그것이 치골라미 우롱차일지라도."
  },
  Stage_24423_Name = {
    Text = "칠성장어 특제 음료"
  },
  Stage_24424_Desc = {
    Text = "각각 운명이 선택한 사람은 자신이 예외라고 생각한다.\n운명은 확률을 비웃는다."
  },
  Stage_24424_Name = {
    Text = "운명의 죄수"
  },
  Stage_24425_Desc = {
    Text = "찰칵. \n그녀는 과거의 삶과 완전히 단절하기로 맹세했다. \n마치 가위로 장식용 끈을 한 번에 두 조각으로 자르는 것처럼."
  },
  Stage_24425_Name = {
    Text = "소레유에게 바치며"
  },
  Stage_24426_Desc = {
    Text = "다시 한 번, 당신은 동정의 포로가 되어 그녀의 영혼에 깊이 빠져들었습니다."
  },
  Stage_24426_Name = {
    Text = "추락한 심판"
  },
  Stage_24427_Desc = {
    Text = "스토리의 시작에서 당신은 화려한 죽음을 증언하게 됩니다. \n그것은 시작일 뿐, 끝은 아닙니다."
  },
  Stage_24427_Name = {
    Text = "축배의 노래"
  },
  Stage_24428_Desc = {
    Text = "소녀의 이름은 소렐로, 마을 전체의 자랑이었습니다. \n그녀는 순하고 깨끗을 사랑하며, 온몸이 눈처럼 하얗고, 작은 걸음으로 진정한 숙녀처럼 보였습니다. \n소녀는 그 숙녀들과 달랐습니다—— 그녀는 결코 꿈을 꾸지 않았습니다."
  },
  Stage_24429_Desc = {
    Text = "논리는 술과 같아, 너무 많이 마시면 그 이점이 사라집니다."
  },
  Stage_24429_Name = {
    Text = "가면과 화성"
  },
  Stage_24430_Desc = {
    Text = "그분의 세심한 보살핌 아래에서, 권력욕이라는 암세포가 만발하는 장미처럼 퍼지기 시작했다."
  },
  Stage_24430_Name = {
    Text = "붉은 축전"
  },
  Stage_24431_Desc = {
    Text = "후루록. 후루룩. 우리는 어둠 속에서 꿈틀거리고, 속삭인다. \n비둔한 몸은 달빛 아래서 굽어있는 눈물 자국을 남긴다—짠 맛이다."
  },
  Stage_24431_Name = {Text = "알"},
  Stage_24432_Desc = {
    Text = "스콘, 마카롱, 따뜻한 코코아……\n시녀의 소원은 단순하다: 잘 먹고, 더 잘 먹는 것."
  },
  Stage_24432_Name = {
    Text = "시녀의 소원"
  },
  Stage_24433_Desc = {
    Text = "조심하세요, 조심하세요. \n여러분이 미쳐 있는 그 부인은 진정한 숙녀가 아니에요. \n하지만, 누가 신경 쓰겠어요?"
  },
  Stage_24433_Name = {
    Text = "숙녀 지침서"
  },
  Stage_24434_Desc = {
    Text = "장미는 종소리 속에서 가는 머리를 숙이고, 독수리는 비릿한 꽃밭에서 길을 잃었다. \n아무도 노래하지 않고, 아무도 말하지 않았다. 그녀의 죽음으로 세상은 퇴색되었다."
  },
  Stage_24434_Name = {
    Text = "장미의 장례식"
  },
  Stage_24435_Desc = {
    Text = "그녀는 포션을 마르게 하고 순진한 새들을 죽였다. \n그녀는 금빛 바람을 가져오고, 그것들은 유성처럼 초원을 스쳐 지나갔다. \n그녀는 세상 전체를 욕망의 불꽃 위에 놓고, 그것을 재로 변모시켰다."
  },
  Stage_24435_Name = {Text = "춘희"},
  Stage_24439_Desc = {
    Text = "조심하세요, 조심하세요. \n여러분이 미쳐 있는 그 부인은 진정한 숙녀가 아니에요. \n하지만, 누가 신경 쓰겠어요?"
  },
