    Text = "그분의 세심한 보살핌 아래에서, 권력욕이라는 암세포가 만발하는 장미처럼 퍼지기 시작했다."
  },
  Stage_24453_Name = {
    Text = "붉은 축전"
  },
  Stage_24454_Desc = {
    Text = "후루록. 후루룩. 우리는 어둠 속에서 꿈틀거리고 속삭인다. \n비둔한 몸은 달빛 아래서 굽어있는 눈물 자국을 남긴다—짠 맛이다."
  },
  Stage_24454_Name = {Text = "알"},
  Stage_24455_Desc = {
    Text = "각각 운명이 선택한 사람은 자신이 예외라고 생각한다.\n운명은 확률을 비웃는다."
  },
  Stage_24455_Name = {
    Text = "운명의 죄수"
  },
  Stage_24456_Desc = {
    Text = "논리는 술과 같아, 너무 많이 마시면 그 이점이 사라집니다."
  },
  Stage_24456_Name = {
    Text = "가면과 화성"
  },
  Stage_24528_Desc = {
    Text = "무슨 일이 있어도, 어떤 변화를 겪더라도, 당신의 부름은 항상 들릴 것입니다."
  },
  Stage_24528_Name = {
    Text = "이것은 영원한 이별이 아니다"
  },
  Stage_24529_Desc = {
    Text = "한 번, 두 번, 세 번…… 시지프스는 거대한 바위를 밀며 불가능한 산을 열심히 오르고 있었다."
  },
  Stage_24529_Name = {
    Text = "시지프스"
  },
  Stage_24530_Desc = {
    Text = "익숙한 소녀가 이렇게 낯설어졌고, 이 냉담한 사람…… 정말 당신이 아는 라몬나인가요?"
  },
  Stage_24530_Name = {
    Text = "사력을 다한 일격"
  },
  Stage_24531_Desc = {
    Text = "평범한 하루, 비일상적인 꿈으로 시작됩니다."
  },
  Stage_24531_Name = {
    Text = "비와 같은 눈물"
  },
  Stage_24532_Desc = {
    Text = "익숙한 소녀가 이렇게 낯설어졌고, 이 냉담한 사람…… 정말 당신이 아는 라몬나인가요?"
  },
  Stage_24532_Name = {
    Text = "사력을 다한 일격"
  },
  Stage_24533_Desc = {
    Text = "익숙한 소녀가 이렇게 낯설어졌고, 이 냉담한 사람…… 정말 당신이 아는 라몬나인가요?"
  },
  Stage_24533_Name = {
    Text = "사력을 다한 일격"
  },
  Stage_34716_Desc = {
    Text = "상황이 급변하고, 갑작스러운 사건, 이야기가 갑자기 변했다——수호자가 느끼기에, 이는 때때로 자신을 설명하는 것 같았다."
  },
  Stage_34716_Name = {
    Text = "Ⅲ·시나리오 회전"
  },
  Stage_34717_Desc = {
    Text = "이것은 라몬나조차 들어보지 못한 단어로, 몇몇 연로한 깨어남체의 도움을 받아 모두가 마침내 이해했다: 때때로, 대성통곡하는 것이 나쁜 감정을 처리하는 유일한 방법이라는 것을."
  },
  Stage_34717_Name = {
    Text = "Ⅱ·카타르시스"
  },
  Stage_34718_Desc = {
    Text = "카시아가 찾은 이론서에는 이렇게 쓰여 있었다: 이야기가 일어나는 시간은 하루를 넘지 않으며, 무대도 한 곳을 넘지 않아야 한다……\n수호자는 여기까지 듣고 포기했다. 결국, 하루의 시간은 때로 수호자가 「융식과 재앙 처리」의 과제 논문을 완성하기에도 부족할 때가 있기 때문이다."
  },
  Stage_34718_Name = {
    Text = "Ⅰ·삼일률"
  },
  Stage_34719_Desc = {
    Text = "카시아에서 찾은 이론서에는 다음과 같이 적혀 있다: 피라미드 모델은 종종 위기 해결에 초점을 맞추고 있다. \n하지만 안타깝게도 모든 위기가 현실타래에서 해결되는 것은 아니다. 그것들은 평화의 가면 뒤에 숨겨지고, 은밀히 번져나가다가 결국 새로운 「피라미드」로 폭발한다."
  },
  Stage_34719_Name = {
    Text = "Ⅶ·극작 피라미드"
  },
  Stage_34720_Desc = {
    Text = "스토리의 끝에서 캐릭터의 발전이나 변화를 나타내야 합니다. 하지만 실타래제 생활에서는 그 광선의 곡선이 종종 원을 이루곤 합니다."
  },
  Stage_34720_Name = {
    Text = "Ⅵ·호광이론"
  },
  Stage_34721_Desc = {
    Text = "예정된 장면, 서로 잘 아는 배우들. 나머지는 영감과 상호작용에 맡겨둡니다."
  },
  Stage_34721_Name = {
    Text = "Ⅴ·가면 코미디"
  },
  Stage_34722_Desc = {
    Text = "관객의 뇌를 내용으로 폭격하지 말고, 그들에게 생각할 공간을 주는 것이 좋다. 가장 좋은 방법은 완전히 정지하는 것이다. —— 수호자는 돌이 수업 중에 이 기술을 숙달했으면 좋겠다며 나지막이 말하기를 했고, 모든 사람의 동의를 받았다."
  },
  Stage_34722_Name = {
    Text = "Ⅳ·장면 정지 순간"
  },
  Stage_34912_Desc = {
    Text = "과거의 재앙이 이 순간 부활하여, 현실타래의 경계를 넘어 타락한 바다를 불태운다."
  },
  Stage_34912_Name = {
    Text = "융재금지구역 제1파·Ⅲ급 경보"
  },
  Stage_34913_Desc = {
