  Stage_34941_Name = {
    Text = "융재금지구역 제5파·Ⅰ급 경보"
  },
  Stage_35099_Desc = {
    Text = "「쉿…… 네가 뭐 보는지 알아?」\n오레타가 수호자에게 놀라 울음을 터뜨린 후, 수호자의 방의 네 번째 벽이 거의 무너질 뻔했다. 오레타가 너무 심하게 울어서 모두를 불안하게 만들었기 때문이다."
  },
  Stage_35099_Name = {
    Text = "Ⅸ·드라마의 네 번째 벽"
  },
  Stage_35100_Desc = {
    Text = "「관객이 극에 완전히 몰입하지 못하게 하고, 무대에서 일어나는 일을 분석하고 비판하게 해야 한다.」 \n 이 이론에 대해 오레타는 이렇게 평가한다: 오레타는 누구에게도 욕먹고 싶지 않아! 오레타는 모두와 좋은 친구가 되고 싶어!"
  },
  Stage_35100_Name = {
    Text = "Ⅷ·이방화 효과"
  },
  Stage_35129_Desc = {
    Text = "그녀는 꿈과 현실타래이 교차하는 경계이며, 밤하늘을 바라보는 각 영혼의 깊은 내면의 반사입니다."
  },
  Stage_35129_Name = {
    Text = "뒤틀린 별들"
  },
  Stage_35129_StageInitStateText = {Text = "해마"},
  Stage_35130_Desc = {
    Text = "그녀는 준비되었다."
  },
  Stage_35130_Name = {
    Text = "내면의 불꽃"
  },
  Stage_35571_Desc = {
    Text = "당신이 오레타의 친구이기 때문에, 그녀는 당신을 그녀의 모든 친구들에게 소개하고 싶어합니다."
  },
  Stage_35571_Name = {
    Text = "친구 대모집"
  },
  Stage_35572_Desc = {
    Text = "당신이 오레타의 친구이기 때문에, 그녀는 당신을 그녀의 모든 친구들에게 소개하고 싶어합니다."
  },
  Stage_35572_Name = {
    Text = "친구 대모집"
  },
  Stage_35573_Desc = {
    Text = "당신이 오레타의 친구이기 때문에, 그녀는 당신을 그녀의 모든 친구들에게 소개하고 싶어합니다."
  },
  Stage_35573_Name = {
    Text = "친구 대모집"
  },
  Stage_35574_Desc = {
    Text = "오레타는 당신을 좋아해서 당신이 그녀의 평범한 하루에 함께할 수 있는 친구가 되기를 원합니다."
  },
  Stage_35574_Name = {
    Text = "고요한 낮"
  },
  Stage_35575_Desc = {
    Text = "오레타 주변에 모두가 함께 있었기 때문에 오레타는 전혀 잠드는 것이 두렵지 않았다."
  },
  Stage_35575_Name = {
    Text = "물 속 궁전"
  },
  Stage_35843_Name = {
    Text = "심해의 숙녀 체험 스테이지"
  },
  Stage_35857_Desc = {
    Text = "별들은 그들이 마땅히 가야 할 곳으로 향했으며, 인간의 이해를 초월적인 방식으로 서로 교류하고, 흐르는 시간과 지나간 광년을 포착하는 보이지 않는 그물을 짜냈다."
  },
  Stage_35857_Name = {
    Text = "미지의 별길"
  },
