  },
  Stage_36620_Desc = {
    Text = "여왕은 높은 왕좌에 앉아 있습니다. \n그녀를 동반하는 것은 무한한 보물, 부, 그리고 조금 가라앉는 우주 폐허입니다."
  },
  Stage_36620_Name = {
    Text = "무리를 떠난 여왕"
  },
  Stage_36621_Desc = {
    Text = "재앙 전, 도성은 그녀의 야심과 욕망의 연장이었다. \n재앙 후, 도성은 밤과 외로움의 감옥이 되었다."
  },
  Stage_36621_Name = {
    Text = "피리 부는 자"
  },
  Stage_36887_Name = {
    Text = "가시의 여왕 체험 스테이지"
  },
  Stage_38756_Desc = {
    Text = "그녀는 양 눈을 감고, 우주의 공허 속에서 무작정 부유했다. \n일 년, 백 년…… 결국 어느 날, 그녀는 자신에게 말했다. 「상관없어. 진실타래과 거짓은 내가 정의할 거야.」 \n여왕과 그녀의 불멸의 도시 이사라우는 그렇게 우주의 광활한 은하에 머물렀다. \n그녀는 이사라우의 스토리를 나에게 전해주었는데, 그것은 영원히 기억되도록 하기 위해서였다."
  },
