  },
  Stage_38774_Desc = {
    Text = "밤에 여왕은 궁전의 테라스에 서서 수천 피트 아래의 도시를 바라보았다. \n날이 갈수록, 그녀가 궁전을 한 발짝도 벗어나려고 할 때마다 기절, 눈물, 그리고 대규모의 기억 상실타래이 찾아왔다. \n「준비됐어요? 이 세상의 진실타래을 맞이할 준비가 되었나요?」 \n그녀는 깊게 숨을 들이쉬고, 테라스에서 뛰어내렸다."
  },
