  Stage_38801_Desc = {
    Text = "「저는 아무것도 없어요.」 한쪽 눈이 먼 방랑자가 말했다. 「오직 이 꽃만을 당신께 드릴 수 있습니다, 위대한 여왕님.」 \n 그녀는 하얀 소광란을 받았지만, 혼란스러웠다. 이 장면이 마치 그녀의 기억 속에서 무수히 반복된 것처럼 느껴졌다. \n 끝없이 반복되는, 마치 미로에 갇힌 미노타우로스처럼."
  },
  Stage_38801_Name = {
    Text = "소광란·추억의 칠"
  },
  Stage_38802_Desc = {
    Text = "밤에 여왕은 궁전의 테라스에 서서 수천 피트 아래의 도시를 바라보았다. \n날이 갈수록, 그녀가 궁전을 한 발짝도 벗어나려고 할 때마다 기절, 눈물, 그리고 대규모의 기억 상실타래이 찾아왔다. \n「준비됐어요? 이 세상의 진실타래을 맞이할 준비가 되었나요?」 \n그녀는 깊게 숨을 들이쉬고, 테라스에서 뛰어내렸다."
  },
  Stage_38802_Name = {
    Text = "진실타래·추억·둘째"
  },
  Stage_38803_Desc = {
    Text = "그녀가 두 눈을 떴을 때, 세상은 그 때문에 파괴되고 있었다. \n모든 건물이 무너졌고, 검은 슬라임이 하늘을 핥았으며, 흰 소광란은 영원한 허공 속으로 사라졌다. \n모든 것이 고요했다. 모든 것이 잠들어 있는 듯했다. \n오직 눈물만이 차갑게 그녀의 얼굴에 맺혀 그녀의 머리카락을 적시고 있었다."
  },
  Stage_38803_Name = {
    Text = "우물·추억의 둘째"
  },
  Stage_38804_Desc = {
    Text = "그녀가 두 눈을 떴을 때, 세상은 그 때문에 파괴되고 있었다. \n모든 건물이 무너졌고, 검은 슬라임이 하늘을 핥았으며, 흰 소광란은 영원한 허공 속으로 사라졌다. \n모든 것이 고요했다. 모든 것이 잠들어 있는 듯했다. \n오직 눈물만이 차갑게 그녀의 얼굴에 맺혀 그녀의 머리카락을 적시고 있었다."
  },
  Stage_38804_Name = {
    Text = "우물·추억의 세 번째"
  },
  Stage_43506_Desc = {
    Text = "영원히 작별을. 거인은 말했다. \n역사 속으로 돌아가야 해. 거기서 나는 무적이고 파괴할 수 없다. \n나는 불멸이다."
  },
  Stage_43506_Name = {
    Text = "침몰한 호른"
  },
  Stage_43508_Desc = {
    Text = "시간에 잊힌 자여, 당신이 향할 곳은 어디인가?\n—— 그 먼 무인지경으로 가라. 거기서는 별과 달이 고요하고, 바다가 소리 없이 흐른다.\n세상에는 당신과 나만 남았다."
  },
  Stage_43508_Name = {
    Text = "의지할 곳 없는 바다"
  },
  Stage_43509_Desc = {
    Text = "영원히 작별을. 거인은 말했다. \n역사 속으로 돌아가야 해. 거기서 나는 무적이고 파괴할 수 없다. \n나는 불멸이다."
  },
  Stage_43509_Name = {
    Text = "침몰한 호른"
  },
  Stage_43510_Desc = {
    Text = "영웅과 그의 수행자가 황금빛 바다를 항해하고 있다. \n그들은 같은 상처를 지니고, 같은 멜로디를 부르며, 함께 죽음과 신생을 맞이한다."
  },
  Stage_43510_Name = {
    Text = "금빛 선율"
  },
  Stage_43512_Desc = {
    Text = "영원히 작별을. 거인은 말했다. \n역사 속으로 돌아가야 해. 거기서 나는 무적이고 파괴할 수 없다. \n나는 불멸이다."
  },
  Stage_43512_Name = {
    Text = "침몰한 호른"
  },
  Stage_44196_Desc = {
    Text = "미련한 자들아, 너희가 지핀 불길이 희망과 구원을 불살랐구나.\n칠흑의 죽음 속에서 허덕일 때, 그 자칭 정의가 과연 무슨 맛이더냐?"
  },
