  Stage_44200_Desc = {
    Text = "미련한 자들아, 너희가 지핀 불길이 희망과 구원을 불살랐구나.\n칠흑의 죽음 속에서 허덕일 때, 그 자칭 정의가 과연 무슨 맛이더냐?"
  },
  Stage_44200_Name = {
    Text = "후회·성장 둘째"
  },
  Stage_44201_Desc = {
    Text = "미련한 자들아, 너희가 지핀 불길이 희망과 구원을 불살랐구나.\n칠흑의 죽음 속에서 허덕일 때, 그 자칭 정의가 과연 무슨 맛이더냐?"
  },
  Stage_44201_Name = {
    Text = "후회、성장 세 번째"
  },
  Stage_44202_Desc = {
    Text = "병고통에 대한 공포가 그들을 불만스럽게 만들었습니다. \n「왜 그에게만 축복을 주는 거야? 나도 병이 들었어!」 \n「내가 가장 심각한 상태라고, 내가 먼저 축복받아야 해!」"
  },
  Stage_44202_Name = {
    Text = "쟁취·성장지네"
  },
  Stage_44203_Desc = {
    Text = "그들이 이익을 본 것이 좋은 것이고, 그들에게 미치지 못한 모든 축복은 저주입니다. \n「어떤 축복이냐, 사악한 피의 마법이 분명하다!」\n「이는 반드시 마술이며, 그는 악마다!」"
  },
  Stage_44203_Name = {
    Text = "비난·성장 둘째"
  },
  Stage_44204_Desc = {
    Text = "그들은 이해를 거부하고, 포용을 거부한다. \n 그들의 세계에는 오로지 흑과 백뿐이지만, 그들조차 그 둘을 제대로 정의하지 못한다.\n “불태워라, 불태워라!” \n “저 이단 주교를 불태워라! 악을 멸하라!”"
  },
