  Stage_44509_Name = {
    Text = "융재금지구역 제4파·Ⅰ급 경보"
  },
  Stage_44551_Desc = {
    Text = "자비로운 아버지 신이시여, 저를 용서하시고 제가 과오를 바로잡을 수 있게 하여 주시며, 제 잘못을 회복할 수 있게 해 주십시오."
  },
  Stage_44551_Name = {
    Text = "우리의 과오"
  },
  Stage_44552_Desc = {
    Text = "먼지가 가라앉고, 죄인들은 판결을 받을 것이며, 전진하는 이들은 계속해서 나아갈 것이다. \n내일은 새로운 하루가 될 것이다."
  },
  Stage_44552_Name = {
    Text = "하얀 희망을 밝혀라"
  },
  Stage_44553_Desc = {
    Text = "이는 평범하게 보였지만, 미사그의 비밀지킴이에게는 보통의 일상이 분명히 사치였습니다."
  },
  Stage_44553_Name = {Text = "회개"},
  Stage_44554_Desc = {
    Text = "정화, 정화…… 이는 도대체 미친 사람의 망언인가, 아니면 어떤 혼란스러운 신앙인가?"
  },
  Stage_44554_Name = {
    Text = "피로 물든 상징"
  },
  Stage_44555_Desc = {
    Text = "그들은 이미 불꽃에 휩싸여 이성을 잃었습니다."
  },
  Stage_44555_Name = {
    Text = "분노와 광기"
  },
  Stage_44556_Desc = {
    Text = "남들이 가지고 있는 것은 물론이고, 남들이 없는 것까지도 더 많이 가져야 한다——불필요하거나 황당하더라도."
  },
  Stage_44556_Name = {
    Text = "질투와 살육"
  },
  Stage_44557_Desc = {
    Text = "멈추세요, 쉬세요, 당신은 이미 충분히 고생했습니다;눕으세요, 편히 자세요, 아무도 당신을 책망하지 않을 것입니다."
  },
  Stage_44557_Name = {
    Text = "나태와 굴복"
  },
  Stage_44558_Desc = {
    Text = "당신은 피곤한 몸으로 왔던 길을 걷다가 굶주린 이빨에 마주쳤습니다."
  },
  Stage_44558_Name = {
    Text = "허기을 채워라"
  },
  Stage_44559_Desc = {
    Text = "거울에 비친 것은 과연 허구의 그림자일까, 아니면 진실타래된 욕망일까?"
  },
  Stage_44559_Name = {
    Text = "죄악을 정화하라"
  },
  Stage_44560_Desc = {
    Text = "자비로운 아버지 신이시여, 저를 용서하시고 제가 과오를 바로잡을 수 있게 하여 주시며, 제 잘못을 회복할 수 있게 해 주십시오."
  },
  Stage_44560_Name = {
    Text = "우리의 과오"
