  Stage_44715_Name = {
    Text = "자비로운 제사장 체험 스테이지"
  },
  Stage_45411_Desc = {
    Text = "작별의 입맞춤을 해줘."
  },
  Stage_45411_Name = {
    Text = "작별의 입맞춤"
  },
  Stage_46169_Desc = {
    Text = "그녀는 모든 확률을 마음에 새겼지만, 신학원의 신학생들과 마찬가지로 혼란스러웠다. \n왜냐하면 광기는 예측할 수 없고, 아쉽게도 그것이 세상의 일반적인 상태이기 때문이다."
  },
  Stage_46169_Name = {
    Text = "만관 계약"
  },
  Stage_46170_Desc = {
    Text = "그녀는 모든 확률을 마음에 새겼지만, 신학원의 신학생들과 마찬가지로 혼란스러웠다. \n왜냐하면 광기는 예측할 수 없고, 아쉽게도 그것이 세상의 일반적인 상태이기 때문이다."
  },
  Stage_46170_Name = {
    Text = "만관 계약"
  },
  Stage_46171_Desc = {
    Text = "주문의 결박이 당신을 영구적 동면 상태의 뱀으로 만들어버렸다. \n그것은 당신의 탯줄만큼 오래되었다."
  },
  Stage_46171_Name = {
    Text = "고통의 저주"
  },
  Stage_46172_Desc = {
    Text = "소녀는 과거에 메이슨이었다. \n조만간 그녀는 유리시즈처럼 아무도 아닌 사람이 될 것이다. \n조만간 그녀는 모든 이가 될 것이다."
  },
  Stage_46172_Name = {
    Text = "「근원」"
  },
  Stage_46173_Desc = {
    Text = "주문의 결박이 당신을 영구적 동면 상태의 뱀으로 만들어버렸다. \n그것은 당신의 탯줄만큼 오래되었다."
  },
  Stage_46173_Name = {
    Text = "고통의 저주"
  },
  Stage_46174_Desc = {
    Text = "여기까지, 나에게서 멈추자. \n네 님을 시도하지 마라."
  },
  Stage_46174_Name = {
    Text = "여기서 멈추다"
  },
  Stage_46175_Desc = {
    Text = "다년 동안 순례자들은 설산에서 길을 파내어 현실타래을 끌어당겼습니다. \n그들은 움직이지 않고, 입을 크게 벌린 채 연속적인 포효를 내는 것처럼 보였습니다 ——"
  },
  Stage_46175_Name = {
    Text = "순례자의 노래"
  },
  Stage_46176_Desc = {
    Text = "주문의 결박이 당신을 영구적 동면 상태의 뱀으로 만들어버렸다. \n그것은 당신의 탯줄만큼 오래되었다."
  },
  Stage_46176_Name = {
    Text = "고통의 저주"
  },
  Stage_46177_Desc = {
    Text = "그녀는 모든 확률을 마음에 새겼지만, 신학원의 신학생들과 마찬가지로 혼란스러웠다. \n광기는 예측할 수 없다. 불행히도, 그것이야말로 세상의 일상이다."
  },
  Stage_46177_Name = {
    Text = "만관 계약"
  },
  Stage_46178_Desc = {
    Text = "그녀는 자신이 곧 세상을 점령할 것을 보았다. \n그녀는 그 좁은 그림자를 바라보며 아무 말도 하지 않았다."
  },
  Stage_46178_Name = {
    Text = "그림자 동화"
  },
  Stage_46179_Desc = {
    Text = "그녀의 코미디는 독특합니다. 그것들은 무한한 적막한 밤, 달, 그리고 눈물로 이루어져 있습니다."
  },
  Stage_46179_Name = {
    Text = "희극을 기다리며"
  },
  Stage_46180_Desc = {
    Text = "모든 것이 잠들 때, 뱀은 깨어납니다. \n모든 것이 무너질 때, 뱀은 원상태로 돌아옵니다."
  },
  Stage_46180_Name = {Text = "불면뱀"},
  Stage_46181_Desc = {
    Text = "고양이는 자신의 감정을 열여덟 조각으로 나누고, 각각의 조각에 다른 음조의 「미야우」 소리를 발명했습니다. \n이렇게 하면, 「배고파요」 「빨리 놀아줘」 「내버려두세요」라고 말할 수 있습니다. \n또한 「너가 보고 싶어」라고도 말할 수 있습니다."
  },
  Stage_46181_Name = {
    Text = "고양이는 모든 것을 알고 있다"
  },
  Stage_46182_Desc = {
    Text = "낡은 종소리와 함께 들려오는 것은 약해지는 축복입니다. \n행복한 축제. 행복한 축제. 행복한 축제."
