    Text = "지옥은 수많은 거울이 놓여 있는 빈 방이다. \n그녀는 감히 눈을 뜨지 못했다. 고개를 들거나 숙일 때마다 창백하고 겁에 질린 그녀의 얼굴이 보였기 때문이다. \n어둠 속에서 어떤 소리가 말했다: \n이것은 보응이다. 네가 살아있을 때는 단 하나의 육신만 있었지만, 죽어서 받는 보응에서는 무수히 많은 육신이 있다."
