    Text = "마지막으로 그녀는 왕의 조각상이 서 있었던 곳을 응시했습니다. \n그곳에는 조각상도, 왕도 없었습니다."
  },
  Stage_51761_Name = {
    Text = "레무리아로 돌아가는 꿈"
  },
  Stage_51762_Desc = {
    Text = "조각상은 그녀와 멀리서 바라보고 있다. 그들 사이에는 긴 시간과 깨어나지 않은 꿈이 있다."
  },
  Stage_51762_Name = {
    Text = "검은 조각상"
  },
  Stage_51763_Desc = {
    Text = "희망은 리모리아에서 가장 소중한 독약입니다. \n그들은 노래하며 술을 마시며, 단맛처럼 그것을 즐깁니다."
  },
  Stage_51763_Name = {
    Text = "사제의 의식"
  },
  Stage_51764_Desc = {
    Text = "별들, 운명, 신성…… 그들 앞에서 공평함은 무의미하다."
  },
  Stage_51764_Name = {
    Text = "거짓말의 미덕"
  },
  Stage_51765_Desc = {
    Text = "비 속에서 고군분투합니다. 비 속에서 작별을 고합니다."
  },
  Stage_51765_Name = {
    Text = "비 속에서"
  },
  Stage_51766_Desc = {
    Text = "응답하십시오, 주인님. 제가 가장 소중한 선물을 드리겠습니다."
  },
  Stage_51766_Name = {
    Text = "왕의 헌례"
  },
  Stage_51767_Desc = {
    Text = "향유하라, 그분이 말했다. 저 비천한 온정을, 저 요리된 운명을 향유하라."
  },
  Stage_51767_Name = {Text = "어육"},
  Stage_51768_Desc = {
    Text = "그분의 의지는 별들의 그물처럼 얽혀 있으며, 그분은 영원한 공허에서 당신이 꿈에 들어가기를 기다리고 있습니다."
  },
  Stage_51768_Name = {
    Text = "심해로부터의 기도"
  },
  Stage_51769_Desc = {
    Text = "기도는 리모리아인이 배운 첫 번째 것이었습니다."
  },
  Stage_51769_Name = {Text = "예언"},
  Stage_51770_Desc = {
    Text = "그 안식의 극락에서 옛 친구들이 서로를 바라봅니다. \n그들은 서로의 손을 잡고 신국으로 향하는 계단을 함께 오르게 될 것입니다."
  },
  Stage_51770_Name = {
    Text = "절친한 벗"
  },
  Stage_51771_Desc = {
    Text = "피. 눈물. 제사. 광란. 살육. \n또 다른 별들의 이야기가 시작되었지만, 별들은 신경 쓰지 않는다. \n그들은 빛나고 있다, 옛날부터 지금까지."
  },
  Stage_51771_Name = {
    Text = "귀 기울여라, 뭇별이여"
  },
  Stage_51772_Desc = {
    Text = "그녀는 그녀의 가장 좋은 친구입니다. 항상 그래왔습니다."
  },
  Stage_51772_Name = {
    Text = "오래된 친구"
  },
  Stage_51773_Desc = {
    Text = "마셔라, 이 달콤한 술을. 춤추어라, 이 뜨거운 춤을. \n고국의 주제사가 전당에 들어가 새로운 신도를 안아준다."
  },
  Stage_51773_Name = {
    Text = "피의 연회"
  },
  Stage_51774_Desc = {
    Text = "안개가 구도자의 얼굴을 가리고 있다. 안개가 옹립자의 마음을 가리고 있다."
  },
  Stage_51774_Name = {
    Text = "안개 속의 사람"
  },
  Stage_51775_Desc = {
    Text = "옛날의 궁전은 이미 포영이 되었고, 옛날의 잔몽은 여운만을 남겼다. 시들어버린 왕좌 위에는 왕의 시체만이 남아, 오래된 유언을 이야기하고 있다."
  },
  Stage_51775_Name = {
    Text = "과거의 환영"
  },
  Stage_51785_Desc = {
    Text = "보이지 않는 재앙이 부활하여, 물리적 세계의 역사와 존재를 심연으로 끌어내린다."
  },
  Stage_51785_Name = {
    Text = "융재금지구역 제1파·Ⅳ급 경보"
  },
  Stage_51786_Desc = {
    Text = "보이지 않는 재앙이 부활하여, 물리적 세계의 역사와 존재를 심연으로 끌어내린다."
  },
  Stage_51786_Name = {
    Text = "융재금지구역 제3파·Ⅳ급 경보"
  },
  Stage_51787_Desc = {
    Text = "보이지 않는 재앙이 부활하여, 물리적 세계의 역사와 존재를 심연으로 끌어내린다."
  },
  Stage_51787_Name = {
    Text = "융재금지구역 제2파·Ⅳ급 경보"
  },
  Stage_51788_Desc = {
    Text = "보이지 않는 재앙이 부활하여, 물리적 세계의 역사와 존재를 심연으로 끌어내린다."
  },
  Stage_51788_Name = {
    Text = "융재금지구역 제5파·Ⅳ급 경보"
  },
  Stage_51789_Desc = {
    Text = "보이지 않는 재앙이 부활하여, 물리적 세계의 역사와 존재를 심연으로 끌어내린다."
  },
  Stage_51789_Name = {
    Text = "융재금지구역 제4파·Ⅳ급 경보"
  },
  Stage_52007_Desc = {
    Text = "모든 것을 잃은 그날, 그녀는 마침내 왕만이 리모리아의 백성을 구원할 수 있다는 것을 깨달았다. \n그녀는 기다렸다. 먼 신국에서, 자신이 잃어버린 모든 것과 재회하기 위해."
  },
  Stage_52007_Name = {
    Text = "증언·지네"
  },
  Stage_52008_Desc = {
    Text = "그녀는 왕이 예언한 모든 것을 갖추게 되었다——강력한 힘, 견고한 신앙. 그녀는 왕을 의심했던 죄를 짊어지고, 신국을 맞이하기 위한 길을 걷기 시작했다."
  },
  Stage_52008_Name = {
    Text = "신념·둘째"
  },
  Stage_52009_Desc = {
