  Stage_52014_Name = {
    Text = "신념·지오"
  },
  Stage_52015_Desc = {
    Text = "신국의 윤곽이 그녀의 눈앞에 나타났다. 신국의 종소리가 그녀의 귀에서 울려 퍼졌다. 그녀는 왕의 예언을 실타래천하며 결코 멈추지 않을 것이다. \n그녀는 이 말로 이생의 망망한 밤을 견뎌냈다."
  },
