  },
  Stage_52022_Desc = {
    Text = "리모리아는 소멸했습니다. 신은 이 땅을 전혀 신경 쓰지 않았습니다. \n신국은 결코 존재하지 않았습니다."
  },
  Stage_52022_Name = {
    Text = "동요·육"
  },
  Stage_52023_Desc = {
    Text = "기도는 리모리아인이 배운 첫 번째 일이지만, 그녀 앞에 나타나 그녀를 보호하는 것은 그녀의 왕이 아닌 다른 존재였다."
