    Text = "인기 있는 시편이 모든 것을 가져왔다. 친구의 찬사 속에서 그녀는 얼굴을 붉혔다. 자신의 시가 드디어 친구가 자신 때문에 고생하지 않게 되었다고 그녀는 생각했다. \n그러나 그녀가 듣지 못한 것은, 악독한 씨앗이 이미 뿌려져 있다는 것이었다. 그것은 장미를 꽉 감싸고 파괴하기만을 기다리고 있었다."
