  Stage_55394_Name = {
    Text = "정원의 애가"
  },
  Stage_55395_Desc = {
    Text = "조각상은 왕의 수사학, 침묵은 조각상의 수사학이다."
  },
  Stage_55395_Name = {
    Text = "조각상 수사학"
  },
  Stage_55396_Desc = {
    Text = "그녀들은 정원을 사이에 두고 서로를 바라보았다. \n정원에는 그녀들 각자의 길이 무수히 많았고, 각각의 길은 서로 다른 방향으로 뻗어 있었다."
  },
  Stage_55396_Name = {
    Text = "분기된 정원의 작은 길"
  },
  Stage_55397_Desc = {
    Text = "첫 번째 장례로 유골을, 두 번째 장례로 세월을 작별한다."
  },
  Stage_55397_Name = {
    Text = "뒤늦은 장례식"
  },
  Stage_55398_Desc = {
    Text = "우수한 시는 사람을 현장에 있는 것처럼 만듭니다. \n고전적인 미학 이론은 이렇게 소개하고 있습니다."
