  Stage_55400_Name = {Text = "고향"},
  Stage_55401_Desc = {
    Text = "「첫 번째 장미로 당신의 첫 시를 바꾸자.」"
  },
  Stage_55401_Name = {
    Text = "시편 1843"
  },
  Stage_55551_Desc = {
    Text = "이 설산은 생명을 가지고 있으며, 산간에 휘파람 소리가 메아리치고 있습니다. 그것은 자신의 딸을 부르는 소리입니다. \n오세요, 오세요. \n딸이 어머니에게 가야 하는가, 아니면 어머니가 딸에게 가야 하는가? \n설산 정상에서 두 개의 텅 빈 공간이 마침내 서로 마주했습니다."
  },
