  Stage_55554_Desc = {
    Text = "설산의 동토는 메말라 빛을 잃었으며, 모든 생명을 말살한다. \n하지만 생명의 의지는 영원히 강하다. \n설산이 녹아내릴 때를 기다리며, 차가운 물방울이 흙으로 떨어진다. \n한 알의 굳건한 씨앗이 즉시 산봉우리에서 싹튼다."
