  Stage_55585_Desc = {
    Text = "설산의 동토는 메말라 빛을 잃었으며, 모든 생명을 말살한다. \n하지만 생명의 의지는 영원히 강하다. \n설산이 녹아내릴 때를 기다리며, 차가운 물방울이 흙으로 떨어진다. \n한 알의 굳건한 씨앗이 즉시 산봉우리에서 싹튼다."
  },
  Stage_55585_Name = {
    Text = "파토·지네"
  },
  Stage_56404_Desc = {
    Text = "머피는 자신이 첫 번째 성녀가 아니라는 것을 알게 되었다. 수천 년의 긴 세월 동안, 수많은 소녀들의 몸속에서 비슷한 심장 박동이 선동되었다. \n무수한 시공간에서, 무수한 심장들이 겹쳐서 뛰고 있었다."
  },
  Stage_56404_Name = {
    Text = "시공의 구멍·광기"
  },
  Stage_56404_StageInitStateText = {Text = "해마"},
  Stage_56405_Desc = {
    Text = "이것은 모든 생명의 마지막으로 존엄한 안식처입니다. \n깊은 바다를 관으로, 하늘과 땅을 자로 삼아 위대한 신성은 양류 속에 잠들다."
  },
  Stage_56405_Name = {
    Text = "포장천·광기"
  },
  Stage_56405_StageInitStateText = {Text = "해마"},
  Stage_56407_Desc = {
    Text = "그는 소리 없이, 마음 없이 강림했다. \n그의 심장은 그녀의 혈맥에서 갈망하지 않는 자세로 생존의 박동을 이어갔다."
  },
  Stage_56407_Name = {
    Text = "그의 강림·광기"
  },
  Stage_56407_StageInitStateText = {Text = "해마"},
  Stage_56408_Desc = {
    Text = "그녀는 높은 하늘의 별을 세며, 바라지 않는 순간을 기다렸다. \n「별들이 교차하는 순간」, 별들이 바다 위로 떠오를 때, 그녀는 별들 중 하나가 될 것이다."
  },
  Stage_56408_Name = {
    Text = "노란 별·광기"
  },
  Stage_56408_StageInitStateText = {Text = "해마"},
  Stage_56409_Desc = {
    Text = "그녀는 자신의 가슴에 심어진 태아의 소유권을 결정할 권한이 없다. \n 그녀는 어디로 도망칠지, 누구의 손을 잡을지, 누구와 함께 떠돌아다닐지 결정할 권한이 없다. \n 바다 위의 환경 속에서 떠다니는 운명 앞에서는 누구든 도살장으로 끌려가는 양과 같다."
  },
  Stage_56409_Name = {
    Text = "도살당한 어린양·광기"
  },
  Stage_56409_StageInitStateText = {Text = "해마"},
  Stage_56410_Desc = {
    Text = "단두대를 사용해 그녀를 처형할 필요는 없다. \n그녀를 손수 죽인 사람은 그녀의 어머니였다."
  },
  Stage_56410_Name = {
    Text = "행형자·광기"
  },
  Stage_56410_StageInitStateText = {Text = "해마"},
  Stage_56411_Desc = {
    Text = "조용히.조용히.조용히.\n얼음 아래 모든 것이 영원하며, 숨쉬기까지 봉인됩니다.생존과 죽음은 동의어이며, 잠복과 부활은 구별되지 않습니다.\n엘워스는 영원히 그녀의 봄을 갖지 못할 것입니다."
  },
  Stage_56411_Name = {
