  Stage_56893_Name = {
    Text = "인형의 집·육"
  },
  Stage_56894_Desc = {
    Text = "이 세상에는 원래 문이 없었다. \n문을 원하는 사람이 많아지면서, 이 세상에는 다양한 문들이 생겨났다. \n모든 사람이 자신의 문 뒤에 천국이 있다고 말한다. \n그러나 오래된 예언은 이미 명백히 말했다. 이 세상에는 문이 없다고. \n인간 세상에 천국을 세우려는 자는 결국 지옥의 대문을 시작하게 될 것이다."
  },
  Stage_56894_Name = {
    Text = "혼돈의 예언·육"
  },
  Stage_56895_Desc = {
    Text = "인형의 손에서 실타래이 늘어져 세계의 부품을 연결한다. \n딸깍, 찌릿, 손가락을 움직이니 세계가 무너진다. \n또 무엇이 인형의 머리 위에 매달려 있어 공허를 위한 춤을 멈추지 않게 하는가."
  },
  Stage_56895_Name = {
    Text = "인형의 실타래·둘째"
  },
  Stage_56896_Desc = {
    Text = "이 세상에는 원래 문이 없었다. \n문을 원하는 사람이 많아지면서, 이 세상에는 다양한 문들이 생겨났다. \n모든 사람이 자신의 문 뒤에 천국이 있다고 말한다. \n그러나 오래된 예언은 이미 명백히 말했다. 이 세상에는 문이 없다고. \n인간 세상에 천국을 세우려는 자는 결국 지옥의 대문을 시작하게 될 것이다."
  },
