  Stage_56997_Name = {
    Text = "본성의 문·지네"
  },
  Stage_56998_Desc = {
    Text = "그는 소리를 따라 왔으며, 지휘대에 올랐다.\n그는 안정적이고 자신감 넘치는 걸음으로 나아갔다.\n아무도 그가 꿈을 따라왔다는 사실타래을 알지 못했고, 그 꿈의 주인은 이미 방향을 잃었다."
