  Stage_57004_Desc = {
    Text = "출발하자. \n이번 여정이 「지혜」로 향하는 것인지 아니면 「어리석음」으로 향하는 것인지는 여행을 시작해야만 알 수 있다."
  },
  Stage_57004_Name = {
    Text = "출발•지네"
  },
  Stage_57395_Desc = {
    Text = "상식과는 반대로: 현실타래 세계에서는 알리바이가 없어도 더 안전할 수 있다. \n확실타래한 증거가 없다면 경찰은 살인자를 체포할 수 없다. \n그러므로, 살인자들은 그 불필요한 행동을 멈추세요!"
  },
  Stage_57395_Name = {
    Text = "부재 진술·광기"
  },
  Stage_57395_StageInitStateText = {Text = "원초"},
  Stage_57396_Desc = {
    Text = "「나arrator인 내가 살인자다」——진정으로 지겨운 수단, 아름다움도 기술도 없다. \n불행하게도, 이번에도 내가 목격하고 말았다."
