  Stage_57396_Name = {
    Text = "반전 술수·광기"
  },
  Stage_57396_StageInitStateText = {Text = "원초"},
  Stage_57397_Desc = {
    Text = "탐정 수칙 제1조: 겉보기에 평범하고 약해 보이는 의뢰인일수록, 그 뒤에 숨겨진 사건이 크다. \n외모로 사람을 판단하는 것은 여기서 적용되지 않는다."
  },
  Stage_57397_Name = {
    Text = "불청객·광기"
  },
  Stage_57397_StageInitStateText = {Text = "원초"},
  Stage_57398_Desc = {
    Text = "만약 현장에서 무두체나 얼굴 없는 시체를 발견했다면, 의심하지 말라—— \n그의 신분은 분명히 바뀌었다."
  },
  Stage_57398_Name = {
    Text = "무두체·광기"
  },
  Stage_57398_StageInitStateText = {Text = "원초"},
  Stage_57399_Desc = {
    Text = "평범한 외모, 경력, 이름……\n이런 요소들이 한 사람에게 집중되면, 용의자 명단에서 안심하고 제외해도 좋습니다.\n왜인지 물어보지 마세요."
  },
  Stage_57399_Name = {
    Text = "행운의 평민·광기"
  },
  Stage_57399_StageInitStateText = {Text = "원초"},
  Stage_57400_Desc = {
    Text = "1,2,3……\n5번째 사람이 살해당할 때까지, 나처럼 영리한 사람도 사건을 해결하지 못했다.\n왜냐하면 이 동요는 총 10개의 문장으로 이루어져 있기 때문이다."
  },
  Stage_57400_Name = {
    Text = "나뭇가지를 물고·광기"
  },
  Stage_57400_StageInitStateText = {Text = "원초"},
  Stage_57401_Desc = {
    Text = "기계 장치, 살인자가 실타래내에 있고, 자살을 위장한 타살……\n정말로 밀실타래을 만드는 데 그렇게 많은 노력이 들었는데, 그냥 킬러를 고용하는 것이 더 빠른 방법이 아니었을까요?"
  },
  Stage_57401_Name = {
    Text = "미스터리 룸·광기"
  },
  Stage_57401_StageInitStateText = {Text = "원초"},
  Stage_57402_Desc = {
    Text = "경찰 친구를 배척하지 마세요. \n 추리의 세계에서 그들은 보통 살인자에게 이용당하는 역할을 합니다. \n 최대의 용도: 즉시 잘못된 용의자를 제거해 줍니다."
  },
  Stage_57402_Name = {
    Text = "탐정의 친구·광기"
  },
  Stage_57402_StageInitStateText = {Text = "원초"},
  Stage_57403_Desc = {
    Text = "만약 위의 추리 원칙을 읽었음에도 불구하고 당신이 탐정이 되고자 하는 열정이 줄지 않았다면. \n그렇다면 행운을 빕니다, 당신 이 고치기 힘든 바보야."
  },
  Stage_57403_Name = {
    Text = "후기·광기"
  },
  Stage_57403_StageInitStateText = {Text = "원초"},
  Stage_57673_Desc = {
    Text = "지우가 등을 돌리고, 형제가 서로를 해치며, 사랑 때문에 증오가 생기는 것……\n그는 인간의 왜곡된 감정을 흡수하는 것을 즐기며, 자신을 자연주의자라고 칭한다.\n「이것은 가장 순수하고 진실타래한 감정입니다. 천연 그대로 가공되지 않았으며, 맛은 소박하고 상쾌합니다.」"
  },
  Stage_57673_Name = {Text = "비극 쇼"},
  Stage_57674_Desc = {
    Text = "모든 불가능을 제거하면 남은 것은 진실타래뿐이다. \n물론, 양자물리학자들은 이에 대해 이의를 제기한다."
  },
  Stage_57674_Name = {
    Text = "진실타래 하나"
  },
  Stage_57675_Desc = {
    Text = "「만약……그렇다면……」은 탐정이 가장 싫어하는 문장 구조입니다. \n이는 실타래패, 후회, 그리고 쓴 맛의 송자주를 의미하며, 그는 이미 오래전에 술을 끊었습니다."
  },
  Stage_57675_Name = {
    Text = "현실타래 아래서"
  },
  Stage_57676_Desc = {
    Text = "모든 사람에게 좋아지는 것은 놀라운 성취입니다; 모든 사람에게 싫어지는 것도 마찬가지입니다. \n그는 위의 두 가지를 전혀 노력하지 않고 해냅니다. \n역시 대단하세요, 다음 주 월요일 선생님!"
  },
  Stage_57676_Name = {
    Text = "다음 주 월요일 선생님"
  },
  Stage_57677_Desc = {
    Text = "그는 어제였지만 오늘도 알고 있다. \n그는 신들과 함께 거주하며, 그의 생명은 영원히 끝나지 않는다."
  },
  Stage_57677_Name = {
    Text = "관 속의 벽"
  },
  Stage_57678_Desc = {
    Text = "사람은 둔감한 생물입니다.\n그들 사이에 나무 판자를 세우기만 하면, 그들은 서로의 기운을 더 이상 감지할 수 없습니다."
  },
  Stage_57678_Name = {Text = "첫만남"},
  Stage_57679_Desc = {
    Text = "여덟 명의 병사, 촛불을 밝혀 밤을 지새우네; \n 목을 매고 떠나, 일곱 명만 남았다."
  },
  Stage_57679_Name = {
    Text = "그리고 아무도 없었다"
  },
  Stage_57681_Desc = {
    Text = "그들은 모두 죽음의 땅에 있었지만, 삶을 향한 갈망을 버리지 않았습니다."
  },
  Stage_57681_Name = {
    Text = "마지막 인사"
  },
  Stage_57682_Desc = {
    Text = "고택과 유령의 관계는 대략 치즈와 베이컨 같다고 할 수 있다.\n누가 먼저인지 말하기 어렵지만, 어쨌든 사람들이 알아차렸을 때 그들은 이미 떼려야 뗄 수 없게 되어 있었다."
  },
  Stage_57682_Name = {
    Text = "유령의 집"
  },
  Stage_57683_Desc = {
    Text = "그러나 결과나 입장을 거꾸로 추론하여 「원인」이라고 하는 것일 뿐이다. \n인류 역사에는 이런 희극이 곳곳에서 일어났다."
  },
  Stage_57683_Name = {Text = "역추론"},
  Stage_57684_Desc = {
    Text = "그들은 모두 죽음의 땅에 있었지만, 삶을 향한 갈망을 버리지 않았습니다."
  },
  Stage_57684_Name = {
    Text = "마지막 인사"
  },
  Stage_57685_Desc = {
    Text = "행운이 당신과 함께하기를, 탐정님. \n후에 있을 기약."
  },
  Stage_57685_Name = {
    Text = "행운을 빕니다!"
  },
  Stage_57686_Desc = {
    Text = "시험 때마다 나는 재난을 기다립니다. \n홍수, 허리케인, 운석 충돌…… 무엇이든 현실타래을 잠시 밀어낼 수 있다면. \n잠깐 동안만."
  },
  Stage_57686_Name = {Text = "불청객"},
  Stage_57687_Desc = {
    Text = "그들은 모두 죽음의 땅에 있었지만, 삶을 향한 갈망을 버리지 않았습니다."
  },
  Stage_57687_Name = {
    Text = "마지막 인사"
  },
  Stage_58064_Desc = {
    Text = "미련한 자들아, 너희가 지핀 불길이 희망과 구원을 불살랐구나.\n칠흑의 죽음 속에서 허덕일 때, 그 자칭 정의가 과연 무슨 맛이더냐?"
  },
  Stage_58064_Name = {
    Text = "후회·광기"
  },
  Stage_58064_StageInitStateText = {Text = "번식"},
  Stage_58065_Desc = {
    Text = "미련한 자들아, 너희가 지핀 불길이 희망과 구원을 불살랐구나.\n칠흑의 죽음 속에서 허덕일 때, 그 자칭 정의가 과연 무슨 맛이더냐?"
  },
  Stage_58065_Name = {
    Text = "후회·육"
  },
  Stage_58066_Desc = {
    Text = "그들은 이해를 거부하고, 포용을 거부한다. \n 그들의 세계에는 오로지 흑과 백뿐이지만, 그들조차 그 둘을 제대로 정의하지 못한다.\n “불태워라, 불태워라!” \n “저 이단 주교를 불태워라! 악을 멸하라!”"
  },
