  Stage_58364_Name = {
    Text = "망각 곡선·광기"
  },
  Stage_58364_StageInitStateText = {Text = "원초"},
  Stage_58365_Desc = {
    Text = "「저는 아무것도 없어요.」 한쪽 눈이 먼 방랑자가 말했다. 「오직 이 꽃만을 당신께 드릴 수 있습니다, 위대한 여왕님.」 \n 그녀는 하얀 소광란을 받았지만, 혼란스러웠다. 이 장면이 마치 그녀의 기억 속에서 무수히 반복된 것처럼 느껴졌다. \n 끝없이 반복되는, 마치 미로에 갇힌 미노타우로스처럼."
  },
