  },
  Stage_58371_Name = {
    Text = "소광란·육"
  },
  Stage_58372_Desc = {
    Text = "여왕과 그녀의 불멸의 도시——이사라우. \n우주가 기운을 주는 쌍둥이들이여, 운명의 끈에 의해 부드럽게 감싸여 있다. \n어떤 이들은 지혜로운 여왕이 시민들을 이끌고 이사라우에 도착했다고 말하며, 이는 마치\"계시록\"에 묘사된 것과 같다. \n또 다른 이들은 이사라우의 강바닥이 전년 흐르다가 결국 여왕을 잉태했다고 말한다."
  },
