  Stage_58378_Desc = {
    Text = "여왕과 그녀의 불멸의 도시——이사라우. \n우주가 기운을 주는 쌍둥이들이여, 운명의 끈에 의해 부드럽게 감싸여 있다. \n어떤 이들은 지혜로운 여왕이 시민들을 이끌고 이사라우에 도착했다고 말하며, 이는 마치\"계시록\"에 묘사된 것과 같다. \n또 다른 이들은 이사라우의 강바닥이 전년 흐르다가 결국 여왕을 잉태했다고 말한다."
  },
  Stage_58378_Name = {
    Text = "계시록·지네"
  },
  Stage_58379_Desc = {
    Text = "이사라우는 그렇게 사라졌다. 마치 그것이 결코 태어나지 않았던 것처럼. \n모든 거리와 백성들은 허상이었다. 그들은 그녀의 꿈에서 태어났고, 하루하루 그려짐으로써 점점 구체화되었지만: \n「번——」 \n꿈이 깨어났다. 그녀는 이사라우를 눈 뜨지 않고 보지 않았으며, 자신을 눈 뜨지 않고 본 적도 없었다."
  },
