  Stage_58386_Desc = {
    Text = "그녀는 양 눈을 감고, 우주의 공허 속에서 무작정 부유했다. \n일 년, 백 년…… 결국 어느 날, 그녀는 자신에게 말했다. 「상관없어. 진실타래과 거짓은 내가 정의할 거야.」 \n여왕과 그녀의 불멸의 도시 이사라우는 그렇게 우주의 광활한 은하에 머물렀다. \n그녀는 이사라우의 스토리를 나에게 전해주었는데, 그것은 영원히 기억되도록 하기 위해서였다."
