  Stage_58402_Name = {
    Text = "황금 도시·육"
  },
  Stage_58403_Desc = {
    Text = "황금 도시—— 이살라우.\n그 부는 끝이 없고, 그 욕망은 무한하다.\n그것은 마치 스펀지처럼 끊임없이 흘러드는 황금 물결을 흡수하며 팽창해 간다.\n이곳이 나의 수도다, 여왕이 말했다. 그녀는 자부심을 느꼈다."
  },
  Stage_58403_Name = {
    Text = "황금 도시·광기"
  },
  Stage_58403_StageInitStateText = {Text = "종말"},
  Stage_58404_Desc = {
    Text = "밤에 여왕은 궁전의 테라스에 서서 수천 피트 아래의 도시를 바라보았다. \n날이 갈수록, 그녀가 궁전을 한 발짝도 벗어나려고 할 때마다 기절, 눈물, 그리고 대규모의 기억 상실타래이 찾아왔다. \n「준비됐어요? 이 세상의 진실타래을 맞이할 준비가 되었나요?」 \n그녀는 깊게 숨을 들이쉬고, 테라스에서 뛰어내렸다."
  },
  Stage_58404_Name = {
    Text = "진실타래·육"
