  },
  Stage_58405_Name = {
    Text = "황금 도시·중 하나"
  },
  Stage_58406_Desc = {
    Text = "황금 도시—— 이살라우.\n그 부는 끝이 없고, 그 욕망은 무한하다.\n그것은 마치 스펀지처럼 끊임없이 흘러드는 황금 물결을 흡수하며 팽창해 간다.\n이곳이 나의 수도다, 여왕이 말했다. 그녀는 자부심을 느꼈다."
