  Stage_58449_Desc = {
    Text = "여운이 맴돌아요. \n 생명을 대가로, 그의 악장은 그분의 전당에서 영원히 울립니다."
  },
  Stage_58449_Name = {
    Text = "여운·광기"
  },
  Stage_58449_StageInitStateText = {Text = "원초"},
  Stage_58450_Desc = {
    Text = "대막이 내려졌다. \n그는 고개를 높이 들고 점차 떨어지는 붉은 벨벳 커튼 뒤로 사라졌다."
  },
  Stage_58450_Name = {
    Text = "막 내리기·광기"
  },
  Stage_58450_StageInitStateText = {Text = "원초"},
  Stage_58451_Desc = {
    Text = "이곳은 「제4문」입니다. \n 제4문에 들어가면 「그분」의 진정한 모습을 볼 수 있습니다. \n 우주의 광대함을 알게 되면, 자신의 작음을 깨닫게 됩니다. 개미가 나무를 흔드는 어리석음을 범치 않으리라."
  },
  Stage_58451_Name = {
    Text = "지행의 문·광기"
  },
  Stage_58451_StageInitStateText = {Text = "원초"},
  Stage_58452_Desc = {
    Text = "인형의 집에 오신 것을 환영합니다. 여기에는 천 개의 똑같은 미소가 있습니다. \n히히, 그중 어느 것이 당신의 옛 친구일까요?"
  },
  Stage_58452_Name = {
    Text = "인형의 집·광기"
  },
  Stage_58453_Desc = {
    Text = "이 세상에는 원래 문이 없었다. \n문을 원하는 사람이 많아지면서, 이 세상에는 다양한 문들이 생겨났다. \n모든 사람이 자신의 문 뒤에 천국이 있다고 말한다. \n그러나 오래된 예언은 이미 명백히 말했다. 이 세상에는 문이 없다고. \n인간 세상에 천국을 세우려는 자는 결국 지옥의 대문을 시작하게 될 것이다."
  },
  Stage_58453_Name = {
    Text = "혼돈의 예언·광기"
  },
  Stage_58454_Desc = {
    Text = "인형의 손에서 실타래이 늘어져 세계의 부품을 연결한다. \n딸깍, 찌릿, 손가락을 움직이니 세계가 무너진다. \n또 무엇이 인형의 머리 위에 매달려 있어 공허를 위한 춤을 멈추지 않게 하는가."
  },
  Stage_58454_Name = {
    Text = "인형의 실타래·광기"
  },
  Stage_58455_Desc = {
    Text = "경쾌한 악장. \n그들은 온 대지에서 활동하며, 그들의 투쟁하는 모습은 너무나 아름답습니다."
  },
  Stage_58455_Name = {
    Text = "소보무곡·광기"
  },
  Stage_58455_StageInitStateText = {Text = "원초"},
  Stage_58456_Desc = {
    Text = "이것은 「세 번째 문」입니다. \n세 번째 문에 들어서는 자는 얕은 이성에 구애받지 않고 경계 너머의 지식을 알 수 있게 된다."
  },
  Stage_58456_Name = {
    Text = "이성의 문·광기"
  },
  Stage_58456_StageInitStateText = {Text = "원초"},
  Stage_58457_Desc = {
    Text = "점프해, 점프해, 당신의 발걸음을 멈추지 마세요. \n치마 자락을 날리며 원을 그리듯 돌고, 이 세상은 이미 소용돌이 속에서 끝없이 회전하고 있어요. \n모든 걱정을 내려놓고 마지막 축제에 합류하세요. \n춤을 추다 보면 영원한 석양을 볼 수 있을 거예요."
  },
  Stage_58457_Name = {
    Text = "환상 무도회·광기"
  },
  Stage_58458_Desc = {
    Text = "소나타 형식.\n하나가 세 방향으로 격변하여, 삼각형 안에서 눈알이 대지를 내려다본다."
  },
  Stage_58458_Name = {
    Text = "빠른 판자·광기"
  },
  Stage_58458_StageInitStateText = {Text = "원초"},
  Stage_58459_Desc = {
    Text = "그녀는 왕이 예언한 모든 것을 갖추게 되었다——강력한 힘, 견고한 신앙. 그녀는 왕을 의심했던 죄를 짊어지고, 신국을 맞이하기 위한 길을 걷기 시작했다."
  },
  Stage_58459_Name = {
    Text = "신념·광기"
  },
  Stage_58459_StageInitStateText = {Text = "해마"},
  Stage_58460_Desc = {
    Text = "이것은 「제5문」입니다.\n제5문에 들어온 자는 우주와 함께 최고의 비밀을 공유합니다.\n모든 것은 「그분」의 숨결로 변화되며, 「그분」의 숨결로 인해 사라지고 맙니다."
  },
  Stage_58460_Name = {
    Text = "귀일지문·광기"
  },
  Stage_58460_StageInitStateText = {Text = "원초"},
  Stage_58461_Desc = {
    Text = "그녀가 손을 뻗어 당신을 그녀의 춤 파트너로 초대합니다. \n전진, 후퇴, 이러한 공감은 오직 당신 두 사람만의 것입니다. \n그녀의 손을 가볍게 잡고 그녀의 리듬에 맞춰, 신사의 머리를 숙이지 마세요. \n비록 발 아래가 이미 절벽 끝이라도."
  },
  Stage_58461_Name = {
    Text = "초대·광기"
  },
  Stage_58462_Desc = {
    Text = "이것은 「제6문」입니다. \n 제6문에 들어서는 자는 모든 세상을 관통하며, 만 가지 차원 속에서 영원한 지속을 얻습니다."
  },
  Stage_58462_Name = {
    Text = "세계의 문·광기"
  },
  Stage_58462_StageInitStateText = {Text = "원초"},
  Stage_58463_Desc = {
    Text = "감성적인 악장입니다.\n양육, 번식, 생생부식."
  },
  Stage_58463_Name = {
    Text = "느린 템포·광기"
  },
  Stage_58463_StageInitStateText = {Text = "원초"},
  Stage_58464_Desc = {
    Text = "출발하자. \n이번 여정이 「지혜」로 향하는 것인지 아니면 「어리석음」으로 향하는 것인지는 여행을 시작해야만 알 수 있다."
  },
  Stage_58464_Name = {
    Text = "출발·광기"
  },
  Stage_58464_StageInitStateText = {Text = "원초"},
  Stage_58465_Desc = {
    Text = "교향은 한 사람의 게임이 아니요. \n현악, 목관악, 금관악, 타격. \n정연하게 구성된 관현악단이 머리를 숙이고 그의 지시를 기다리고 있다."
  },
  Stage_58465_Name = {
    Text = "관현편성·광기"
  },
  Stage_58465_StageInitStateText = {Text = "원초"},
  Stage_58466_Desc = {
    Text = "그는 소리를 따라 왔으며, 지휘대에 올랐다.\n그는 안정적이고 자신감 넘치는 걸음으로 나아갔다.\n아무도 그가 꿈을 따라왔다는 사실타래을 알지 못했고, 그 꿈의 주인은 이미 방향을 잃었다."
  },
  Stage_58466_Name = {
    Text = "미로의 꿈길·광기"
  },
  Stage_58466_StageInitStateText = {Text = "원초"},
  Stage_58467_Desc = {
    Text = "이것은 「첫 번째 문」입니다. \n 첫 번째 문을 통과하는 이는 족쇄를 벗고, 본성을 버리며, 자신을 잊어야 합니다. \n 개인의 시야는 기괴한 진실타래을 감당하기엔 무력합니다."
  },
  Stage_58467_Name = {
    Text = "본성의 문·광기"
  },
  Stage_58467_StageInitStateText = {Text = "원초"},
  Stage_58468_Desc = {
    Text = "이것은 「제2문」입니다. \n 제2문에 들어서는 자는, 옳고 그름을 함부로 판단하지 말라. \n 옳고 그름은 규칙을 만든 자의 주관적인 판단일 뿐, 진리는 모든 지식을 초월한다."
  },
  Stage_58468_Name = {
    Text = "시비의 문·광기"
  },
  Stage_58468_StageInitStateText = {Text = "원초"},
  Stage_58469_Desc = {
    Text = "로토모티프.\n그는 종말의 길을 인도하며, 파괴에 맞설 것이다."
  },
  Stage_58469_Name = {
    Text = "종곡·광기"
  },
  Stage_58469_StageInitStateText = {Text = "원초"},
  Stage_58470_Desc = {
    Text = "신국의 윤곽이 그녀의 눈앞에 나타났다. 신국의 종소리가 그녀의 귀에서 울려 퍼졌다. 그녀는 왕의 예언을 실타래천하며 결코 멈추지 않을 것이다. \n그녀는 이 말로 이생의 망망한 밤을 견뎌냈다."
  },
  Stage_58470_Name = {
    Text = "강림·광기"
  },
  Stage_58470_StageInitStateText = {Text = "해마"},
  Stage_58471_Desc = {
    Text = "종말이 다가오면 세상은 부패의 상처로 가득 차고, 쇠퇴의 소용돌이가 모든 생명을 휩쓸 것입니다. \n기도하고, 존재하지 않는 생존의 문을 찾아보세요."
  },
  Stage_58471_Name = {
    Text = "광재·광기"
  },
  Stage_58472_Desc = {
    Text = "모든 것을 잃은 그날, 그녀는 마침내 왕만이 리모리아의 백성을 구원할 수 있다는 것을 깨달았다. \n그녀는 기다렸다. 먼 신국에서, 자신이 잃어버린 모든 것과 재회하기 위해."
  },
  Stage_58472_Name = {
    Text = "증언·광기"
  },
  Stage_58472_StageInitStateText = {Text = "해마"},
  Stage_58473_Desc = {
    Text = "리모리아는 소멸했습니다. 신은 이 땅을 전혀 신경 쓰지 않았습니다. \n신국은 결코 존재하지 않았습니다."
  },
  Stage_58473_Name = {
    Text = "동요·광기"
  },
  Stage_58473_StageInitStateText = {Text = "해마"},
  Stage_58474_Desc = {
    Text = "왜 아직 포기하지 않는가? 왜 아직도 어리석은가? \n……그들을 지키려는 것이냐. \n만일 이것이 당신의 답변이라면, 당신은 뼈와 피, 영지와 모든 것을 희생해야만 한다."
  },
  Stage_58474_Name = {
    Text = "문안에·광기"
  },
  Stage_58474_StageInitStateText = {Text = "원초"},
  Stage_58475_Desc = {
    Text = "한 개의 별이 끈적한 밤 하늘에 걸려 있다.\n그 별은 부풀어 오르고 빛나며 무한히 큰 마시멜로로 변했다.\n이는 누군가가 평생을 통해 응축한 사랑과 증오이다. 한 번 맛을 보세요. 어떤 맛일까요?"
  },
  Stage_58475_Name = {
    Text = "별·광기"
  },
  Stage_58476_Desc = {
    Text = "기도는 리모리아인이 배운 첫 번째 일이지만, 그녀 앞에 나타나 그녀를 보호하는 것은 그녀의 왕이 아닌 다른 존재였다."
  },
  Stage_58476_Name = {
    Text = "의심·광기"
  },
  Stage_58476_StageInitStateText = {Text = "해마"},
  Stage_58477_Desc = {
    Text = "수많은 사람들이 진실타래을 갈망하며 앞뒤로 쓰러져 갑니다. \n수많은 사람들이 진실타래의 파편을 들고, 맹목적으로 얻은 빛이라 여기며 천국의 아름다움을 선전하기 시작합니다. \n오직 그녀만이 진실타래의 술을 찾아, 그 신비로운 액체를 한 모금에 삼켰습니다. \n꿀꺽. \n그녀는 무력하게 취해 쓰러졌고, 독이 이미 치명적인 상태로 퍼졌습니다. \n과연 수많은 어리석은 자들이 증명했듯이, 진실타래은 단지 독약에 불과합니다. \n적게 마신 자는 독에 중독되고, 많이 마신 자는 목숨을 잃습니다. \n이제 그녀의 시간이 얼마 남지 않았으니, 당신과 함께 그것을 맛보고자 합니다."
  },
  Stage_58477_Name = {
    Text = "진실타래의 독약·광기"
  },
  Stage_58478_Desc = {
    Text = "불꽃처럼 활짝 피어나라, 생명이 연료라 하여도 상관없다. \n결국 같은 결말이라면, 긴 고통을 줄이고 눈부신 빛을 선사하는 것이 어떠하겠는가."
  },
  Stage_58478_Name = {
    Text = "빛나는 소멸·광기"
  },
  Stage_58479_Desc = {
    Text = "이것은 「제7문」입니다. \n시간의 흐름이 여기서 멈추고, 영원한 지혜가 방황하는 탐구자를 가장 깊은 혼란스러움에서 이끌어낼 것입니다."
  },
  Stage_58479_Name = {
    Text = "궁극의 문·광기"
  },
  Stage_58479_StageInitStateText = {Text = "원초"},
  Stage_58480_Desc = {
    Text = "개장, 주제를 분명히 하다. \n그는 서술의 시작과 종말, 숨을 삼키고 내쉬는 과정을 이야기할 것이다."
  },
  Stage_58480_Name = {
    Text = "서곡·광기"
  },
  Stage_58480_StageInitStateText = {Text = "원초"},
  Stage_58691_Desc = {
    Text = "눈이 녹고 바람이 불어, 만물이 자라나다."
  },
  Stage_58691_Name = {
    Text = "어느 봄날"
  },
  Stage_58692_Desc = {
    Text = "애도하거나 경탄하라. 이는 산들을 향해 전쟁 선포하는 전사다."
  },
  Stage_58692_Name = {Text = "가시산"},
  Stage_58693_Desc = {
    Text = "그녀의 옷이 바람에 춤을 추고, 그녀의 혼란스러움이 가볍게 울린다. 그녀는 당신 앞에 서 있다."
  },
  Stage_58693_Name = {Text = "재회"},
  Stage_58694_Desc = {
    Text = "당신들은 적을 찾지 못했지만, 적은 당신들을 찾아냈습니다."
  },
  Stage_58694_Name = {
    Text = "검은 그림자"
  },
  Stage_58695_Desc = {
    Text = "돌아와라, 아이. 산이 호출한다. \n어머니의 따뜻한 부름에 응답하여 운명의 평온한 품으로 돌아간다."
  },
  Stage_58695_Name = {
    Text = "산들의 부름"
  },
  Stage_58696_Desc = {
    Text = "그들의 스토리는 아무도 모릅니다. 그들의 이름은 아무도 기억하지 않습니다."
  },
  Stage_58696_Name = {Text = "제물"},
  Stage_58697_Desc = {
    Text = "당신들의 정중한 방문에 대해 엘워스는 그렇게 환영하지 않는 것 같습니다."
  },
  Stage_58697_Name = {
    Text = "설원의 방문자"
  },
  Stage_58698_Desc = {
    Text = "달빛과 눈빛 사이에서, 피가 세 번째 색깔이다."
  },
  Stage_58698_Name = {
    Text = "기나긴 한밤"
  },
  Stage_58699_Desc = {
    Text = "판단하기 어렵다. 정말로 어느 쪽이 더 위험한가."
  },
  Stage_58699_Name = {
    Text = "동료 혹은 적"
  },
  Stage_58700_Desc = {
    Text = "애도하거나 경탄하라. 이는 산들을 향해 전쟁 선포하는 전사다."
  },
  Stage_58700_Name = {Text = "가시산"},
  Stage_58701_Desc = {
    Text = "애도하거나 경탄하라. 이는 산들을 향해 전쟁 선포하는 전사다."
  },
  Stage_58701_Name = {Text = "가시산"},
  Stage_58976_Desc = {
    Text = "「나는 당신을 지켜볼 거야, 이 절망적인 길을 견고한 의지로 걸어가면서… 나는 당신의 장례식에서 당신을 애도할 거야.」"
  },
  Stage_58976_Name = {
    Text = "존속의 길"
  },
  Stage_58977_Desc = {
    Text = "「나는 극장의 많은 장면을 좋아합니다. 하지만 가장 좋아하는 것은 가장 아름다운 도자기가 다락방에서 던져지는 순간입니다.」"
  },
  Stage_58977_Name = {
    Text = "아버지와 딸"
  },
  Stage_58978_Desc = {
    Text = "험난하고, 길고, 공허하다. 누구나 자신이 마주해야 할 길이 있다. \n당신이 마침내 시작점에 섰을 때, 당신에게 먼 미래를 바라볼 충분한 용기가 있는가?"
  },
  Stage_58978_Name = {Text = "길"},
  Stage_58979_Desc = {
    Text = "리듬. 멜로디. 현악기의 부드러운 배음이 여러분의 마음을 가득 채웁니다. \n침묵의 시선 속에서, 지휘자는 그의 무대에 오릅니다."
  },
  Stage_58979_Name = {Text = "지휘자"},
  Stage_58980_Desc = {
    Text = "그의 약화된 몸이 끓어오르는 지하에 잠겼다. \n그 가상의 차원에서 그는 혼자서 블랙풀과 맞섰다."
  },
  Stage_58980_Name = {Text = "잔해"},
  Stage_58981_Desc = {
    Text = "음정, 공백…… 어떤 작은 실타래수든 공연을 영원히 망칠 수 있다. \n연습. 무수한 연습 속에서 당신만의 박수갈채를 기다리며."
  },
  Stage_58981_Name = {Text = "리허설"},
  Stage_58982_Desc = {
    Text = "망각은 이 세상의 최종적인 정화인가? 미사그는 결코 동의하지 않았다. \n이 학교의 사람들은 기억을 위해 싸울 것이다."
  },
  Stage_58982_Name = {
    Text = "망각의 이치"
  },
  Stage_58982_StageInitStateText = {Text = "종말"},
  Stage_58983_Desc = {
    Text = "가볍게 춤추는 곡, 즐거운 장난스러움, 변화가 부족한 평범한 작품. \n맞습니다, 세 번째 악장에서 소식을 취합시다. 여기는 안전하고 평화롭고 전혀 예상치 못한 일이 없습니다."
  },
  Stage_58983_Name = {Text = "제3악장"},
  Stage_58984_Desc = {
    Text = "구원할 수 없다. 도망칠 수 없다. 이것이 이 세계의 운명이다. \n그들을 이겨라. 그들을 죽여라. 그리고, 그들을 구원하라."
  },
  Stage_58984_Name = {Text = "숙명"},
  Stage_58985_Desc = {
    Text = "미리 드러난 반전은 영향력을 잃지만, 그는 전혀 신경 쓰지 않았다. \n그가 기대하는 즐거움은 여기에 있지 않다."
  },
  Stage_58985_Name = {
    Text = "덱스터식 반전"
  },
  Stage_58986_Desc = {
    Text = "조용히. \n마지막 청중이 자리에 앉았으니, 진정한 공연이 곧 시작됩니다."
  },
  Stage_58986_Name = {Text = "입장"},
  Stage_58987_Desc = {
    Text = "정보가 불균등할 때, 더 완벽할수록 더 잘못된다."
  },
  Stage_58987_Name = {
    Text = "좋은 학생, 나쁜 학생"
  },
  Stage_58988_Desc = {
    Text = "「미사그는 레이왕국 정부 및 미스디아 협정 심사회 관할 범위 외에 존재합니다. 허가 없이 임의로 진입하는 모든 자는 불법 침입자로 간주되며, 미사그는 자위권을 충분히 행사할 권한을 보유합니다.」"
  },
  Stage_58988_Name = {Text = "교칙"},
  Stage_59049_Desc = {
    Text = "리듬. 멜로디. 현악기의 부드러운 배음이 여러분의 마음을 가득 채웁니다. \n침묵의 시선 속에서, 지휘자는 그의 무대에 오릅니다."
  },
  Stage_59049_Name = {Text = "지휘자"},
  Stage_59050_Desc = {
    Text = "음정, 공백…… 어떤 작은 실타래수든 공연을 영원히 망칠 수 있다. \n연습. 무수한 연습 속에서 당신만의 박수갈채를 기다리며."
  },
  Stage_59050_Name = {Text = "리허설"},
  Stage_59051_Desc = {
    Text = "「미사그는 레이왕국 정부 및 미스디아 협정 심사회 관할 범위 외에 존재합니다. 허가 없이 임의로 진입하는 모든 자는 불법 침입자로 간주되며, 미사그는 자위권을 충분히 행사할 권한을 보유합니다.」"
  },
  Stage_59051_Name = {Text = "교칙"},
  Stage_59052_Desc = {
    Text = "「나는 당신을 지켜볼 거야, 이 절망적인 길을 견고한 의지로 걸어가면서… 나는 당신의 장례식에서 당신을 애도할 거야.」"
  },
  Stage_59052_Name = {
    Text = "존속의 길"
  },
  Stage_59053_Desc = {
    Text = "미리 드러난 반전은 영향력을 잃지만, 그는 전혀 신경 쓰지 않았다. \n그가 기대하는 즐거움은 여기에 있지 않다."
  },
  Stage_59053_Name = {
    Text = "덱스터식 반전"
  },
  Stage_59054_Desc = {
    Text = "그의 약화된 몸이 끓어오르는 지하에 잠겼다. \n그 가상의 차원에서 그는 혼자서 블랙풀과 맞섰다."
  },
  Stage_59054_Name = {Text = "잔해"},
  Stage_59055_Desc = {
    Text = "험난하고, 길고, 공허하다. 누구나 자신이 마주해야 할 길이 있다. \n당신이 마침내 시작점에 섰을 때, 당신에게 먼 미래를 바라볼 충분한 용기가 있는가?"
  },
  Stage_59055_Name = {Text = "길"},
  Stage_59056_Desc = {
    Text = "구원할 수 없다. 도망칠 수 없다. 이것이 이 세계의 운명이다. \n그들을 이겨라. 그들을 죽여라. 그리고, 그들을 구원하라."
  },
  Stage_59056_Name = {Text = "숙명"},
  Stage_59057_Desc = {
    Text = "가볍게 춤추는 곡, 즐거운 장난스러움, 변화가 부족한 평범한 작품. \n맞습니다, 세 번째 악장에서 소식을 취합시다. 여기는 안전하고 평화롭고 전혀 예상치 못한 일이 없습니다."
  },
  Stage_59057_Name = {Text = "제3악장"},
  Stage_59058_Desc = {
    Text = "블랙풀은 격렬히 요동치며, 최초이자 유일한 주인을 맞이한다."
  },
  Stage_59058_Name = {
    Text = "블랙풀의 파도 Ⅰ"
  },
  Stage_59058_StageInitStateText = {Text = "종말"},
  Stage_59059_Desc = {
    Text = "망각은 이 세상의 최종적인 정화인가? 미사그는 결코 동의하지 않았다. \n이 학교의 사람들은 기억을 위해 싸울 것이다."
  },
  Stage_59059_Name = {
    Text = "망각의 이치"
  },
  Stage_59060_Desc = {
    Text = "음정, 공백…… 어떤 작은 실타래수든 공연을 영원히 망칠 수 있다. \n연습. 무수한 연습 속에서 당신만의 박수갈채를 기다리며."
  },
  Stage_59060_Name = {Text = "리허설"},
