  Stage_59077_Desc = {
    Text = "미사그의 지하에는 이 세계의 첫 번째이자 마지막 재앙이 숨겨져 있다."
  },
  Stage_59077_Name = {
    Text = "원초의 균열 Ⅱ"
  },
  Stage_59502_Desc = {
    Text = "가장 원초적인 절망을 마주하라. 가장 원초적인 두려움을 마주하라. \n보이지 않는 서로의 곁에 서서, 그리고 그분을 이겨내라."
  },
  Stage_59502_Name = {
    Text = "결전: 원초의 그림자"
  },
  Stage_59503_Desc = {
    Text = "기억은 당신의 서약이고, 망각은 당신의 제례다."
  },
  Stage_59503_Name = {Text = "제례"},
  Stage_59503_StageInitStateText = {Text = "원초"},
  Stage_59504_Desc = {
    Text = "꿈의 신전에 서서 무너진 잔해를 지탱합니다. \n당신 아래, 당신이 아끼고 염려하는 모든 것을 담은 먼지를 수호합니다."
  },
  Stage_59504_Name = {
    Text = "꿈의 붕괴"
  },
  Stage_59504_StageInitStateText = {Text = "원초"},
  Stage_59505_Desc = {
    Text = "「생존할 것인가, 아니면 파멸을 마주할 것인가?」"
  },
  Stage_59505_Name = {Text = "안내자"},
  Stage_59505_StageInitStateText = {Text = "원초"},
  Stage_59506_Desc = {
    Text = "기억은 당신의 서약이고, 망각은 당신의 제례다."
  },
  Stage_59506_Name = {Text = "제례"},
  Stage_59506_StageInitStateText = {Text = "원초"},
  Stage_59507_Desc = {
    Text = "꿈의 신전에 서서 무너진 잔해를 지탱합니다. \n당신 아래, 당신이 아끼고 염려하는 모든 것을 담은 먼지를 수호합니다."
  },
  Stage_59507_Name = {
    Text = "꿈의 붕괴"
  },
  Stage_59507_StageInitStateText = {Text = "원초"},
  Stage_59508_Desc = {
    Text = "「생존할 것인가, 아니면 파멸을 마주할 것인가?」"
  },
  Stage_59508_Name = {Text = "안내자"},
  Stage_59509_Desc = {
    Text = "「생존할 것인가, 아니면 파멸을 마주할 것인가?」"
  },
  Stage_59509_Name = {Text = "안내자"},
  Stage_59509_StageInitStateText = {Text = "원초"},
  Stage_59510_Desc = {
    Text = "꿈의 신전에 서서 무너진 잔해를 지탱합니다. \n당신 아래, 당신이 아끼고 염려하는 모든 것을 담은 먼지를 수호합니다."
  },
  Stage_59510_Name = {
    Text = "꿈의 붕괴"
  },
  Stage_59511_Desc = {
    Text = "기억은 당신의 서약이고, 망각은 당신의 제례다."
  },
  Stage_59511_Name = {Text = "제례"},
  Stage_62348_Desc = {
    Text = "이것은 별들의 절정입니다. 이것은 우주의 막을 내리는 순간입니다. \n이 조용한 가운데, 집중해서 귀를 기울여 보세요——\n그 진정한 음표, 들으셨나요?"
  },
  Stage_62348_Name = {Text = "피날레"},
  Stage_66016_Desc = {
    Text = "그는 최고의 의지, 우주의 조물주, 만물의 말씀자입니다. \n그분 앞에서 슬피 울어보세요. 당신들의 연약한 용기와 그분의 끝없는 권능을 위해."
  },
  Stage_66016_Name = {
    Text = "빈민원·슬픔의 시선"
  },
  Stage_66016_StageInitStateText = {Text = "원초"},
  Stage_66017_Desc = {
    Text = "그는 최고의 의지, 우주의 조물주, 만물의 말씀자입니다. \n그분 앞에서 슬피 울어보세요. 당신들의 연약한 용기와 그분의 끝없는 권능을 위해."
  },
  Stage_66017_Name = {
    Text = "빈민원·슬픔의 시선"
  },
  Stage_66017_StageInitStateText = {Text = "원초"},
  Stage_66018_Desc = {
    Text = "그는 최고의 의지, 우주의 조물주, 만물의 말씀자입니다. \n그분 앞에서 슬피 울어보세요. 당신들의 연약한 용기와 그분의 끝없는 권능을 위해."
  },
  Stage_66018_Name = {
    Text = "빈민원·슬픔의 시선"
  },
  Stage_66381_Desc = {
    Text = "걱정하지 마세요, 공포는 생명체의 가장 원시적인 본능입니다. \n신은 어느 작은 존재도 곤란하게 하지 않습니다. 그분은 깨어남을 통해 여러분에게 축복을 내립니다."
  },
  Stage_66381_Name = {
    Text = "밀랍인형관·공포의 시선"
  },
  Stage_66381_StageInitStateText = {Text = "원초"},
  Stage_66382_Desc = {
    Text = "노래하라, 위대한 조물주! \n그분이 꿈을 꾸실타래 때, 백성들은 번영한다. \n그분이 눈 뜰 때, 만물이 먼지로 변한다."
  },
  Stage_66382_Name = {
    Text = "브리지포트·모독의 시선"
  },
  Stage_66382_StageInitStateText = {Text = "원초"},
  Stage_66383_Desc = {
    Text = "고통을 체감하라, 최고의 의지가 내리는 가장 원초적인 선물이다. \n고통 속에서 조물주의 위엄을 엿본다."
  },
  Stage_66383_Name = {
    Text = "라이·참혹의 시선"
  },
  Stage_66383_StageInitStateText = {Text = "원초"},
  Stage_66384_Desc = {
    Text = "투쟁하지 마십시오. 저항하지 마십시오. 이해할 수 없는 것을 이해하려 하지 마십시오. \n최고의 의지 아래, 꿈의 종말을 맞이하십시오."
  },
  Stage_66384_Name = {
    Text = "요양원·기만의 시선"
  },
  Stage_66384_StageInitStateText = {Text = "원초"},
  Stage_66385_Desc = {
    Text = "그는 최고의 의지, 우주의 조물주, 만물의 말씀자입니다. \n그분 앞에서 슬피 울어보세요. 당신들의 연약한 용기와 그분의 끝없는 권능을 위해."
  },
  Stage_66385_Name = {
    Text = "빈민원·슬픔의 시선"
  },
  Stage_66385_StageInitStateText = {Text = "원초"},
  Stage_67123_Desc = {
    Text = "그 웅장한 문명, 인간의 비극과 희열, 당신을 둘러싸고 멀어지는 수많은 사람들, 그들은 결코 존재하지 않았다. 꿈의 해체, 결국 도래할 것이다. \n수호자들이여, 망각하라. 망각은 가장 엄숙한 고통이다. \n망각은 축복과도 같은 해법이다."
  },
  Stage_67123_Name = {
    Text = "레무바시·탄생의 시선"
  },
  Stage_67123_StageInitStateText = {Text = "원초"},
  Stage_67124_Desc = {
    Text = "맹목한 어리석음의 물결 위에서, 질서의 누각이 굉음과 함께 무너졌다. \n이성은 한 번도 존재한 적 없으며, 광기만이 너희의 최종 귀결이다."
  },
  Stage_67124_Name = {
    Text = "소나닐 호·광기의 시선"
  },
  Stage_67124_StageInitStateText = {Text = "원초"},
  Stage_67897_Desc = {
    Text = "맹목한 어리석음의 물결 위에서, 질서의 누각이 굉음과 함께 무너졌다. \n이성은 한 번도 존재한 적 없으며, 광기만이 너희의 최종 귀결이다."
  },
  Stage_67897_Name = {
    Text = "소나닐 호·광기의 시선"
  },
  Stage_67898_Desc = {
    Text = "노래하라, 위대한 조물주! \n그분이 꿈을 꾸실타래 때, 백성들은 번영한다. \n그분이 눈 뜰 때, 만물이 먼지로 변한다."
  },
  Stage_67898_Name = {
    Text = "브리지포트·모독의 시선"
  },
  Stage_67899_Desc = {
    Text = "투쟁하지 마십시오. 저항하지 마십시오. 이해할 수 없는 것을 이해하려 하지 마십시오. \n최고의 의지 아래, 꿈의 종말을 맞이하십시오."
  },
  Stage_67899_Name = {
    Text = "요양원·기만의 시선"
  },
  Stage_67900_Desc = {
    Text = "고통을 체감하라, 최고의 의지가 내리는 가장 원초적인 선물이다. \n고통 속에서 조물주의 위엄을 엿본다."
  },
  Stage_67900_Name = {
    Text = "라이·참혹의 시선"
  },
  Stage_67901_Desc = {
    Text = "걱정하지 마세요, 공포는 생명체의 가장 원시적인 본능입니다. \n신은 어느 작은 존재도 곤란하게 하지 않습니다. 그분은 깨어남을 통해 여러분에게 축복을 내립니다."
  },
