  },
  Stage_67911_StageInitStateText = {Text = "원초"},
  Stage_67912_Desc = {
    Text = "그 웅장한 문명, 인간의 비극과 희열, 당신을 둘러싸고 멀어지는 수많은 사람들, 그들은 결코 존재하지 않았다. 꿈의 해체, 결국 도래할 것이다. \n수호자들이여, 망각하라. 망각은 가장 엄숙한 고통이다. \n망각은 축복과도 같은 해법이다."
  },
  Stage_67912_Name = {
    Text = "레무바시·탄생의 시선"
  },
  Stage_67912_StageInitStateText = {Text = "원초"},
  Stage_67913_Desc = {
    Text = "개미에게 있어, 생존과 파멸은 문제가 되지 않는다.\n그들은 태어나면서부터 거대한 나무와 맞설 운명이다."
  },
  Stage_67913_Name = {Text = "개미"},
  Stage_67913_StageInitStateText = {Text = "원초"},
  Stage_67914_Desc = {
    Text = "{Male=그,Female=그녀}의 이름과 업적은 누구에게도 알려지지 않을 것이다. {Male=그,Female=그녀}는 망각에서 왔고, 다시 망각으로 돌아갈 것이다. 오직 묘비에 새겨진 교훈만이 세상에 남는다.\n은빛 열쇠는 한때 {Male=그,Female=그녀}의 앞길을 인도했다. 앞으로의 길 또한, 은빛 열쇠가 우리를 비추기를 바란다."
  },
  Stage_67914_Name = {
    Text = "작별 인사: K-0617"
  },
