    Text = "재생화는 영원한 순환입니다. \n 생명이 가장 왕성할 때, 잊지 말아야 합니다: 낮과 밤의 비밀, 그리고 계절의 속삭임은 꽃이 지면서 사라집니다. \n 죽음이 끝이라면, 탄생은 시작입니다."
