  Stage_70110_StageInitStateText = {Text = "번식"},
  Stage_70111_Desc = {
    Text = "수분은 먼 곳에서의 만남입니다. \n꽃가지가 흔들리며 춤을 추는 사자에게 초대를 보내, 꽃가루를 수집하여, 꽃 사이를 유영하며, 자연의 리듬 속에서 새로운 생명의 원천을 다른 기다리는 품으로 전합니다."
