  Stage_70111_Name = {
    Text = "수분-망언 육"
  },
  Stage_70402_Desc = {
    Text = "검은 고양이는 이 순간에 취하여, 목에서 신비한 저어가 흘러나오며, 마치 세상의 진리가 전부 여기에 모인 것 같다 \n미야우, 미야오, 미야우우오 \n당신은 이해하지 못하지만, 그것이 당신이 그 요란한 소리를 멈추게 하고 싶다는 것을 방해하지는 않는다"
  },
