  Stage_70404_Desc = {
    Text = "검은 고양이는 이 순간에 취하여, 목에서 신비한 저어가 흘러나오며, 마치 세상의 진리가 전부 여기에 모인 것 같다 \n미야우, 미야오, 미야우우오 \n당신은 이해하지 못하지만, 그것이 당신이 그 요란한 소리를 멈추게 하고 싶다는 것을 방해하지는 않는다"
  },
  Stage_70404_Name = {
    Text = "고양이의 속삭임·세 번째"
  },
  Stage_70405_Desc = {
    Text = "악마 같은 검은 고양이가 교활하게 웃자, 당신은 지갑이 찢어진 듯한 흔적을 발견했다. \n맞은편 고양이의 모자 속에서 은심의 빛이 순간적으로 반짝였습니다."
  },
  Stage_70405_Name = {
    Text = "고양이의 꾀·세 번째"
  },
  Stage_70406_Desc = {
    Text = "악마 같은 검은 고양이가 교활하게 웃자, 당신은 지갑이 찢어진 듯한 흔적을 발견했다. \n맞은편 고양이의 모자 속에서 은심의 빛이 순간적으로 반짝였습니다."
  },
  Stage_70406_Name = {
    Text = "고양이의 꾀·둘째"
  },
  Stage_70407_Desc = {
    Text = "악마 같은 검은 고양이가 교활하게 웃자, 당신은 지갑이 찢어진 듯한 흔적을 발견했다. \n맞은편 고양이의 모자 속에서 은심의 빛이 순간적으로 반짝였습니다."
  },
  Stage_70407_Name = {
    Text = "고양이의 꾀·중 하나"
  },
  Stage_70408_Desc = {
    Text = "검은 고양이가 눈을 가늘게 뜨고 당신을 바라봅니다. 고양이의 세계에서 그것은 좋아하는 의미입니다. \n당신을 좋아하는 검은 고양이가 뛰어다니며 당신의 종아리를 살짝 두드리지만, 그것은 폭력이 아니라 사랑의 놀이입니다."
  },
  Stage_70408_Name = {
    Text = "고양이의 선호· 중 하나"
  },
  Stage_70409_Desc = {
    Text = "검은 고양이가 눈을 가늘게 뜨고 당신을 바라봅니다. 고양이의 세계에서 그것은 좋아하는 의미입니다. \n당신을 좋아하는 검은 고양이가 뛰어다니며 당신의 종아리를 살짝 두드리지만, 그것은 폭력이 아니라 사랑의 놀이입니다."
  },
  Stage_70409_Name = {
    Text = "고양이의 선호·세 번째"
  },
  Stage_70410_Desc = {
    Text = "검은 고양이가 눈을 가늘게 뜨고 당신을 바라봅니다. 고양이의 세계에서 그것은 좋아하는 의미입니다. \n당신을 좋아하는 검은 고양이가 뛰어다니며 당신의 종아리를 살짝 두드리지만, 그것은 폭력이 아니라 사랑의 놀이입니다."
  },
  Stage_70410_Name = {
    Text = "고양이의 선호·둘째"
  },
  Stage_70411_Desc = {
    Text = "고양이 귀가 회전하고, 고양이 발바닥이 뛰어오르며, 꼬리가 서 있습니다. \n당신과의 차차 춤에서 고양이의 행복이 넘쳐나는 것이 분명합니다."
  },
  Stage_70411_Name = {
    Text = "고양이의 기쁨·중 하나"
  },
  Stage_70412_Desc = {
    Text = "고양이의 발톱이 당신 앞에서 쉬지 않고 시험해 보며, 내밀었다가 빼고, 다시 내밀었다가 빼고 합니다. \n 검은 발자국이 당신의 교복 구두 위에 찍혔습니다. \n 당신은 참을 수 없어 주먹을 불끈 쥐었습니다."
  },
  Stage_70412_Name = {
    Text = "고양이의 발자국·중 하나"
  },
  Stage_70413_Desc = {
    Text = "익숙한 검은 고양이는 분명히 당신에 대한 기억도 가지고 있으며, 그것은 예를 표하기 위해 모자를 벗습니다. \n어디서 가져왔는지 모르는 흰 장갑이 당신 앞에 던져졌습니다. 이것은 인사가 아니라, 신사의 결투 초대입니다."
  },
  Stage_70413_Name = {
    Text = "고양이의 인사·중 하나"
  },
  Stage_70414_Desc = {
    Text = "익숙한 검은 고양이는 분명히 당신에 대한 기억도 가지고 있으며, 그것은 예를 표하기 위해 모자를 벗습니다. \n어디서 가져왔는지 모르는 흰 장갑이 당신 앞에 던져졌습니다. 이것은 인사가 아니라, 신사의 결투 초대입니다."
  },
  Stage_70414_Name = {
    Text = "고양이의 인사·세 번째"
  },
  Stage_70415_Desc = {
    Text = "익숙한 검은 고양이는 분명히 당신에 대한 기억도 가지고 있으며, 그것은 예를 표하기 위해 모자를 벗습니다. \n어디서 가져왔는지 모르는 흰 장갑이 당신 앞에 던져졌습니다. 이것은 인사가 아니라, 신사의 결투 초대입니다."
  },
  Stage_70415_Name = {
    Text = "고양이의 인사·둘째"
  },
  Stage_70416_Desc = {
    Text = "오늘 밤은 얼마나 즐거운가, 모든 것이 고양이에게 잊지 못할 추억을 남깁니다!\n맑은 달빛이 꽃무늬 창을 통해 환한 파티에 비춰지게 하세요!\n아, 고양이를 찬미합니다!"
  },
  Stage_70416_Name = {
    Text = "고양이의 축제·둘째"
  },
  Stage_70417_Desc = {
    Text = "고양이 귀가 회전하고, 고양이 발바닥이 뛰어오르며, 꼬리가 서 있습니다. \n당신과의 차차 춤에서 고양이의 행복이 넘쳐나는 것이 분명합니다."
  },
  Stage_70417_Name = {
    Text = "고양이의 기쁨·둘째"
  },
  Stage_70418_Desc = {
    Text = "고양이의 발톱이 당신 앞에서 쉬지 않고 시험해 보며, 내밀었다가 빼고, 다시 내밀었다가 빼고 합니다. \n 검은 발자국이 당신의 교복 구두 위에 찍혔습니다. \n 당신은 참을 수 없어 주먹을 불끈 쥐었습니다."
  },
  Stage_70418_Name = {
    Text = "고양이의 발자국·세 번째"
  },
  Stage_70419_Desc = {
    Text = "고양이의 발톱이 당신 앞에서 쉬지 않고 시험해 보며, 내밀었다가 빼고, 다시 내밀었다가 빼고 합니다. \n 검은 발자국이 당신의 교복 구두 위에 찍혔습니다. \n 당신은 참을 수 없어 주먹을 불끈 쥐었습니다."
  },
  Stage_70419_Name = {
    Text = "고양이의 발자국·둘째"
  },
  Stage_70420_Desc = {
    Text = "고양이 파티에서 마음껏 노래를 부르세요. 즐거운 술잔을 높이 들고, 검은 고양이가 당신의 잔에 미음을 채워줄 것입니다… 무슨, 왜 주전자에는 생선 국물이 들어있지?"
  },
  Stage_70420_Name = {
    Text = "고양이 파티·중 하나"
  },
  Stage_70421_Desc = {
    Text = "검은 고양이가 등을 둥글게 말며 자신의 네 다리를 움직이기 시작했다. \n보기에 이 검은 고양이는 방금 자신의 몸을 길들인 것 같다. \n기묘한 모습의 검은 고양이가 손을 내밀며 당신에게 함께 춤을 추자고 초대한다."
  },
  Stage_70421_Name = {
    Text = "고양이의 춤·중 하나"
  },
