  Stage_70433_Name = {
    Text = "고양이의 춤·둘째"
  },
  Stage_70434_Desc = {
    Text = "검은 고양이가 마지막 축복을 전합니다. 당신은 이 희극이 곧 끝날 것임을 느낄 수 있습니다. \n냥냥이는 무엇을 잘못했을까요? 그것은 단지 명절에 당신에게 조금의 활기를 주고 싶었을 뿐입니다."
  },
  Stage_70434_Name = {
    Text = "고양이의 축복·하나"
  },
  Stage_70435_Desc = {
    Text = "이 검은 고양이는 마법 같은 힘을 가지고 있는 것 같다.\n고양이가 손가락을 튕기자 하늘에 불꽃이 피어났다.\n시끌벅적한 소음 속에서 당신은 머리 위에서 머리카락이 타는 냄새를 맡았다."
  },
  Stage_70435_Name = {
    Text = "고양이의 마법·둘째"
  },
  Stage_70436_Desc = {
    Text = "이 검은 고양이는 마법 같은 힘을 가지고 있는 것 같다.\n고양이가 손가락을 튕기자 하늘에 불꽃이 피어났다.\n시끌벅적한 소음 속에서 당신은 머리 위에서 머리카락이 타는 냄새를 맡았다."
  },
  Stage_70436_Name = {
    Text = "고양이의 마법·세 번째"
  },
  Stage_70437_Desc = {
    Text = "이 검은 고양이는 마법 같은 힘을 가지고 있는 것 같다.\n고양이가 손가락을 튕기자 하늘에 불꽃이 피어났다.\n시끌벅적한 소음 속에서 당신은 머리 위에서 머리카락이 타는 냄새를 맡았다."
  },
  Stage_70437_Name = {
    Text = "고양이의 마법·하나"
  },
  Stage_70924_Desc = {
    Text = "사랑해, 우리 함께 종말을 보러 가자. \n절망 속에서 점점 쇠퇴하기보다는 운명이 강림하기 전에 직접 종말의 위업을 이루자."
  },
  Stage_70924_Name = {
    Text = "선택되지 않은 길"
  },
  Stage_70925_Desc = {
    Text = "숫자는 결코 이름이 아니고, 단지 기호일 뿐입니다. \n평범한 생명들은 자신이 상상한 독특함을 포기하고 싶지 않아서 숫자로 자신을 대신 부르는 것을 거부합니다. \n그녀는 전혀 신경 쓰지 않습니다."
  },
  Stage_70926_Desc = {
    Text = "가능성은 좋은 결과와 동일하지 않지만, 신기루 역시 전진하는 자의 유인물이다."
  },
  Stage_70926_Name = {
    Text = "가능성의 답"
  },
  Stage_70927_Desc = {
    Text = "구르르, 구르르, 구르르. 기관이 절박한 갈망의 비명을 지른다. \n아니, 뱃속의 허기 소리가 아니라, 그 공허는 대뇌로부터 시작된다."
  },
  Stage_70927_Name = {
    Text = "인간 식량"
  },
  Stage_70928_Desc = {
    Text = "비. 계속되는 비."
  },
  Stage_70928_Name = {
    Text = "비 속에서"
  },
  Stage_70929_Desc = {
    Text = "한 계단 한 계단 한 계단, 그분의 촉수가 깊은 꿈의 바닥을 향해 나아간다."
  },
  Stage_70929_Name = {Text = "깊은 꿈"},
  Stage_70930_Desc = {
    Text = "눈, 나는 꿈에서 마주치는 것이 두려워\n죽음의 환상의 땅에서"
  },
  Stage_70930_Name = {
    Text = "마음이 허한 사람"
  },
  Stage_70931_Desc = {
    Text = "인간은 유일한 진리를 정의합니다. \n당신이 보는 것이 세상의 진실타래입니다."
  },
  Stage_70931_Name = {
    Text = "진실타래"
  },
  Stage_70932_Desc = {
    Text = "보세요, 그 둥근 윤광이 나는 사과가 얼마나 유혹적인지. \n조심스럽게 한 입 베어물면 모든 고민을 날려버리세요."
  },
  Stage_70932_Name = {Text = "독사과"},
  Stage_70933_Desc = {
    Text = "전부 회상과 같아요."
  },
  Stage_70933_Name = {
    Text = "친근하고 용감한"
  },
  Stage_70934_Desc = {
    Text = "지나간 것은 다시 돌아오지 않는다. \n하지만, 다른 세계에서라면."
  },
  Stage_70934_Name = {
    Text = "우리가 잃어버린 것"
  },
  Stage_70935_Desc = {
    Text = "리버스, 리버스, 음표가 예상 밖의 리듬으로 움직입니다."
  },
  Stage_70935_Name = {
    Text = "미로 속 음표"
  },
  Stage_70936_Desc = {
    Text = "한 트랩에서 벗어나 더 거대한 감옥으로 빠져들게 된다."
  },
  Stage_70936_Name = {Text = "탈출"},
  Stage_70937_Desc = {
    Text = "뇌인두는 기계 의체를 꿈꾸는가?"
  },
  Stage_70937_Name = {
    Text = "통 속의 꿈"
  },
  Stage_71748_Desc = {
    Text = "「쉿…… 네가 뭐 보는지 알아?」\n오레타가 수호자에게 놀라 울음을 터뜨린 후, 수호자의 방의 네 번째 벽이 거의 무너질 뻔했다. 오레타가 너무 심하게 울어서 모두를 불안하게 만들었기 때문이다."
  },
  Stage_71748_Name = {
    Text = "드라마의 네 번째 벽·칠"
  },
  Stage_71748_StageInitStateText = {Text = "원초"},
  Stage_71749_Desc = {
    Text = "관객의 뇌를 내용으로 폭격하지 말고, 그들에게 생각할 공간을 주는 것이 좋다. 가장 좋은 방법은 완전히 정지하는 것이다. —— 수호자는 돌이 수업 중에 이 기술을 숙달했으면 좋겠다며 나지막이 말하기를 했고, 모든 사람의 동의를 받았다."
  },
  Stage_71749_Name = {
    Text = "장면 정지 순간·칠"
  },
  Stage_71749_StageInitStateText = {Text = "원초"},
  Stage_71750_Desc = {
    Text = "스토리의 끝에서 캐릭터의 발전이나 변화를 나타내야 합니다. 하지만 실타래제 생활에서는 그 광선의 곡선이 종종 원을 이루곤 합니다."
  },
  Stage_71750_Name = {
    Text = "호광이론·칠"
  },
  Stage_71750_StageInitStateText = {Text = "원초"},
  Stage_71751_Desc = {
    Text = "예정된 장면, 서로 잘 아는 배우들. 나머지는 영감과 상호작용에 맡겨둡니다."
  },
  Stage_71751_Name = {
    Text = "가면 코미디·칠"
  },
  Stage_71751_StageInitStateText = {Text = "원초"},
  Stage_71752_Desc = {
    Text = "이것은 라몬나조차 들어보지 못한 단어로, 몇몇 연로한 깨어남체의 도움을 받아 모두가 마침내 이해했다: 때때로, 대성통곡하는 것이 나쁜 감정을 처리하는 유일한 방법이라는 것을."
  },
  Stage_71752_Name = {
    Text = "카타시스·칠"
  },
  Stage_71752_StageInitStateText = {Text = "원초"},
  Stage_71753_Desc = {
    Text = "「관객이 극에 완전히 몰입하지 못하게 하고, 무대에서 일어나는 일을 분석하고 비판하게 해야 한다.」 \n 이 이론에 대해 오레타는 이렇게 평가한다: 오레타는 누구에게도 욕먹고 싶지 않아! 오레타는 모두와 좋은 친구가 되고 싶어!"
  },
  Stage_71753_Name = {
    Text = "이방화 효과·칠"
  },
  Stage_71753_StageInitStateText = {Text = "원초"},
  Stage_71754_Desc = {
    Text = "상황이 급변하고, 갑작스러운 사건, 이야기가 갑자기 변했다——수호자가 느끼기에, 이는 때때로 자신을 설명하는 것 같았다."
  },
  Stage_71754_Name = {
    Text = "시나리오 회전·칠"
  },
  Stage_71754_StageInitStateText = {Text = "원초"},
  Stage_71755_Desc = {
    Text = "카시아가 찾은 이론서에는 이렇게 쓰여 있었다: 이야기가 일어나는 시간은 하루를 넘지 않으며, 무대도 한 곳을 넘지 않아야 한다……\n수호자는 여기까지 듣고 포기했다. 결국, 하루의 시간은 때로 수호자가 「융식과 재앙 처리」의 과제 논문을 완성하기에도 부족할 때가 있기 때문이다."
  },
  Stage_71755_Name = {
    Text = "삼일률·칠"
  },
  Stage_71755_StageInitStateText = {Text = "원초"},
  Stage_71756_Desc = {
    Text = "카시아에서 찾은 이론서에는 다음과 같이 적혀 있다: 피라미드 모델은 종종 위기 해결에 초점을 맞추고 있다. \n하지만 안타깝게도 모든 위기가 현실타래에서 해결되는 것은 아니다. 그것들은 평화의 가면 뒤에 숨겨지고, 은밀히 번져나가다가 결국 새로운 「피라미드」로 폭발한다."
  },
  Stage_71756_Name = {
    Text = "극작 피라미드·칠"
  },
  Stage_71756_StageInitStateText = {Text = "원초"},
  Stage_71810_Desc = {
    Text = "그녀는 많은 신분을 가지고 있다: 명부인, 상인, 중개인, 수집가……\n유일하게 자신만은 없다 — 아쉽지만, 장미 부인은 이로 인해 실타래망하지 않는다.\n그녀에게 있어 원시적이고 다듬지 않은 것들은 중요하지 않다. 복잡하고 혼탁한 것이야말로 최고의 미학이다."
  },
  Stage_71810_Name = {
    Text = "얼굴·칠"
  },
  Stage_71810_StageInitStateText = {Text = "번식"},
  Stage_71811_Desc = {
    Text = "그녀의 장다리 아저씨는 다른 사람들과 달랐다: 그는 안개로 만들어졌다. \n여자아이가 이미 인간에 대한 신뢰를 잃어버렸기에, 안개나 금, 기호로 만들어진 사람들은 별 차이가 없었다. \n물론, 그녀는 자신의 잘못된 판단에 대해 대가를 치르게 될 것이다—하지만 그것은 오랜 시간 후의 이야기였다."
  },
  Stage_71811_Name = {
    Text = "장다리 아저씨·칠"
  },
  Stage_71811_StageInitStateText = {Text = "번식"},
  Stage_71812_Desc = {
    Text = "출발 전, 전기 작가는 이 장미가 만발한 아름다운 저택을 돌아보았다. 그것은 주인의 빛의 만분의 일에도 미치지 못했다. \n소렐 부인에 대한 전설은 계속되고 있으며, 바로 지금 이 순간에도 일어나고 있다. 우리는 모두 그 증인이 될 것이다."
  },
  Stage_71812_Name = {
    Text = "종곡·칠"
  },
  Stage_71812_StageInitStateText = {Text = "번식"},
  Stage_71813_Desc = {
    Text = "꽃꽂이, 자수, 차 예절…… 그녀의 삶은 무의미한 기호들의 연속으로 이루어져 있다. \n「좋은 아침, 소렐 양」 「당신 정말 대단해요, 소렐 양」…… \n억지로 밝게 꾸민 말은 두꺼운 어항처럼 그녀를 영원히 가두고 있다."
  },
  Stage_71813_Name = {
    Text = "부아래서 헤엄치는 물고기·칠"
  },
  Stage_71813_StageInitStateText = {Text = "번식"},
  Stage_71814_Desc = {
    Text = "미모는 무형의 실타래로, 가볍게 사람들의 마음을 얽어맨다. 그녀는 마치 가장 무심한 천재처럼 실타래을 망설임 없이 다룬다. \n하지만 곧 그녀는 이 게임에 싫증이 났다. 왜냐하면 그들의 추한 얼굴 너머로 그녀는 자신의 본 모습을 엿보았기 때문이다."
  },
  Stage_71814_Name = {
    Text = "인형 게임·칠"
  },
  Stage_71814_StageInitStateText = {Text = "번식"},
  Stage_71815_Desc = {
    Text = "그녀는 생일에 선물을 받았습니다: 정성스럽게 만든 하얀 레이스 드레스. \n그런 후 그녀는 자신이 이 선물을 입고서 부모님께서 다른 사람에게 주실타래 선물이 될 것이라고 들었습니다."
  },
  Stage_71815_Name = {
    Text = "선물·칠"
  },
  Stage_71815_StageInitStateText = {Text = "번식"},
  Stage_71816_Desc = {
    Text = "그녀는 자석처럼 주변 사람들의 시선을 단단히 끌어당겼다. \n부러움, 놀람, 시기, 욕심…… 그 어떤 것도 평온하지 않았다. 그녀의 운명 또한 그러했다."
  },
  Stage_71816_Name = {
    Text = "시선·칠"
  },
  Stage_71816_StageInitStateText = {Text = "번식"},
  Stage_71817_Desc = {
    Text = "그날 밤, 그녀는 흑무를 꾸었고, 그것이 생기가 있어 떨리고 있는 것을 보았다. \n호랑이와 말의, 이루 형용할 수 없는 잡종이 아니요, 두 동물의 성질을 겸비하였다. \n동시에 그것은 검은 고양이, 장미 한 송이, 폭풍우였다."
  },
  Stage_71817_Name = {
    Text = "장미의 각·칠"
  },
  Stage_71817_StageInitStateText = {Text = "번식"},
  Stage_71818_Desc = {
    Text = "그녀는 대본의 지시에 따라 한 편의 연극을 끝내고, 끝없는 혼란을 일으킬 것입니다. \n그리고 그녀는 폭풍의 눈에서 우아하게 날아오르는 무용가입니다. \n그녀는 항상 가장 성실타래한 배우였습니다."
  },
  Stage_71818_Name = {
    Text = "미완의 대본·칠"
  },
  Stage_71818_StageInitStateText = {Text = "번식"},
  Stage_71852_Desc = {
    Text = "그는 높은 청석 왕좌에 위엄 있게 앉아 영원한 숭고함과 고독을 혼자 즐기고 있다."
  },
  Stage_71852_Name = {Text = "왕좌"},
  Stage_71853_Desc = {
    Text = "나는 나에게 직접 무한한 힘과 영광을 씌워줄 것입니다."
  },
  Stage_71853_Name = {Text = "가관"},
  Stage_71854_Desc = {
    Text = "신성의 기도를 통해 기적을 바라는 것 외에, 보잘것없는 인간에게는 다른 선택이 없다."
  },
  Stage_71854_Name = {Text = "재난"},
  Stage_71855_Desc = {
    Text = "그 왕관의 무게는 이미 오래 전에 그 아이들의 어깨에 짓눌렸다."
  },
  Stage_71855_Name = {
    Text = "어린 시절"
  },
  Stage_71923_Desc = {
    Text = "심연으로부터 어둠이 솟아오르고, 침입자는 가슴을 조이는 공포 속에서 투쟁한다. 어둠에 삼켜지기 전까지."
  },
  Stage_71923_Name = {
    Text = "융재금지구역 제2파·Ⅴ급 경보"
  },
  Stage_71924_Desc = {
    Text = "심연으로부터 어둠이 솟아오르고, 침입자는 가슴을 조이는 공포 속에서 투쟁한다. 어둠에 삼켜지기 전까지."
