  Stage_71930_Desc = {
    Text = "심연으로부터 어둠이 솟아오르고, 침입자는 가슴을 조이는 공포 속에서 투쟁한다. 어둠에 삼켜지기 전까지."
  },
  Stage_71930_Name = {
    Text = "융재금지구역 제1파·Ⅴ급 경보"
  },
  Stage_71931_Desc = {
    Text = "심연으로부터 어둠이 솟아오르고, 침입자는 가슴을 조이는 공포 속에서 투쟁한다. 어둠에 삼켜지기 전까지."
  },
  Stage_71931_Name = {
    Text = "융재금지구역 제3파·Ⅴ급 경보"
  },
  Stage_71932_Desc = {
    Text = "심연으로부터 어둠이 솟아오르고, 침입자는 가슴을 조이는 공포 속에서 투쟁한다. 어둠에 삼켜지기 전까지."
  },
  Stage_71932_Name = {
    Text = "융재금지구역 제2파·Ⅴ급 경보"
  },
  Stage_72063_Desc = {
    Text = "눈, 나는 꿈에서 마주치는 것이 두려워\n죽음의 환상의 땅에서"
  },
  Stage_72063_Name = {
    Text = "마음이 허한 사람"
  },
  Stage_72064_Desc = {
    Text = "인간은 유일한 진리를 정의합니다. \n당신이 보는 것이 세상의 진실타래입니다."
  },
  Stage_72064_Name = {
    Text = "진실타래"
  },
  Stage_72065_Desc = {
    Text = "보세요, 그 둥근 윤광이 나는 사과가 얼마나 유혹적인지. \n조심스럽게 한 입 베어물면 모든 고민을 날려버리세요."
  },
  Stage_72065_Name = {Text = "독사과"},
  Stage_72066_Desc = {
    Text = "전부 회상과 같아요."
  },
  Stage_72066_Name = {
    Text = "친근하고 용감한"
  },
  Stage_72067_Desc = {
    Text = "지나간 것은 다시 돌아오지 않는다. \n하지만, 다른 세계에서라면."
  },
  Stage_72067_Name = {
    Text = "우리가 잃어버린 것"
  },
  Stage_72068_Desc = {
    Text = "리버스, 리버스, 음표가 예상 밖의 리듬으로 움직입니다."
  },
  Stage_72068_Name = {
    Text = "미로 속 음표"
  },
  Stage_72069_Desc = {
    Text = "한 트랩에서 벗어나 더 거대한 감옥으로 빠져들게 된다."
  },
  Stage_72069_Name = {Text = "탈출"},
  Stage_72070_Desc = {
    Text = "사랑해, 우리 함께 종말을 보러 가자. \n절망 속에서 점점 쇠퇴하기보다는 운명이 강림하기 전에 직접 종말의 위업을 이루자."
  },
  Stage_72070_Name = {
    Text = "선택되지 않은 길"
  },
  Stage_72071_Desc = {
    Text = "숫자는 결코 이름이 아니고, 단지 기호일 뿐입니다. \n평범한 생명들은 자신이 상상한 독특함을 포기하고 싶지 않아서 숫자로 자신을 대신 부르는 것을 거부합니다. \n그녀는 전혀 신경 쓰지 않습니다."
  },
  Stage_72072_Desc = {
    Text = "구르르, 구르르, 구르르. 기관이 절박한 갈망의 비명을 지른다. \n아니, 뱃속의 허기 소리가 아니라, 그 공허는 대뇌로부터 시작된다."
  },
  Stage_72072_Name = {
    Text = "인간 식량"
  },
  Stage_74229_Desc = {
    Text = "당신은 그 휘날리는 치마자락과 마주치고, 그 도는 춤의 치마가 얼마나 백조의 날개처럼, 또 얼마나 타오르는 불꽃처럼 보이는지요."
  },
  Stage_74229_Name = {
    Text = "뜻밖의 불꽃"
  },
  Stage_74230_Desc = {
    Text = "여기가 예술의 전당이 아니었나? 그렇지 않다면 어떻게 그렇게 눈부신 우아한 춤이 많을 수 있을까.\n하지만 여기 정말 예술의 전당일까? 아니면 왜 그렇게 많은 차갑고 기름진 시선이 가득할까?"
  },
  Stage_74230_Name = {
    Text = "타는 단단한 얼음"
  },
  Stage_74231_Desc = {
    Text = "꿈속의 백조가 높이 날아오르다가 사냥꾼의 망에 부딪혀 떨어졌습니다."
  },
  Stage_74231_Name = {
    Text = "한여름 밤의 꿈"
  },
  Stage_74232_Desc = {
    Text = "청색 무용수가 무대에서 춤춘다.\n청색의 불꽃이 화염 속에서 타오른다.\n감히 죽음을 향해 나아가는 백조를 위해, 마지막 애가를 바친다."
  },
  Stage_74232_Name = {
    Text = "천운의 애가"
  },
  Stage_74242_Desc = {
    Text = "청색 무용수가 무대에서 춤춘다.\n청색의 불꽃이 화염 속에서 타오른다.\n감히 죽음을 향해 나아가는 백조를 위해, 마지막 애가를 바친다."
  },
  Stage_74242_Name = {
    Text = "천운의 애가"
  },
  Stage_74243_Desc = {
    Text = "청색 무용수가 무대에서 춤춘다.\n청색의 불꽃이 화염 속에서 타오른다.\n감히 죽음을 향해 나아가는 백조를 위해, 마지막 애가를 바친다."
  },
  Stage_74243_Name = {
    Text = "천운의 애가"
  },
  Stage_74328_Desc = {
    Text = "조건이 준비되었고, 열혈이 끓고 있습니다. 이제, 결투를 시작합니다."
  },
  Stage_74328_Name = {
    Text = "의지를 관철하는 결투"
  },
  Stage_74329_Desc = {
    Text = "절망적인 상황에 있어도 희망을 포기하지 마세요. 왜냐하면 모든 순간이 역전의 시작이 될 수 있기 때문입니다."
  },
  Stage_74329_Name = {
    Text = "역전의 순간"
  },
  Stage_74330_Desc = {
    Text = "한 번의 사고로 인해 페이즈 대결 공간에 특별한 손님이 찾아왔다. 페이즈 대결 공간을 되찾기 위해 당신은 최강의 카드 마스터가 되기 위한 여정을 시작했다."
  },
  Stage_74330_Name = {
    Text = "이계의 손님"
  },
  Stage_74975_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_74975_Name = {
    Text = "환몽 심잠 Ⅵ"
  },
  Stage_74976_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_74976_Name = {
    Text = "환몽 심잠·광기"
  },
  Stage_74977_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_74977_Name = {
    Text = "환몽 심잠·광기"
