  },
  Stage_75261_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_75261_Name = {
    Text = "환몽 심잠·광기"
  },
  Stage_75262_Desc = {
    Text = "무너진 우상은 자신의 백성을 응시한다. \n 그들은 생존하고, 번식하고, 서로 싸우다가, 결국 자신을 완전히 잊는다. \n 무너진 우상은 그 백성을 그리워한다."
  },
  Stage_75262_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
  Stage_75743_Desc = {
    Text = "그는 이미 자신의 이름을 잊어버렸고, 그녀와 처음 만난 날의 기억마저 희미해지기 시작했다. \n오직 그녀의 손, 그녀가 부드럽게 잡아준 그 손만이 그의 야만적이고 외로운 영혼을 따뜻하게 해주었다. \n그래서 그는 그녀의 손에서 아름다운 두개골을 받아, 자발적으로 영원한 가면과 족쇄를 썼다."
  },
