    Text = "비오는 날은 항상 숨을 쉬기 어렵게 만든다. \n미끄러운 수증기가 피부에 달라붙고, 답답한 공기가 폐를 가득 채운다. \n골골거리며 무언가가 드롭되어 굴러간다. \n조심해요, 발이 걸리지 않도록 하세요."
