    Text = "그 회색 바다는 끝이 없다. \n모든 안식처 없는 영혼들이 이곳에서 모여들어, 파도가 거세게 밀려오고 부유하고 침몰한다. \n그들은 서로 안기고 웃고 울며, 당신을 바라보고 있으며, 다음 동료를 기다리고 있다."
  },
  Stage_75777_Name = {
    Text = "회색 바다로 돌아가다·지네"
  },
  Stage_7635_Desc = {
    Text = "그들은 종잡을 수 없는 마법사처럼 시공간의 틈새를 떠돌아다닌다. 증오도, 두려움도, 연민도 없다."
  },
  Stage_7635_Name = {
    Text = "차원 잔상 Ⅱ"
  },
  Stage_7636_Desc = {
    Text = "그녀는 몸으로 성스러운 유골을 품고, 교리로 신도들을 이끌며, 독니로 신앙을 퍼뜨렸다.\n그녀의 기도는 멈추지 않고, 그녀의 부름은 그치지 않는다."
  },
  Stage_7636_Name = {
    Text = "신앙의 손아귀 Ⅲ"
  },
  Stage_7637_Desc = {
    Text = "뭇별이 생겨나기 전부터, 그것들은 이미 이곳에 존재했다. 그들은 허무이자, 모든 것이기도 하다."
  },
  Stage_7637_Name = {
    Text = "혼돈 잔상 Ⅴ"
  },
  Stage_7638_Desc = {
    Text = "그들은 바다의 비밀을 말없이 지키며, 영혼은 우주만큼이나 깊다."
  },
  Stage_7638_Name = {
    Text = "해연 잔상 Ⅴ"
  },
  Stage_76399_Desc = {
    Text = "심연으로부터 어둠이 솟아오르고, 침입자는 가슴을 조이는 공포 속에서 투쟁한다. 어둠에 삼켜지기 전까지."
  },
  Stage_76399_Name = {
    Text = "융재금지구역 제4파·Ⅴ급 경보"
  },
  Stage_7639_Desc = {
    Text = "그것들은 어둠 속에서 뒤틀리고 융합한 후, 엄숙히 조각상 안에 보관되었다.\n이는 오래 전부터 계획되었던 재회였다."
  },
  Stage_7639_Name = {
    Text = "초월의 여정·간격Ⅰ"
  },
  Stage_76400_Desc = {
    Text = "심연으로부터 어둠이 솟아오르고, 침입자는 가슴을 조이는 공포 속에서 투쟁한다. 어둠에 삼켜지기 전까지."
  },
  Stage_76400_Name = {
    Text = "융재금지구역 제5파·Ⅴ급 경보"
  },
  Stage_76401_Desc = {
