  },
  Stage_7644_Name = {
    Text = "환몽 심잠 Ⅳ"
  },
  Stage_7645_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_7645_Name = {
    Text = "환몽 심잠 Ⅲ"
  },
  Stage_7646_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_7646_Name = {
    Text = "환몽 심잠 Ⅱ"
  },
  Stage_7647_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_7647_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
  Stage_7648_Desc = {
    Text = "사냥개는 규칙을 깨뜨린 자들을 쉴새없이 추적한다. \n'규칙'이란 무엇이며, 그것을 '깨뜨린다'는 것은 또 무엇인가? \n사냥개는 그런 것들을 생각하지 않는다— 생각은 덮치는 속도를 늦출 뿐이다."
  },
  Stage_7648_Name = {
    Text = "너머의 그림자 Ⅲ"
  },
  Stage_7649_Desc = {
    Text = "론디니움은 찬란한 산업 문명과 도시를 뒤덮은 회색 안개로 유명하다. \n안개는 어디에나 있으며, 지나가는 사람들에게는 그저 우연적이고 무의미한 불편함 정도에 불과하다."
  },
  Stage_7649_Name = {
    Text = "안개의 도시 Ⅱ"
  },
  Stage_7650_Desc = {
    Text = "정체불명의 조각상이 어둠 속을 떠돌아다니며 떨고 있다.\n그들은 오래된 리듬에 맞춰, 먼 곳에서 들려오는 피리 소리를 따라 춤을 추었다."
  },
  Stage_7650_Name = {
    Text = "혈육의 늪지·간격Ⅶ"
  },
  Stage_7651_Desc = {
    Text = "투박하고, 미처 소화되지 못한 물질 무더기. 사람들은 그것을 배설물, 혹은 혼돈이라고 부른다.\n세계는 배설물에서 탄생했다."
  },
  Stage_7651_Name = {
    Text = "혼돈 군집 Ⅴ"
  },
  Stage_7652_Desc = {
    Text = "꿈틀거리고, 흘러내린다... 족쇄의 틈새로 원생질 종양이 빠져나가고 있다.\n이것은 그녀가 '자유'를 위해 치른 대가이다."
  },
  Stage_7652_Name = {
    Text = "칠흑의 사슬 Ⅲ"
  },
  Stage_7653_Desc = {
    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_7653_Name = {
    Text = "초월의 여정·회전 간격Ⅰ"
  },
  Stage_7654_Desc = {
    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_7654_Name = {
    Text = "초월의 여정·회전 간격Ⅰ"
  },
  Stage_7655_Desc = {
    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_7655_Name = {
    Text = "초월의 여정·회전 간격Ⅰ"
  },
  Stage_7656_Desc = {
    Text = "인형은 침대 가장자리에 얌전히 기대어 앉아 있고, 초점 없는 단추 눈은 허공을 바라본다.\n작은 몸으로 주인의 모든 눈물을 받아냈지만, 위로의 말은 건넬 수 없었다."
  },
  Stage_7656_Name = {
    Text = "인형의 눈물 Ⅴ"
  },
  Stage_7657_Desc = {
    Text = "그들은 본래 슬픔, 왜곡, 그리고 무지로 이루어진 무의식적 집합체였지만, \n행복한 아이와 어른, 그리고 애완동물의 모습으로 꾸며졌다. \n단 한 번도 행복을 맛본 적이 없었기에, 그들은 최악의 배우였다."
  },
  Stage_7657_Name = {
    Text = "밀랍상의 비밀 Ⅴ"
  },
  Stage_7658_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_7658_Name = {
    Text = "혼돈의 영역·간격Ⅳ"
  },
  Stage_7659_Desc = {
    Text = "폭풍우는 아직 준비 중이며, 모든 것이 종료되지 않았습니다."
  },
  Stage_7659_Name = {
    Text = "다시 현실타래로"
  },
  Stage_7660_Desc = {
    Text = "화려한 무대 장치도 없고, 감동적인 여주인공도 없다. \n—— 이는 세 명의 남자들이 연기하는 지루한 연극이다."
  },
  Stage_7660_Name = {
    Text = "사제, 마법사와 노예"
  },
  Stage_7661_Desc = {
    Text = "바람과 황사 속에서 전사가 결연하게 태양을 향해 달려갔다."
  },
  Stage_7661_Name = {
    Text = "태양 원정대"
  },
  Stage_7662_Desc = {
    Text = "친구들, 싸움과 다툼을 멈추세요. \n 제사의 불꽃이 이미 타오르고 있습니다. 죽음에 이르기 전 마지막 평온을 만끽하십시오……"
  },
  Stage_7662_Name = {
    Text = "붉은 제례"
  },
  Stage_7663_Desc = {
    Text = "엄격한 의미에서 보면, 이는 비극이 아니다. \n 전사의 사전에는 「비극」이라는단어가 없다."
  },
  Stage_7663_Name = {
    Text = "비극의 막이 내리다"
  },
  Stage_7664_Desc = {
    Text = "육지를 향해, 생존의 기회를 향해,"
  },
  Stage_7664_Name = {
    Text = "비극의 출항"
  },
  Stage_7665_Desc = {
    Text = "우주 깊은 곳에 숨어 있는 구부러진 경계.\n당신을 한 어둠에서 또 다른 어둠으로 이끌 수 있다."
  },
  Stage_7665_Name = {
    Text = "블랙홀의 목구멍 Ⅲ"
  },
  Stage_7666_Desc = {
    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_7666_Name = {
    Text = "심해의 유산·간격Ⅲ"
  },
