  Stage_77103_Name = {
    Text = "융재금지구역 제5파·Ⅲ급 경보"
  },
  Stage_7710_Desc = {
    Text = "일기는 기억의 파편이다. \n조사 중에는 항상 일기가 발견된다."
  },
  Stage_7710_Name = {
    Text = "기억의 파편"
  },
  Stage_7711_Desc = {
    Text = "이곳은 그녀를 위해 만들어진 세계로, 위대한 사랑의 증거이자 공포스러운 감옥이다."
  },
  Stage_7711_Name = {
    Text = "정신병원"
  },
  Stage_7712_Desc = {
    Text = "귀족들이 권력을 잃을 때, 부자들이 전재산을 잃을 때 그들은 한없이 무력해진다. 지금의 당신처럼."
  },
  Stage_7712_Name = {
    Text = "광기의 병동"
  },
  Stage_7713_Desc = {
    Text = "세상의 싸움은 칼날이 맞부딪히는 전장에만 있는 것이 아니다. 때로는 미치광이의 입에서 시작될 수도 있다."
  },
  Stage_7713_Name = {
    Text = "광인의 입"
  },
  Stage_7714_Desc = {
    Text = "안개 속에 감싸진 궤적, 수많은 발걸음이 그 위를 맴돌고, 각각의 발걸음은 운명에 대한 물음이다."
  },
  Stage_7714_Name = {
    Text = "미궁 같은 앞길"
  },
  Stage_7715_Desc = {
    Text = "조용히 타오르는 불꽃은 여행자에게 허망한 약속을 한다."
  },
  Stage_7715_Name = {
    Text = "유혹의 불꽃"
  },
  Stage_7716_Desc = {
    Text = "혈육으로 빚어진 현실타래을 바쳐라. 그것들은 만족을 모르는 심연이다."
  },
  Stage_7716_Name = {
    Text = "유기 잔상 Ⅴ"
  },
  Stage_7717_Desc = {
    Text = "폭풍우는 아직 준비 중이며, 모든 것이 종료되지 않았습니다."
  },
  Stage_7717_Name = {
    Text = "다시 현실타래로"
  },
  Stage_7718_Desc = {
    Text = "육지를 향해, 생존의 기회를 향해,"
  },
  Stage_7718_Name = {
    Text = "비극의 출항"
  },
  Stage_7719_Desc = {
    Text = "그것은 기대받지 못한 생명이었을 뿐, 더러운 기생충에 불과했다."
  },
  Stage_7719_Name = {Text = "기생충"},
  Stage_7720_Desc = {
    Text = "무한한 밤의 어둠 속에서 유인하는 빛을 쫓아가는 것처럼, 화염의 나비처럼 모든 것을 버리고 운명의 불꽃을 향해 날아오른다."
  },
  Stage_7720_Name = {Text = "불나방"},
  Stage_7721_Desc = {
    Text = "야색은 암류에 침식당하고, 별빛은 잃어버렸다. 전환과 풍우의 위기의 달이, 미지의 미래를 조용히 비추고 있다."
  },
  Stage_7721_Name = {
    Text = "위기의 달"
  },
  Stage_7722_Desc = {
    Text = "운명의 광풍 속에서 떨고, 발버둥치지만 그것은 정말로 떠돌지 않을 것이다."
  },
  Stage_7722_Name = {
    Text = "흔들리는 운명"
  },
  Stage_7723_Desc = {
    Text = "지난 세월에 흔들리던 우정은 새로운 희망을 결어졌습니다."
  },
  Stage_7723_Name = {
    Text = "옛 벗과 새 친구"
  },
  Stage_7724_Desc = {
    Text = "그분의 나라는 우주의 껍데기이며, 그분의 욕망은 끝이 없다."
  },
  Stage_7724_Name = {
    Text = "벌레의 소굴 Ⅲ"
  },
  Stage_7725_Desc = {
    Text = "혈육으로 빚어진 현실타래을 바쳐라. 그것들은 만족을 모르는 심연이다."
  },
  Stage_7725_Name = {
    Text = "유기 잔상 Ⅱ"
  },
  Stage_7726_Desc = {
    Text = "그들은 본래 슬픔, 왜곡, 그리고 무지로 이루어진 무의식적 집합체였지만, \n행복한 아이와 어른, 그리고 애완동물의 모습으로 꾸며졌다. \n단 한 번도 행복을 맛본 적이 없었기에, 그들은 최악의 배우였다."
  },
  Stage_7726_Name = {
    Text = "밀랍상의 비밀 Ⅰ"
  },
  Stage_7727_Desc = {
    Text = "인형은 침대 가장자리에 얌전히 기대어 앉아 있고, 초점 없는 단추 눈은 허공을 바라본다.\n작은 몸으로 주인의 모든 눈물을 받아냈지만, 위로의 말은 건넬 수 없었다."
  },
  Stage_7727_Name = {
    Text = "인형의 눈물 Ⅰ"
  },
  Stage_7728_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_7728_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
