  },
  Stage_7741_Name = {
    Text = "환몽 심잠 Ⅴ"
  },
  Stage_7742_Desc = {
    Text = "무너진 우상은 자신의 백성을 응시한다. \n 그들은 생존하고, 번식하고, 서로 싸우다가, 결국 자신을 완전히 잊는다. \n 무너진 우상은 그 백성을 그리워한다."
  },
  Stage_7742_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
  Stage_7743_Desc = {
    Text = "뭇별이 생겨나기 전부터, 그것들은 이미 이곳에 존재했다. 그들은 허무이자, 모든 것이기도 하다."
  },
  Stage_7743_Name = {
    Text = "혼돈 잔상 Ⅰ"
  },
  Stage_7744_Desc = {
    Text = "그것들은 어둠 속에서 뒤틀리고 융합한 후, 엄숙히 조각상 안에 보관되었다.\n이는 오래 전부터 계획되었던 재회였다."
  },
  Stage_7744_Name = {
    Text = "심해의 유산·간격Ⅰ"
  },
  Stage_7745_Desc = {
    Text = "그녀는 몸으로 성스러운 유골을 품고, 교리로 신도들을 이끌며, 독니로 신앙을 퍼뜨렸다.\n그녀의 기도는 멈추지 않고, 그녀의 부름은 그치지 않는다."
  },
  Stage_7745_Name = {
    Text = "신앙의 손아귀 Ⅰ"
  },
  Stage_7746_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_7746_Name = {
    Text = "심해의 유산·간격Ⅳ"
  },
  Stage_7747_Desc = {
    Text = "라이 마을은 론디니움의 북동쪽에 위치해 있으며, 끝없는 산맥 속에 숨겨져 있다. \n침묵하는 마을 사람들, 어디에나 있는 시선... 조심하라, 이곳의 모든 점이 평범하지 않다."
  },
  Stage_7747_Name = {
    Text = "혼란의 마을 Ⅰ"
  },
  Stage_7748_Desc = {
    Text = "오, 하수도! 너는 도시의 양심이자 도시의 피난처구나."
  },
  Stage_7748_Name = {
    Text = "지하수로"
  },
  Stage_7749_Desc = {
    Text = "네, 네. 눈은 마음의 감옥이고, 영혼은 육체를 묶는 족쇄입니다."
  },
  Stage_7749_Name = {
    Text = "해부적 우울"
  },
  Stage_7750_Desc = {
    Text = "허무는 우리의 근원이자 종착지다."
  },
  Stage_7750_Name = {
    Text = "불멸의 속삭임"
  },
  Stage_7751_Desc = {
    Text = "그래, 아가야. 마음껏 울거라. 네 모든 고통을 담아서 세상에 다시 없을 걸작처럼 꾸미거라."
  },
  Stage_7751_Name = {
    Text = "소녀와 눈물"
  },
  Stage_7752_Desc = {
    Text = "사냥개는 규칙을 깨뜨린 자들을 쉴새없이 추적한다. \n'규칙'이란 무엇이며, 그것을 '깨뜨린다'는 것은 또 무엇인가? \n사냥개는 그런 것들을 생각하지 않는다— 생각은 덮치는 속도를 늦출 뿐이다."
  },
  Stage_7752_Name = {
    Text = "너머의 그림자 Ⅱ"
  },
  Stage_7753_Desc = {
    Text = "진실타래, 이 잔인한 진실타래."
  },
  Stage_7753_Name = {
    Text = "베일 속에서"
  },
  Stage_7754_Desc = {
    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_7754_Name = {
    Text = "혈육의 늪지·회전 간격Ⅱ"
  },
  Stage_7755_Desc = {
    Text = "그 후로 용사는 고향으로 돌아가 공주와 결혼했고, 행복하고 평온하게 살았답니다. \n정말로? 거짓말이야."
  },
