  Stage_77999_Name = {
    Text = "카라부 체험 스테이지"
  },
  Stage_7799_Desc = {
    Text = "무너진 우상은 자신의 백성을 응시한다. \n 그들은 생존하고, 번식하고, 서로 싸우다가, 결국 자신을 완전히 잊는다. \n 무너진 우상은 그 백성을 그리워한다."
  },
  Stage_7799_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
  Stage_78001_Name = {
    Text = "카티구라 체험 스테이지"
  },
  Stage_78002_Name = {
    Text = "폴리덱스 체험 스테이지"
  },
  Stage_7800_Desc = {
    Text = "「이곳에는 만신창이가 되어 지쳐버린 대학이 잠들어 있다. \n그곳은 한때 인류의 존속을 위해 일말의 희망과 용기를 바쳤고, 그 결과는 지금 당신이 보는 그대로다.」"
  },
  Stage_7800_Name = {
    Text = "환몽 심잠 Ⅵ"
  },
  Stage_7801_Desc = {
    Text = "카다스의 극점에 위치한 엘워스는 일년 내내 녹지 않는 얼음과 눈으로 덮여 있고, \n두껍고 단단한 빙하 아래에는 생명의 맥동이 어렴풋이 느껴진다."
  },
  Stage_7801_Name = {
    Text = "무질서한 산맥 Ⅳ"
  },
