  Stage_7814_Desc = {
    Text = "그것은 바다를 갈라놓으려는 의도를 가진 이의 거대한 검이며, 모든 바다를 평평하게 만들려는 의도를 지닌 이의 야심입니다."
  },
  Stage_7814_Name = {
    Text = "광신도의 거대한 칼"
  },
  Stage_7815_Desc = {
    Text = "현실타래은 화근을 심었으나, 운명은 만남을 이끌었다."
  },
  Stage_7815_Name = {
    Text = "운명의 씨앗"
  },
  Stage_7816_Desc = {
    Text = "여러 바다를 건너는 해의 사도."
  },
  Stage_7816_Name = {Text = "사도"},
  Stage_7817_Desc = {
    Text = "배에서 선장 외에 누구를 믿을 수 있을까?"
  },
  Stage_7817_Name = {Text = "선원"},
  Stage_7818_Desc = {
    Text = "후퇴할 곳이 없을 때, 훈련된 파트너가 주로 상황을 해결하는 열쇠가 된다는 것을 — 라몬나는 다시 한 번 당신에게 이 점을 가르쳐주었다."
  },
  Stage_7818_Name = {
    Text = "막다른 길"
  },
  Stage_7819_Desc = {
    Text = "각 바다를 밟고 지나가는 것은 적뿐만 아니라 희망의 약한 빛일 수도 있다."
  },
  Stage_7819_Name = {
    Text = "침몰한 자"
  },
  Stage_7820_Desc = {
    Text = "밤의 항구, 친절한 주민들, 따뜻한 환대."
  },
  Stage_7820_Name = {Text = "매복"},
  Stage_7821_Desc = {
    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_7821_Name = {
    Text = "심해의 유산·회전 간격Ⅱ"
