  },
  Stage_7824_Name = {
    Text = "또 다른 기적"
  },
  Stage_7825_Desc = {
    Text = "돌파구를 찾는 것은 언제나 단순하지 않다, 하지만 다행히도 이번에는 수호자가 가장 밝은 항성을 찾았습니다."
  },
  Stage_7825_Name = {
    Text = "추적하는 별빛"
  },
  Stage_7826_Desc = {
    Text = "로저스 밀랍인형관은 사우스워크 가의 깊은 곳에 자리하고 있으며, 템스 강의 지류와 가깝다. \n전혀 눈에 띄지 않는 곳이지만, 수많은 아방가르드 예술 애호가들이 그 명성을 듣고 찾아온다."
  },
  Stage_7826_Name = {
    Text = "광기의 박물관 Ⅰ"
  },
  Stage_7827_Desc = {
    Text = "그는 그분이 될 수 없고, 그분은 절대 그가 될 수 없다. \n맞아…… 맞아, 오직 나의 신성만이 진정한 그이다."
  },
  Stage_7827_Name = {
    Text = "잃어버린 빛"
