  },
  Stage_7831_Desc = {
    Text = "「이곳에는 만신창이가 되어 지쳐버린 대학이 잠들어 있다. \n그곳은 한때 인류의 존속을 위해 일말의 희망과 용기를 바쳤고, 그 결과는 지금 당신이 보는 그대로다.」"
  },
  Stage_7831_Name = {
    Text = "환몽 심잠 Ⅱ"
  },
  Stage_7832_Desc = {
    Text = "「이곳에는 만신창이가 되어 지쳐버린 대학이 잠들어 있다. \n그곳은 한때 인류의 존속을 위해 일말의 희망과 용기를 바쳤고, 그 결과는 지금 당신이 보는 그대로다.」"
  },
  Stage_7832_Name = {
    Text = "환몽 심잠 Ⅲ"
  },
  Stage_7833_Desc = {
    Text = "「이곳에는 만신창이가 되어 지쳐버린 대학이 잠들어 있다. \n그곳은 한때 인류의 존속을 위해 일말의 희망과 용기를 바쳤고, 그 결과는 지금 당신이 보는 그대로다.」"
  },
  Stage_7833_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
  Stage_7834_Desc = {
    Text = "이곳에서 창궐하는 것은 보통 질병이 아니다."
  },
  Stage_7834_Name = {Text = "병"},
  Stage_7835_Desc = {
    Text = "빈민원을 감싸는 짙은 안개 속에서 절단, 소실타래, 그리고 죽음과 마주한다."
  },
  Stage_7835_Name = {
    Text = "누가 참새를 죽였나?"
  },
  Stage_7836_Desc = {
    Text = "그분의 나라는 우주의 껍데기이며, 그분의 욕망은 끝이 없다."
  },
  Stage_7836_Name = {
    Text = "벌레의 소굴 Ⅴ"
  },
  Stage_7837_Desc = {
    Text = "당신은 라모나와 함께 론디니움 동부 지구의 릴리 빈민원으로 향해, 신입 수호자로서의 첫 조사를 시작한다. \n모든 일이 순조로울 것이다... 아마도?"
  },
  Stage_7837_Name = {
    Text = "겉모습에 속지 말라"
  },
  Stage_7838_Desc = {
    Text = "달콤하고, 향기로운 아이들의 친구.\n고상하고, 자유로운 어른들의 동경."
  },
  Stage_7838_Name = {
    Text = "달콤한 예술"
  },
  Stage_7839_Desc = {
    Text = "양심의 무게는 맹세와 같다."
  },
  Stage_7839_Name = {
    Text = "양심의 무게"
  },
  Stage_7840_Desc = {
    Text = "위험은 내부에서 온다."
  },
  Stage_7840_Name = {
    Text = "내부의 위험"
  },
  Stage_7841_Desc = {
    Text = "나는 영원히 자라지 않고, 매일 이렇게 너와 별을 보고 싶어. \n나는 더 빨리 자랐으면 좋겠어. 그러면 너희 모두를 지킬 수 있을 텐데."
  },
  Stage_7841_Name = {
    Text = "우리의 비밀"
  },
  Stage_7842_Desc = {
    Text = "인형의 가느다란 실타래을 자르면, 더 이상 춤추지 못할 것이다."
  },
  Stage_7842_Name = {
    Text = "새들이 없는 밤"
  },
  Stage_7843_Desc = {
    Text = "당신이 알고 싶은 모든 것이 당신의 눈앞에 있지만, 발견하지 못했을 뿐이다."
  },
  Stage_7843_Name = {
    Text = "모자 아래에 숨겨진"
  },
  Stage_7844_Desc = {
    Text = "라모나가 팀으로 돌아왔다. 미사그 조사원의 여정은 계속된다."
  },
  Stage_7844_Name = {
    Text = "어제의 재현"
  },
  Stage_7845_Desc = {
    Text = "인간의 다리는 야생동물의 민첩한 네 발을 이길 수 없지만, 두뇌로는 가능하다. 하지만 \"헬하운드\"를 포획한 후, 일행을 기다리고 있는 것은 무엇일까?"
  },
  Stage_7845_Name = {
    Text = "비장의 카드"
  },
  Stage_7846_Desc = {
    Text = "즐거운 여정 되시길 바랍니다."
  },
  Stage_7846_Name = {
    Text = "좋은 여행 되세요"
  },
  Stage_7847_Desc = {
    Text = "당신들은 지하철 안에서 정체불명의 암살자에게 습격을 당했다…"
  },
  Stage_7847_Name = {Text = "고독"},
  Stage_7848_Desc = {
    Text = "다포딜과의 교류는 언제나 거래의 형태였다. 이번에도 나타나서 당신에게 거래를 제안했지만, 정체불명의 습격자도 이 거래에 응할까?"
  },
  Stage_7848_Name = {
    Text = "공정한 거래"
  },
  Stage_7849_Desc = {
    Text = "지옥견 \"케르베로스\"에 관한 소문을 추적하는 과정에서, 미사그 조사원들은 실타래종 사건의 진상을 파헤치기 위해 론디니움 외곽의 작은 마을 '라이'에 도착했다..."
  },
  Stage_7849_Name = {
    Text = "생각하고 행동하라"
  },
  Stage_7850_Desc = {
    Text = "좋은 소식과 나쁜 소식이 있다. 사라진 단서는 다시 나타나지 않겠지만, 새로운 사건들이 암암리에 준비되고 있다. 장담컨대, 조사원들은 빈손으로 돌아가지 않을 것이다."
  },
  Stage_7850_Name = {
    Text = "좋은 소식, 나쁜 소식"
  },
  Stage_7851_Desc = {
    Text = "광기 어린 어조와 강렬한 비린내, 이것이 라이의 환영 방식이다."
  },
  Stage_7851_Name = {
    Text = "라이에 오신 것을 환영합니다"
  },
  Stage_7852_Desc = {
    Text = "인형은 침대 가장자리에 얌전히 기대어 앉아 있고, 초점 없는 단추 눈은 허공을 바라본다.\n작은 몸으로 주인의 모든 눈물을 받아냈지만, 위로의 말은 건넬 수 없었다."
  },
  Stage_7852_Name = {
    Text = "인형의 눈물 Ⅲ"
  },
  Stage_7855_Desc = {
    Text = "그는 그분이 될 수 없고, 그분은 절대 그가 될 수 없다. \n맞아…… 맞아, 오직 나의 신성만이 진정한 그이다."
  },
  Stage_7855_Name = {
    Text = "잃어버린 빛"
  },
  Stage_7856_Desc = {
    Text = "뭇별이 생겨나기 전부터, 그것들은 이미 이곳에 존재했다. 그들은 허무이자, 모든 것이기도 하다."
  },
  Stage_7856_Name = {
    Text = "혼돈 잔상 Ⅳ"
  },
  Stage_7857_Desc = {
    Text = "그들은 바다의 비밀을 말없이 지키며, 영혼은 우주만큼이나 깊다."
  },
  Stage_7857_Name = {
    Text = "해연 잔상 Ⅱ"
  },
  Stage_7858_Desc = {
    Text = "어찌 영원히 지지 않는 석양이 있을 수 있겠는가?"
  },
  Stage_7858_Name = {Text = "일몰"},
  Stage_7859_Desc = {
    Text = "비가 내리고 피가 흐를 때, 우리는 다시 만나는 순간을 맞이합니다. \n오랜만입니다, 수호자."
  },
  Stage_7859_Name = {
    Text = "뜻밖의 만남"
  },
  Stage_7860_Desc = {
    Text = "그들은 종잡을 수 없는 마법사처럼 시공간의 틈새를 떠돌아다닌다. 증오도, 두려움도, 연민도 없다."
  },
  Stage_7860_Name = {
    Text = "차원 잔상 Ⅰ"
  },
  Stage_7861_Desc = {
    Text = "사냥개는 규칙을 깨뜨린 자들을 쉴새없이 추적한다. \n'규칙'이란 무엇이며, 그것을 '깨뜨린다'는 것은 또 무엇인가? \n사냥개는 그런 것들을 생각하지 않는다— 생각은 덮치는 속도를 늦출 뿐이다."
  },
  Stage_7861_Name = {
    Text = "너머의 그림자 Ⅳ"
  },
  Stage_7862_Desc = {
    Text = "그들은 바다의 비밀을 말없이 지키며, 영혼은 우주만큼이나 깊다."
  },
  Stage_7862_Name = {
    Text = "해연 잔상 Ⅲ"
  },
  Stage_7863_Desc = {
    Text = "그들은 바다의 비밀을 말없이 지키며, 영혼은 우주만큼이나 깊다."
  },
  Stage_7863_Name = {
    Text = "해연 잔상 Ⅰ"
  },
  Stage_7864_Desc = {
    Text = "론디니움은 찬란한 산업 문명과 도시를 뒤덮은 회색 안개로 유명하다. \n안개는 어디에나 있으며, 지나가는 사람들에게는 그저 우연적이고 무의미한 불편함 정도에 불과하다."
  },
  Stage_7864_Name = {
    Text = "안개의 도시 Ⅰ"
  },
  Stage_7865_Desc = {
    Text = "무엇이 그녀의 눈을 가렸는가? \n 사랑, 연민, 정의, 아니면 지나친 감사였나?"
  },
  Stage_7865_Name = {Text = "초월"},
  Stage_7866_Desc = {
    Text = "아이가 어머니에게 양손을 내밀어 고통으로 가득 찬 포옹을 갈망합니다. \n주사바늘이 연부드러운 표피를 뚫고, 수술칼이 희백한 피부를 가릅니다. 속박띠가 약한 관절을 묶어도. \n끝없이 퍼져나가는 고통조차 그들이 서로를 껴안는 것을 막을 수 없습니다. \n왜냐하면, 이는 가장 따뜻한 포옹이기 때문입니다. 태아가 모체에서 벗어나 간극이 생기고, 마찰로 날카로워져 서로를 해치지만, 결국 회귀하여 친밀해지고 하나가 됩니다."
  },
  Stage_7866_Name = {Text = "그녀"},
  Stage_7867_Desc = {
    Text = "당신은 밤의 침묵 속에서 잠들어 있습니다. \n어떤 의혹이나 분쟁도 남아 있지 않고, \n영원한 포옹처럼, \n우리는 평온한 안정 속에 누워 있습니다."
  },
  Stage_7867_Name = {Text = "방"},
  Stage_7868_Desc = {
    Text = "하얀 눈밭 속에서 백합이 만발한다."
  },
  Stage_7868_Name = {
    Text = "신비한 강"
  },
  Stage_7869_Desc = {
    Text = "새벽은 언제나 도래하고, 태양은 평소대로 떠오릅니다."
  },
  Stage_7869_Name = {
    Text = "에필로그"
  },
  Stage_7870_Desc = {
    Text = "그녀는 몸으로 성스러운 유골을 품고, 교리로 신도들을 이끌며, 독니로 신앙을 퍼뜨렸다.\n그녀의 기도는 멈추지 않고, 그녀의 부름은 그치지 않는다."
  },
  Stage_7870_Name = {
    Text = "신앙의 손아귀 Ⅱ"
  },
  Stage_7871_Desc = {
    Text = "예리한 가시가 완벽한 원을 찢었으나, 그것은 ‘케르베로스’의 것이 아니며, 균열 속에서 모습을 드러냈다."
  },
  Stage_7871_Name = {
    Text = "껍질 속 균열"
  },
  Stage_7872_Desc = {
    Text = "현실타래은 화근을 심었으나, 운명은 만남을 이끌었다."
  },
  Stage_7872_Name = {
    Text = "운명의 씨앗"
  },
  Stage_78738_Name = {
    Text = "본원 잠자는 왕 체험 스테이지"
  },
  Stage_7873_Desc = {
    Text = "그것들은 어둠 속에서 뒤틀리고 융합한 후, 엄숙히 조각상 안에 보관되었다.\n이는 오래 전부터 계획되었던 재회였다."
  },
  Stage_7873_Name = {
    Text = "심해의 유산·간격Ⅴ"
  },
  Stage_7874_Desc = {
    Text = "배에서 선장 외에 누구를 믿을 수 있을까?"
  },
  Stage_7874_Name = {Text = "선원"},
  Stage_7875_Desc = {
    Text = "여러 바다를 건너는 해의 사도."
  },
  Stage_7875_Name = {Text = "사도"},
  Stage_7876_Desc = {
    Text = "각 바다를 밟고 지나가는 것은 적뿐만 아니라 희망의 약한 빛일 수도 있다."
  },
  Stage_7876_Name = {
    Text = "침몰한 자"
  },
  Stage_78773_Name = {
    Text = "본원 심해의 숙녀 체험 스테이지"
  },
  Stage_7877_Desc = {
    Text = "그들은 본래 슬픔, 왜곡, 그리고 무지로 이루어진 무의식적 집합체였지만, \n행복한 아이와 어른, 그리고 애완동물의 모습으로 꾸며졌다. \n단 한 번도 행복을 맛본 적이 없었기에, 그들은 최악의 배우였다."
  },
  Stage_7877_Name = {
    Text = "밀랍상의 비밀 Ⅱ"
  },
  Stage_7878_Desc = {
    Text = "밤의 항구, 친절한 주민들, 따뜻한 환대."
  },
  Stage_7878_Name = {Text = "매복"},
  Stage_7879_Desc = {
    Text = "정체불명의 조각상이 어둠 속을 떠돌아다니며 떨고 있다.\n그들은 오래된 리듬에 맞춰, 먼 곳에서 들려오는 피리 소리를 따라 춤을 추었다."
  },
  Stage_7879_Name = {
    Text = "혈육의 늪지·간격Ⅷ"
  },
  Stage_7880_Desc = {
    Text = "돌파구를 찾는 것은 언제나 단순하지 않다, 하지만 다행히도 이번에는 수호자가 가장 밝은 항성을 찾았습니다."
  },
  Stage_7880_Name = {
    Text = "추적하는 별빛"
  },
  Stage_7881_Desc = {
    Text = "두 번째 심장이 머피의 몸에서 뛰고 있어, 「탄생 의식」을 막아야 한다."
  },
  Stage_7881_Name = {
    Text = "또 다른 기적"
  },
  Stage_7882_Desc = {
    Text = "정체불명의 조각상이 어둠 속을 떠돌아다니며 떨고 있다.\n그들은 오래된 리듬에 맞춰, 먼 곳에서 들려오는 피리 소리를 따라 춤을 추었다."
  },
  Stage_7882_Name = {
    Text = "혼돈의 영역·간격Ⅶ"
  },
  Stage_7883_Desc = {
    Text = "진실타래, 이 잔인한 진실타래."
  },
  Stage_7883_Name = {
    Text = "베일 속에서"
  },
  Stage_7884_Desc = {
    Text = "조용히 타오르는 불꽃은 여행자에게 허망한 약속을 한다."
  },
  Stage_7884_Name = {
    Text = "유혹의 불꽃"
  },
  Stage_7885_Desc = {
    Text = "운명의 광풍 속에서 떨고, 발버둥치지만 그것은 정말로 떠돌지 않을 것이다."
  },
  Stage_7885_Name = {
    Text = "흔들리는 운명"
  },
  Stage_7886_Desc = {
    Text = "안개 속에 감싸진 궤적, 수많은 발걸음이 그 위를 맴돌고, 각각의 발걸음은 운명에 대한 물음이다."
  },
  Stage_7886_Name = {
    Text = "미궁 같은 앞길"
  },
  Stage_7887_Desc = {
    Text = "무너진 우상은 자신의 백성을 응시한다. \n 그들은 생존하고, 번식하고, 서로 싸우다가, 결국 자신을 완전히 잊는다. \n 무너진 우상은 그 백성을 그리워한다."
  },
  Stage_7887_Name = {
    Text = "환몽 심잠 Ⅳ"
  },
  Stage_7888_Desc = {
    Text = "투박하고, 미처 소화되지 못한 물질 무더기. 사람들은 그것을 배설물, 혹은 혼돈이라고 부른다.\n세계는 배설물에서 탄생했다."
  },
  Stage_7888_Name = {
    Text = "혼돈 군집 Ⅰ"
  },
  Stage_7889_Desc = {
    Text = "떠나간 이가 잊혀지면, 모든 것은 다시 평상시대로 돌아온다.\n하지만 누군가는 그 사라져가는 기억들을 간직하고 있을 것이다."
  },
  Stage_7889_Name = {
    Text = "돌아온 일상"
  },
  Stage_7890_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_7890_Name = {
    Text = "환몽 심잠 Ⅴ"
  },
  Stage_7891_Desc = {
