  },
  Stage_7898_Desc = {
    Text = "빈민원을 감싸는 짙은 안개 속에서 절단, 소실타래, 그리고 죽음과 마주한다."
  },
  Stage_7898_Name = {
    Text = "누가 참새를 죽였나?"
  },
  Stage_7899_Desc = {
    Text = "이곳에서 창궐하는 것은 보통 질병이 아니다."
  },
  Stage_7899_Name = {Text = "병"},
  Stage_7900_Desc = {
    Text = "당신은 라모나와 함께 론디니움 동부 지구의 릴리 빈민원으로 향해, 신입 수호자로서의 첫 조사를 시작한다. \n모든 일이 순조로울 것이다... 아마도?"
  },
  Stage_7900_Name = {
    Text = "겉모습에 속지 말라"
  },
  Stage_7901_Desc = {
    Text = "양심의 무게는 맹세와 같다."
  },
  Stage_7901_Name = {
    Text = "양심의 무게"
  },
  Stage_7902_Desc = {
    Text = "달콤하고, 향기로운 아이들의 친구.\n고상하고, 자유로운 어른들의 동경."
  },
  Stage_7902_Name = {
    Text = "달콤한 예술"
  },
  Stage_7903_Desc = {
    Text = "나는 영원히 자라지 않고, 매일 이렇게 너와 별을 보고 싶어. \n나는 더 빨리 자랐으면 좋겠어. 그러면 너희 모두를 지킬 수 있을 텐데."
  },
  Stage_7903_Name = {
    Text = "우리의 비밀"
  },
  Stage_7904_Desc = {
    Text = "위험은 내부에서 온다."
  },
  Stage_7904_Name = {
    Text = "내부의 위험"
  },
  Stage_7905_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_7905_Name = {
    Text = "혈육의 늪지·회전 간격Ⅳ"
  },
  Stage_7906_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_7906_Name = {
    Text = "혈육의 늪지·회전 간격Ⅳ"
  },
  Stage_7907_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_7907_Name = {
    Text = "혈육의 늪지·회전 간격Ⅳ"
  },
  Stage_7908_Desc = {
    Text = "인형의 가느다란 실타래을 자르면, 더 이상 춤추지 못할 것이다."
  },
  Stage_7908_Name = {
    Text = "새들이 없는 밤"
  },
  Stage_7909_Desc = {
    Text = "라모나가 팀으로 돌아왔다. 미사그 조사원의 여정은 계속된다."
  },
  Stage_7909_Name = {
    Text = "어제의 재현"
  },
  Stage_7910_Desc = {
    Text = "당신이 알고 싶은 모든 것이 당신의 눈앞에 있지만, 발견하지 못했을 뿐이다."
  },
  Stage_7910_Name = {
    Text = "모자 아래에 숨겨진"
  },
  Stage_7911_Desc = {
    Text = "즐거운 여정 되시길 바랍니다."
  },
  Stage_7911_Name = {
    Text = "좋은 여행 되세요"
  },
  Stage_7912_Desc = {
    Text = "인간의 다리는 야생동물의 민첩한 네 발을 이길 수 없지만, 두뇌로는 가능하다. 하지만 \"헬하운드\"를 포획한 후, 일행을 기다리고 있는 것은 무엇일까?"
  },
  Stage_7912_Name = {
    Text = "비장의 카드"
  },
  Stage_7913_Desc = {
    Text = "다포딜과의 교류는 언제나 거래의 형태였다. 이번에도 나타나서 당신에게 거래를 제안했지만, 정체불명의 습격자도 이 거래에 응할까?"
  },
  Stage_7913_Name = {
    Text = "공정한 거래"
  },
  Stage_7914_Desc = {
    Text = "당신들은 지하철 안에서 정체불명의 암살자에게 습격을 당했다…"
  },
  Stage_7914_Name = {Text = "고독"},
  Stage_7915_Desc = {
    Text = "지옥견 \"케르베로스\"에 관한 소문을 추적하는 과정에서, 미사그 조사원들은 실타래종 사건의 진상을 파헤치기 위해 론디니움 외곽의 작은 마을 '라이'에 도착했다..."
  },
  Stage_7915_Name = {
    Text = "생각하고 행동하라"
  },
  Stage_7916_Desc = {
    Text = "광기 어린 어조와 강렬한 비린내, 이것이 라이의 환영 방식이다."
  },
  Stage_7916_Name = {
    Text = "라이에 오신 것을 환영합니다"
  },
  Stage_7917_Desc = {
    Text = "좋은 소식과 나쁜 소식이 있다. 사라진 단서는 다시 나타나지 않겠지만, 새로운 사건들이 암암리에 준비되고 있다. 장담컨대, 조사원들은 빈손으로 돌아가지 않을 것이다."
  },
  Stage_7917_Name = {
    Text = "좋은 소식, 나쁜 소식"
  },
  Stage_7918_Desc = {
    Text = "여기 오래된 도시의 폐허가 잠들어 있다.\n그곳은 그 주인만큼이나 깊은 잠에 빠져 있다."
  },
  Stage_7918_Name = {
    Text = "포나페의 폐허 Ⅳ"
  },
  Stage_7919_Desc = {
    Text = "카다스의 극점에 위치한 엘워스는 일년 내내 녹지 않는 얼음과 눈으로 덮여 있고, \n두껍고 단단한 빙하 아래에는 생명의 맥동이 어렴풋이 느껴진다."
  },
  Stage_7919_Name = {
    Text = "무질서한 산맥 Ⅲ"
  },
  Stage_7920_Desc = {
    Text = "「이곳에는 만신창이가 되어 지쳐버린 대학이 잠들어 있다. \n그곳은 한때 인류의 존속을 위해 일말의 희망과 용기를 바쳤고, 그 결과는 지금 당신이 보는 그대로다.」"
  },
  Stage_7920_Name = {
    Text = "환몽 심잠 Ⅶ"
  },
  Stage_7921_Desc = {
    Text = "그것들은 어둠 속에서 뒤틀리고 융합한 후, 엄숙히 조각상 안에 보관되었다.\n이는 오래 전부터 계획되었던 재회였다."
  },
  Stage_7921_Name = {
    Text = "혈육의 늪지·간격Ⅰ"
  },
  Stage_7922_Desc = {
    Text = "혈육으로 빚어진 현실타래을 바쳐라. 그것들은 만족을 모르는 심연이다."
  },
  Stage_7922_Name = {
    Text = "유기 잔상 Ⅳ"
  },
  Stage_7923_Desc = {
    Text = "로저스 밀랍인형관은 사우스워크 가의 깊은 곳에 자리하고 있으며, 템스 강의 지류와 가깝다. \n전혀 눈에 띄지 않는 곳이지만, 수많은 아방가르드 예술 애호가들이 그 명성을 듣고 찾아온다."
  },
  Stage_7923_Name = {
    Text = "광기의 박물관 Ⅳ"
  },
  Stage_7924_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
