  Stage_7931_Desc = {
    Text = "그분의 나라는 우주의 껍데기이며, 그분의 욕망은 끝이 없다."
  },
  Stage_7931_Name = {
    Text = "벌레의 소굴 Ⅱ"
  },
  Stage_7932_Desc = {
