  },
  Stage_7932_Name = {
    Text = "포나페의 폐허 Ⅱ"
  },
  Stage_7933_Desc = {
    Text = "진실타래, 이 잔인한 진실타래."
  },
  Stage_7933_Name = {
    Text = "베일 속에서"
  },
  Stage_7934_Desc = {
    Text = "허무는 우리의 근원이자 종착지다."
  },
  Stage_7934_Name = {
    Text = "불멸의 속삭임"
  },
  Stage_7935_Desc = {
    Text = "정체불명의 조각상이 어둠 속을 떠돌아다니며 떨고 있다.\n그들은 오래된 리듬에 맞춰, 먼 곳에서 들려오는 피리 소리를 따라 춤을 추었다."
  },
  Stage_7935_Name = {
    Text = "심해의 유산·간격Ⅷ"
  },
  Stage_7936_Desc = {
    Text = "라이 마을은 론디니움의 북동쪽에 위치해 있으며, 끝없는 산맥 속에 숨겨져 있다. \n침묵하는 마을 사람들, 어디에나 있는 시선... 조심하라, 이곳의 모든 점이 평범하지 않다."
  },
  Stage_7936_Name = {
    Text = "혼란의 마을 Ⅱ"
  },
  Stage_7937_Desc = {
    Text = "「각 열쇠에는 고유한 번호가 있으며, 단 한 명의 조사원만이 대응된다.」\n즉, 열쇠 하나가 사라진다는 것은 곧 그 조사원의 죽음을 의미한다.\n멋지지 않은가? 죽음마저 유일무이하다니."
  },
  Stage_7937_Name = {
    Text = "환몽 심잠 Ⅴ"
  },
