  },
  Stage_7940_Desc = {
    Text = "「각 열쇠에는 고유한 번호가 있으며, 단 한 명의 조사원만이 대응된다.」\n즉, 열쇠 하나가 사라진다는 것은 곧 그 조사원의 죽음을 의미한다.\n멋지지 않은가? 죽음마저 유일무이하다니."
  },
  Stage_7940_Name = {
    Text = "환몽 심잠 Ⅵ"
  },
  Stage_7941_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_7941_Name = {
    Text = "혈육의 늪지·회전 간격Ⅲ"
  },
