  },
  Stage_7944_Name = {
    Text = "환몽 심잠 Ⅱ"
  },
  Stage_7945_Desc = {
    Text = "그녀는 꿈과 현실타래이 교차하는 경계이며, 밤하늘을 바라보는 각 영혼의 깊은 내면의 반사입니다."
  },
  Stage_7945_Name = {
    Text = "뒤틀린 별들"
  },
  Stage_7945_StageInitStateText = {Text = "해마"},
  Stage_7946_Desc = {
    Text = "우주 깊은 곳에 숨어 있는 구부러진 경계.\n당신을 한 어둠에서 또 다른 어둠으로 이끌 수 있다."
  },
  Stage_7946_Name = {
    Text = "블랙홀의 목구멍 Ⅰ"
  },
  Stage_7947_Desc = {
    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_7947_Name = {
    Text = "혼돈의 영역·간격Ⅲ"
  },
  Stage_7948_Desc = {
    Text = "여기 오래된 도시의 폐허가 잠들어 있다.\n그곳은 그 주인만큼이나 깊은 잠에 빠져 있다."
  },
  Stage_7948_Name = {
    Text = "포나페의 폐허 Ⅴ"
  },
  Stage_7949_Desc = {
    Text = "인형은 침대 가장자리에 얌전히 기대어 앉아 있고, 초점 없는 단추 눈은 허공을 바라본다.\n작은 몸으로 주인의 모든 눈물을 받아냈지만, 위로의 말은 건넬 수 없었다."
  },
  Stage_7949_Name = {
    Text = "인형의 눈물 Ⅱ"
  },
  Stage_7950_Desc = {
    Text = "건강을 위해 니코틴을 멀리하세요."
  },
  Stage_7950_Name = {
    Text = "연기와 제비꽃"
  },
  Stage_7951_Desc = {
    Text = "정체불명의 조각상이 어둠 속을 떠돌아다니며 떨고 있다.\n그들은 오래된 리듬에 맞춰, 먼 곳에서 들려오는 피리 소리를 따라 춤을 추었다."
  },
  Stage_7951_Name = {
    Text = "혈육의 늪지·간격Ⅱ"
  },
  Stage_7952_Desc = {
    Text = "혈육으로 빚어진 현실타래을 바쳐라. 그것들은 만족을 모르는 심연이다."
  },
  Stage_7952_Name = {
    Text = "유기 잔상 Ⅲ"
  },
  Stage_7953_Desc = {
    Text = "무너진 우상은 자신의 백성을 응시한다. \n 그들은 생존하고, 번식하고, 서로 싸우다가, 결국 자신을 완전히 잊는다. \n 무너진 우상은 그 백성을 그리워한다."
  },
  Stage_7953_Name = {
    Text = "환몽 심잠 Ⅱ"
  },
  Stage_7954_Desc = {
    Text = "그 후 그녀는 사라지고, 어둠 속으로 돌아갔다. \n사람들은 눈을 크게 뜬 채 고개를 들어 그녀가 지나갔던 하늘을 올려다보았다."
  },
  Stage_7954_Name = {Text = "설송목"},
  Stage_7955_Desc = {
    Text = "그녀의 아름다움이라는 이름의 제단 위에, 나는 내 눈물과 탄식, 그리고 진심을 바친다."
  },
  Stage_7955_Name = {
    Text = "갈라테아"
  },
  Stage_7956_Desc = {
    Text = "무너진 우상은 자신의 백성을 응시한다. \n 그들은 생존하고, 번식하고, 서로 싸우다가, 결국 자신을 완전히 잊는다. \n 무너진 우상은 그 백성을 그리워한다."
  },
  Stage_7956_Name = {
    Text = "환몽 심잠 Ⅴ"
  },
  Stage_79574_Desc = {
    Text = "노출된 심장, 오래된 표본, 흐릿한 은열쇠……\n그녀가 기다리는 것은 당신이 가져다줄 작별 인사이다."
  },
  Stage_79574_Name = {
    Text = "화염의 나비·지네"
  },
  Stage_79575_Desc = {
    Text = "오랜 은빛이 소녀에게 세 번째 생명을 부여했습니다. \n마지막 눈물은 더는 흐르지 않고, 영원한 고통이 시작되었습니다. \n첫 번째 눈물이 떨어지기 시작하며, 새로운 인생이 새 장을 열었습니다. \n죽음을 맞이하려던 사람이 다시 출발하여 진정한 자신을 찾기 위해 떠났습니다."
