  },
  Stage_79596_Desc = {
    Text = "무형의 불은 수많은 생명을 연료로 삼아 세상의 만상을 태워버린다. \n비명조차 용납하지 않고, 머물러 있을 곳도 없으며, 어떤 흔적도 남기지 않는다. \n그 분노는 끝이 없고, 소리 없는 포효는 영원히 멈추지 않는다. \n왜냐하면 항상 운명에 저항하며 재가 될 운명인 연료를 구원하려 한다."
  },
  Stage_79596_Name = {
    Text = "타오르는 세계·육"
  },
  Stage_79597_Desc = {
    Text = "무형의 불은 수많은 생명을 연료로 삼아 세상의 만상을 태워버린다. \n비명조차 용납하지 않고, 머물러 있을 곳도 없으며, 어떤 흔적도 남기지 않는다. \n그 분노는 끝이 없고, 소리 없는 포효는 영원히 멈추지 않는다. \n왜냐하면 항상 운명에 저항하며 재가 될 운명인 연료를 구원하려 한다."
