  Stage_79599_Name = {
    Text = "타오르는 세계·세 번째"
  },
  Stage_7959_Desc = {
    Text = "뒤돌아보지 말라! 얼마나 귀중한 당부인가. 오르페우스의 전철을 밟지 말라."
  },
  Stage_7959_Name = {
    Text = "뒤돌아보지 말라"
  },
