  },
  Stage_79600_Name = {
    Text = "타오르는 세계·둘째"
  },
  Stage_79601_Desc = {
    Text = "무형의 불은 수많은 생명을 연료로 삼아 세상의 만상을 태워버린다. \n비명조차 용납하지 않고, 머물러 있을 곳도 없으며, 어떤 흔적도 남기지 않는다. \n그 분노는 끝이 없고, 소리 없는 포효는 영원히 멈추지 않는다. \n왜냐하면 항상 운명에 저항하며 재가 될 운명인 연료를 구원하려 한다."
  },
  Stage_79601_Name = {
    Text = "타오르는 세계·중 하나"
  },
  Stage_79602_Desc = {
    Text = "진자 운동의 리듬에 따라 움직이고, 주변에서 들리는 아름다운 곤충들의 소리를 들어보세요. 피곤한 신경을 이완시키고, 클레멘틴 의사가 당신을 꿈으로 안내할 것입니다. \n마음의 전당에 오신 것을 환영합니다."
  },
  Stage_79602_Name = {
    Text = "꿈을 침입할 때·지오"
  },
  Stage_79603_Desc = {
