  },
  Stage_79607_Name = {
    Text = "꿈을 침입할 때·세 번째"
  },
  Stage_79608_Desc = {
    Text = "진자 운동의 리듬에 따라 움직이고, 주변에서 들리는 아름다운 곤충들의 소리를 들어보세요. 피곤한 신경을 이완시키고, 클레멘틴 의사가 당신을 꿈으로 안내할 것입니다. \n마음의 전당에 오신 것을 환영합니다."
  },
  Stage_79608_Name = {
    Text = "꿈을 침입할 때·둘째"
  },
  Stage_7960_Desc = {
    Text = "얼마나 행복한 잠이었는지, 그것은 내 천사를 다시 내 곁으로 돌려주었다."
  },
  Stage_7960_Name = {
    Text = "비밀 창문"
  },
  Stage_7961_Desc = {
    Text = "일기는 기억의 파편이다. \n조사 중에는 항상 일기가 발견된다."
  },
  Stage_7961_Name = {
    Text = "기억의 파편"
  },
  Stage_7962_Desc = {
    Text = "하얀 눈밭 속에서 백합이 만발한다."
  },
  Stage_7962_Name = {Text = "28일"},
  Stage_7963_Desc = {
    Text = "귀족들이 권력을 잃을 때, 부자들이 전재산을 잃을 때 그들은 한없이 무력해진다. 지금의 당신처럼."
  },
  Stage_7963_Name = {
    Text = "광기의 병동"
  },
  Stage_7964_Desc = {
    Text = "이곳은 그녀를 위해 만들어진 세계로, 위대한 사랑의 증거이자 공포스러운 감옥이다."
  },
  Stage_7964_Name = {
    Text = "정신병원"
  },
  Stage_7965_Desc = {
    Text = "세상의 싸움은 칼날이 맞부딪히는 전장에만 있는 것이 아니다. 때로는 미치광이의 입에서 시작될 수도 있다."
  },
  Stage_7965_Name = {
    Text = "광인의 입"
  },
  Stage_7966_Desc = {
    Text = "조용히 타오르는 불꽃은 여행자에게 허망한 약속을 한다."
  },
  Stage_7966_Name = {
    Text = "유혹의 불꽃"
  },
  Stage_7967_Desc = {
    Text = "안개 속에 감싸진 궤적, 수많은 발걸음이 그 위를 맴돌고, 각각의 발걸음은 운명에 대한 물음이다."
  },
  Stage_7967_Name = {
    Text = "미궁 같은 앞길"
  },
  Stage_7968_Desc = {
    Text = "사냥개는 규칙을 깨뜨린 자들을 쉴새없이 추적한다. \n'규칙'이란 무엇이며, 그것을 '깨뜨린다'는 것은 또 무엇인가? \n사냥개는 그런 것들을 생각하지 않는다— 생각은 덮치는 속도를 늦출 뿐이다."
  },
  Stage_7968_Name = {
    Text = "너머의 그림자 Ⅰ"
  },
  Stage_7969_Desc = {
    Text = "그녀는 몸으로 성스러운 유골을 품고, 교리로 신도들을 이끌며, 독니로 신앙을 퍼뜨렸다.\n그녀의 기도는 멈추지 않고, 그녀의 부름은 그치지 않는다."
  },
  Stage_7969_Name = {
    Text = "신앙의 손아귀 Ⅰ"
  },
  Stage_7970_Desc = {
    Text = "폭풍우는 아직 준비 중이며, 모든 것이 종료되지 않았습니다."
  },
  Stage_7970_Name = {
    Text = "다시 현실타래로"
  },
  Stage_7971_Desc = {
    Text = "그것은 기대받지 못한 생명이었을 뿐, 더러운 기생충에 불과했다."
  },
  Stage_7971_Name = {Text = "기생충"},
  Stage_7972_Desc = {
    Text = "육지를 향해, 생존의 기회를 향해,"
  },
  Stage_7972_Name = {
    Text = "비극의 출항"
  },
  Stage_7973_Desc = {
    Text = "야색은 암류에 침식당하고, 별빛은 잃어버렸다. 전환과 풍우의 위기의 달이, 미지의 미래를 조용히 비추고 있다."
  },
  Stage_7973_Name = {
    Text = "위기의 달"
  },
  Stage_7974_Desc = {
    Text = "무한한 밤의 어둠 속에서 유인하는 빛을 쫓아가는 것처럼, 화염의 나비처럼 모든 것을 버리고 운명의 불꽃을 향해 날아오른다."
  },
  Stage_7974_Name = {Text = "불나방"},
  Stage_7975_Desc = {
    Text = "지난 세월에 흔들리던 우정은 새로운 희망을 결어졌습니다."
  },
  Stage_7975_Name = {
    Text = "옛 벗과 새 친구"
  },
  Stage_7976_Desc = {
    Text = "운명의 광풍 속에서 떨고, 발버둥치지만 그것은 정말로 떠돌지 않을 것이다."
  },
  Stage_7976_Name = {
    Text = "흔들리는 운명"
  },
  Stage_7977_Desc = {
    Text = "바람과 황사 속에서 전사가 결연하게 태양을 향해 달려갔다."
  },
  Stage_7977_Name = {
    Text = "태양 원정대"
  },
  Stage_7978_Desc = {
    Text = "꿈틀거리고, 흘러내린다... 족쇄의 틈새로 원생질 종양이 빠져나가고 있다.\n이것은 그녀가 '자유'를 위해 치른 대가이다."
  },
  Stage_7978_Name = {
    Text = "칠흑의 사슬 Ⅴ"
  },
  Stage_7979_Desc = {
    Text = "투박하고, 미처 소화되지 못한 물질 무더기. 사람들은 그것을 배설물, 혹은 혼돈이라고 부른다.\n세계는 배설물에서 탄생했다."
  },
  Stage_7979_Name = {
    Text = "혼돈 군집 Ⅲ"
  },
  Stage_7980_Desc = {
    Text = "정체불명의 조각상이 어둠 속을 떠돌아다니며 떨고 있다.\n그들은 오래된 리듬에 맞춰, 먼 곳에서 들려오는 피리 소리를 따라 춤을 추었다."
  },
  Stage_7980_Name = {
    Text = "초월의 여정·간격Ⅷ"
  },
  Stage_7981_Desc = {
    Text = "그것들은 어둠 속에서 뒤틀리고 융합한 후, 엄숙히 조각상 안에 보관되었다.\n이는 오래 전부터 계획되었던 재회였다."
  },
  Stage_7981_Name = {
    Text = "혈육의 늪지·간격Ⅴ"
  },
  Stage_7982_Desc = {
    Text = "그 후 그녀는 사라지고, 어둠 속으로 돌아갔다. \n사람들은 눈을 크게 뜬 채 고개를 들어 그녀가 지나갔던 하늘을 올려다보았다."
  },
  Stage_7982_Name = {Text = "설송목"},
  Stage_7983_Desc = {
    Text = "작은 쥐 한 마리, 작은 쥐 한 마리.\n달려라, 달려, 그녀는 고기 칼로 쥐의 꼬리를 자르고 말았네."
  },
  Stage_7983_Name = {
    Text = "브라운 출격"
  },
  Stage_7984_Desc = {
    Text = "당신은 밤의 침묵 속에서 잠들어 있습니다. \n어떤 의혹이나 분쟁도 남아 있지 않고, \n영원한 포옹처럼, \n우리는 평온한 안정 속에 누워 있습니다."
  },
  Stage_7984_Name = {Text = "방"},
  Stage_7985_Desc = {
    Text = "론디니움은 찬란한 산업 문명과 도시를 뒤덮은 회색 안개로 유명하다. \n안개는 어디에나 있으며, 지나가는 사람들에게는 그저 우연적이고 무의미한 불편함 정도에 불과하다."
  },
  Stage_7985_Name = {
    Text = "안개의 도시 Ⅲ"
  },
  Stage_7986_Desc = {
    Text = "그녀의 아름다움이라는 이름의 제단 위에, 나는 내 눈물과 탄식, 그리고 진심을 바친다."
  },
  Stage_7986_Name = {
    Text = "갈라테아"
  },
  Stage_7987_Desc = {
    Text = "철벅철벅, 갈라졌네. 철벅철벅, 부러졌네."
  },
  Stage_7987_Name = {
    Text = "인형의 집"
  },
  Stage_7988_Desc = {
    Text = "규칙은 깨라고 있는 것 아닌가?"
  },
  Stage_7988_Name = {
    Text = "세 가지 규칙"
  },
  Stage_7989_Desc = {
    Text = "요크셔 북쪽에 위치한 해변 마을, 스카버러. 높은 절벽과 금빛 만으로 유명하여, 우아하고 매력적인 휴양지다."
  },
  Stage_7989_Name = {
    Text = "스카버러의 여름"
  },
  Stage_7990_Desc = {
    Text = "팔, 이 성가신 팔! 항상 제 머리카락을 잡아당기고 있어요."
  },
  Stage_7990_Name = {Text = "스물넷"},
  Stage_7991_Desc = {
    Text = "그녀는 인간의 눈물과 배설물 속에서, 세상의 그 어떤 책보다도 더 많은 실타래용적인 심리학 지식을 얻었다."
  },
  Stage_7991_Name = {
    Text = "진료 수첩"
  },
  Stage_7992_Desc = {
    Text = "건강을 위해 니코틴을 멀리하세요."
  },
  Stage_7992_Name = {
    Text = "연기와 제비꽃"
  },
  Stage_7993_Desc = {
    Text = "요크셔 북쪽에 위치한 해변 마을, 스카버러. 높은 절벽과 금빛 만으로 유명하여, 우아하고 매력적인 휴양지다."
  },
  Stage_7993_Name = {
    Text = "스카보로의 여름"
  },
  Stage_7994_Desc = {
    Text = "건강을 위해 니코틴을 멀리하세요."
  },
  Stage_7994_Name = {
    Text = "연기와 제비꽃"
  },
  Stage_7995_Desc = {
    Text = "작은 쥐 한 마리, 작은 쥐 한 마리.\n달려라, 달려, 그녀는 고기 칼로 쥐의 꼬리를 자르고 말았네."
  },
  Stage_7995_Name = {
    Text = "브라운 출격"
  },
  Stage_7996_Desc = {
    Text = "그 후 그녀는 사라지고, 어둠 속으로 돌아갔다. \n사람들은 눈을 크게 뜬 채 고개를 들어 그녀가 지나갔던 하늘을 올려다보았다."
  },
  Stage_7996_Name = {Text = "설송목"},
  Stage_7997_Desc = {
    Text = "그녀의 아름다움이라는 이름의 제단 위에, 나는 내 눈물과 탄식, 그리고 진심을 바친다."
  },
  Stage_7997_Name = {
    Text = "갈라테아"
  },
  Stage_7998_Name = {
    Text = "[프롤로그]"
  },
  Stage_7999_Desc = {
    Text = "팔, 이 성가신 팔! 항상 제 머리카락을 잡아당기고 있어요."
  },
  Stage_7999_Name = {Text = "스물넷"},
  Stage_8000_Desc = {
    Text = "네, 네. 눈은 마음의 감옥이고, 영혼은 육체를 묶는 족쇄입니다."
  },
  Stage_8000_Name = {
    Text = "해부적 우울"
  },
  Stage_8001_Desc = {
    Text = "그래, 아가야. 마음껏 울거라. 네 모든 고통을 담아서 세상에 다시 없을 걸작처럼 꾸미거라."
  },
  Stage_8001_Name = {
    Text = "소녀와 눈물"
  },
  Stage_8002_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8002_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
  Stage_8003_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8003_Name = {
    Text = "환몽 심잠 Ⅲ"
  },
  Stage_8004_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8004_Name = {
    Text = "환몽 심잠 Ⅱ"
  },
  Stage_8005_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8005_Name = {
    Text = "환몽 심잠 Ⅴ"
  },
  Stage_8006_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8006_Name = {
    Text = "환몽 심잠 Ⅳ"
  },
  Stage_8007_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8007_Name = {
    Text = "환몽 심잠 Ⅶ"
  },
  Stage_8008_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8008_Name = {
    Text = "환몽 심잠 Ⅵ"
  },
  Stage_8009_Desc = {
    Text = "여기 오래된 도시의 폐허가 잠들어 있다.\n그곳은 그 주인만큼이나 깊은 잠에 빠져 있다."
  },
  Stage_8009_Name = {
    Text = "포나페의 폐허 Ⅰ"
  },
  Stage_8010_Desc = {
    Text = "우리는 다른 시간과 공간의 차원에서 계속 만나게 될 것입니다"
  },
  Stage_8010_Name = {
    Text = "다음에 또 만나요"
  },
  Stage_8011_Desc = {
    Text = "우주 깊은 곳에 숨어 있는 구부러진 경계.\n당신을 한 어둠에서 또 다른 어둠으로 이끌 수 있다."
  },
  Stage_8011_Name = {
    Text = "블랙홀의 목구멍 Ⅱ"
  },
  Stage_8012_Desc = {
    Text = "우주 깊은 곳에 숨어 있는 구부러진 경계.\n당신을 한 어둠에서 또 다른 어둠으로 이끌 수 있다."
  },
  Stage_8012_Name = {
    Text = "블랙홀의 목구멍 Ⅴ"
  },
  Stage_8013_Desc = {
    Text = "신왕이 내린 관을 벗길 수 있는 이는 없다. 단 한 사람도."
  },
  Stage_8013_Name = {
    Text = "레무리아의 「영광」"
  },
  Stage_8014_Desc = {
    Text = "지난 세월에 흔들리던 우정은 새로운 희망을 결어졌습니다."
  },
  Stage_8014_Name = {
    Text = "옛 벗과 새 친구"
  },
  Stage_8015_Desc = {
    Text = "야색은 암류에 침식당하고, 별빛은 잃어버렸다. 전환과 풍우의 위기의 달이, 미지의 미래를 조용히 비추고 있다."
  },
  Stage_8015_Name = {
    Text = "위기의 달"
  },
  Stage_8016_Desc = {
    Text = "네, 욕심은 그의 원죄이며, 그는 이를 위해 후회할 것입니다."
  },
  Stage_8016_Name = {Text = "소멸"},
  Stage_8017_Desc = {
    Text = "침묵의 가디언이 새로운 목소리를 내기 시작했다."
  },
  Stage_8017_Name = {Text = "과보호"},
  Stage_8018_Desc = {
    Text = "무한한 밤의 어둠 속에서 유인하는 빛을 쫓아가는 것처럼, 화염의 나비처럼 모든 것을 버리고 운명의 불꽃을 향해 날아오른다."
  },
  Stage_8018_Name = {Text = "불나방"},
  Stage_8019_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_8019_Name = {
    Text = "혼돈의 영역·회전 간격Ⅲ"
  },
  Stage_8020_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_8020_Name = {
    Text = "혼돈의 영역·회전 간격Ⅲ"
  },
  Stage_8021_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_8021_Name = {
    Text = "혼돈의 영역·회전 간격Ⅲ"
  },
  Stage_8022_Desc = {
    Text = "그것은 기대받지 못한 생명이었을 뿐, 더러운 기생충에 불과했다."
  },
  Stage_8022_Name = {Text = "기생충"},
  Stage_8023_Desc = {
    Text = "얼마나 행복한 잠이었는지, 그것은 내 천사를 다시 내 곁으로 돌려주었다."
  },
  Stage_8023_Name = {
    Text = "비밀 창문"
  },
  Stage_80242_Desc = {
    Text = "이야기의 끝에, 세계는 여전히 타오르고 있으며, 저는 작별할 준비가 되어 있습니다.\n하지만 우리는 결국 다시 만날 것입니다."
  },
  Stage_80242_Name = {
    Text = "불타는 세계여, 안녕"
  },
  Stage_80243_Desc = {
    Text = "인은 사회적 동물입니다. 그들은 사회의 영향을 받으며, 또한 사회에 영향을 줍니다.\n그러므로 말씀해 주세요. 당신은 삶과 환경에 의해 어떤 모습으로 형성되었나요?"
  },
  Stage_80243_Name = {
    Text = "인지 재구성 실타래험"
  },
  Stage_80244_Desc = {
    Text = "미안해요, 당신께 드릴 특별한 선물은 없어요.\n작은 번데기 하나, 이건 당신에게 드리는 깊은 축복입니다: 절망적일 때, 반드시 고치에서 다시 태어나세요."
  },
  Stage_80244_Name = {
    Text = "우정의 번데기"
  },
  Stage_80245_Desc = {
    Text = "불꽃은 빛을 가져오지만, 고통과 피해도 가져옵니다.\n온 세상이 타고 있을 때, 나는 생명을 한 방울의 눈물로 녹여 고통의 바다를 만들겠습니다."
  },
  Stage_80245_Name = {
    Text = "안녕, 불타는 세계여"
  },
  Stage_80246_Desc = {
    Text = "용사는 외롭다. 인간은 그에게 진정으로 다가갈 수 없으며, 용 역시 그를 진정으로 이해할 수 없다.\n도대체 용을 베는 것인가, 아니면 용으로 변하는 것인가, 이것이 문제이다."
  },
  Stage_80246_Name = {
    Text = "고독한 용사"
  },
  Stage_80247_Desc = {
    Text = "나는 세상에 대해 꿈이 가득하고, 꽃이 항상 피어나기를 바라며, 미소가 영원히 존재하기를 희망한다.\n그러나 생명은 나에게 단 하나의 꿈만을 주었다."
  },
  Stage_80247_Name = {
    Text = "나의 많은 꿈들"
  },
  Stage_80248_Desc = {
    Text = "집단은 유동하는 호박이며, 각 영혼은 타인의 빛을 반사하고 투명한 감옥에서 자신의 반영을 봅니다."
  },
  Stage_80248_Name = {
    Text = "사회적 동물"
  },
  Stage_80249_Desc = {
    Text = "나는 나의 친구이자 적이다.\n이 협력과 사투는 한 사람이 남을 때까지 멈추지 않는다."
  },
  Stage_80249_Name = {
    Text = "도플갱어"
  },
  Stage_8024_Desc = {
    Text = "무론 금속의 몸체가 얼마나 무겁더라도, 영혼은 단지 21그램이다."
  },
  Stage_8024_Name = {Text = "21그램"},
  Stage_80250_Desc = {
    Text = "작고 귀여운 나비, 꿈을 지나 현실타래로 날아간다.\n아마도 너무 어리석어도, 나비의 선택은 인간과 다르다."
  },
  Stage_80250_Name = {
    Text = "나비의 비행"
  },
  Stage_80251_Desc = {
    Text = "나에게 보여줘, ‘너’와 ‘나’를 구성하는 어떤 성분과 구조인지."
  },
  Stage_80251_Name = {Text = "눈"},
  Stage_80252_Desc = {
    Text = "오, 친구여, 우리는 모두 꿈을 꿉니다.\n그저 어떤 사람은 꿈을 현실타래로 만들고, 어떤 사람의 현실타래은 꿈처럼 터무니없기만 하죠."
  },
  Stage_80252_Name = {
    Text = "통제할 수 없는 꿈"
  },
  Stage_80253_Desc = {
    Text = "나는 잃어버린 기억 속에서 춤추고 싶다. 나를 사랑하는 사람들과 내가 사랑하는 사람들을 잊고, 오직 나 자신과 영원히 춤추며, 시간의 끝까지 춤추고 싶다."
  },
  Stage_80253_Name = {
    Text = "잃어버린 기억"
  },
  Stage_80254_Desc = {
    Text = "도망쳐, 도망쳐, 강아지야 빨리 도망쳐.\n너의 패닉과 고통스런 무력함으로 우리에게 코미디를 공연해 줘."
  },
  Stage_80254_Name = {Text = "추격"},
  Stage_80255_Desc = {
    Text = "당신을 바라보며, 제가 당신을 바라보고 있습니다.\n매 순간, 언제나, 그저 그렇게 당신을 바라보는 것이죠."
  },
  Stage_80255_Name = {
    Text = "타인의 응시"
  },
  Stage_80256_Desc = {
    Text = "추억은 믿을 수 없는 것이죠, 제가 그 안에서 뒤지면서 시작이 파괴되고 색이 바래져 가니까요. 당신의 형체를 영원히 잠금시키려면 도대체 어떤 방법이 필요할까요?\n만약 추억이 견고하지 않다면, 그럼 생명에 새겨야죠."
  },
  Stage_80256_Name = {
    Text = "닮은 그림자"
  },
  Stage_80257_Desc = {
    Text = "첫 세 발은 전초전이었고,\n마지막 두 발 중 하나로 그의 생명을, 하나로 그의 혼을 빼앗았다."
  },
  Stage_80257_Name = {
    Text = "다섯 발의 총성"
  },
  Stage_80258_Desc = {
    Text = "\"호기심\"이 당신에게 질문을 던졌습니다. 비록 답이 가시로 가득 차 있고, 당신을 태워버릴 것임을 알면서도, 당신은 거부할 수 없습니다.\n결국 당신은\"호기심\"을 거부할 수 없는 고양이입니다."
  },
  Stage_80258_Name = {
    Text = "호기심은 고양이를 죽인다"
  },
  Stage_80259_Desc = {
    Text = "세상은 큰 요양원 같아요. 모든 사람들이 미쳐가고 있거나, 자신의 광기를 숨기고 있어요.\n그래서, 심리 상담을 받으러 오시겠어요?"
  },
  Stage_80259_Name = {
    Text = "상담 초대"
  },
  Stage_8025_Desc = {
    Text = "이곳은 그녀를 위해 만들어진 세계로, 위대한 사랑의 증거이자 공포스러운 감옥이다."
  },
  Stage_8025_Name = {
    Text = "정신병원"
  },
  Stage_80260_Desc = {
    Text = "오, 친구여, 우리는 모두 꿈을 꿉니다.\n그저 어떤 사람은 꿈을 현실타래로 만들고, 어떤 사람의 현실타래은 꿈처럼 터무니없기만 하죠."
  },
  Stage_80260_Name = {
    Text = "통제할 수 없는 꿈"
  },
  Stage_80261_Desc = {
    Text = "나는 잃어버린 기억 속에서 춤추고 싶다. 나를 사랑하는 사람들과 내가 사랑하는 사람들을 잊고, 오직 나 자신과 영원히 춤추며, 시간의 끝까지 춤추고 싶다."
  },
  Stage_80261_Name = {
    Text = "잃어버린 기억"
  },
  Stage_80262_Desc = {
    Text = "도망쳐, 도망쳐, 강아지야 빨리 도망쳐.\n당신의 놀라움과 고통으로, 우리를 위해 한 편의 우스꽝스러운 공연을 보여줘."
  },
  Stage_80262_Name = {Text = "추격"},
  Stage_80263_Desc = {
    Text = "추억은 믿을 수 없는 것이죠, 제가 그 안에서 뒤지면서 시작이 파괴되고 색이 바래져 가니까요. 당신의 형체를 영원히 잠금시키려면 도대체 어떤 방법이 필요할까요?\n만약 추억이 견고하지 않다면, 그럼 생명에 새겨야죠."
  },
