  },
  Stage_80268_Name = {
    Text = "인지 재구성 실타래험"
  },
  Stage_80269_Desc = {
    Text = "나는 세상에 대해 꿈이 가득하고, 꽃이 항상 피어나기를 바라며, 미소가 영원히 존재하기를 희망한다.\n그러나 생명은 나에게 단 하나의 꿈만을 주었다."
  },
  Stage_80269_Name = {
    Text = "나의 많은 꿈들"
  },
  Stage_8026_Desc = {
    Text = "귀족들이 권력을 잃을 때, 부자들이 전재산을 잃을 때 그들은 한없이 무력해진다. 지금의 당신처럼."
  },
  Stage_8026_Name = {
    Text = "광기의 병동"
  },
  Stage_80270_Desc = {
    Text = "나는 나의 친구이자 적이다.\n이 협력과 사투는 한 사람이 남을 때까지 멈추지 않는다."
  },
  Stage_80270_Name = {
    Text = "도플갱어"
  },
  Stage_80271_Desc = {
    Text = "작고 귀여운 나비, 꿈을 지나 현실타래로 날아간다.\n아마도 너무 어리석어도, 나비의 선택은 인간과 다르다."
  },
  Stage_80271_Name = {
    Text = "나비의 비행"
  },
  Stage_8027_Desc = {
    Text = "세상의 싸움은 칼날이 맞부딪히는 전장에만 있는 것이 아니다. 때로는 미치광이의 입에서 시작될 수도 있다."
  },
  Stage_8027_Name = {
    Text = "광인의 입"
  },
  Stage_8028_Desc = {
    Text = "인형의 가느다란 실타래을 자르면, 더 이상 춤추지 못할 것이다."
  },
  Stage_8028_Name = {
    Text = "새들이 없는 밤"
  },
  Stage_8029_Desc = {
    Text = "뒤돌아보지 말라! 얼마나 귀중한 당부인가. 오르페우스의 전철을 밟지 말라."
  },
  Stage_8029_Name = {
    Text = "뒤돌아보지 말라"
  },
  Stage_8030_Desc = {
    Text = "누가 \"봄\"의 의미를 해석할 수 있을까?\n고요한 허공 속에 잠복한 죽음과 망각이, 몽롱한 봄날의 신기루 속으로 스며든다."
  },
  Stage_8030_Name = {
    Text = "보티첼리의 봄"
  },
  Stage_8031_Desc = {
    Text = "일기는 기억의 파편이다. \n조사 중에는 항상 일기가 발견된다."
  },
  Stage_8031_Name = {
    Text = "기억의 파편"
  },
  Stage_8032_Desc = {
    Text = "처음 뵙겠습니다, 주인님."
  },
  Stage_8032_Name = {Text = "육감"},
  Stage_8033_Desc = {
    Text = "그것들은 어둠 속에서 뒤틀리고 융합한 후, 엄숙히 조각상 안에 보관되었다.\n이는 오래 전부터 계획되었던 재회였다."
  },
  Stage_8033_Name = {
    Text = "혈육의 늪지·간격Ⅵ"
  },
  Stage_8034_Desc = {
    Text = "뭇별이 생겨나기 전부터, 그것들은 이미 이곳에 존재했다. 그들은 허무이자, 모든 것이기도 하다."
  },
  Stage_8034_Name = {
    Text = "혼돈 잔상 Ⅲ"
  },
  Stage_8035_Desc = {Text = "랜덤 4"},
  Stage_8035_Name = {
    Text = "달빛 늪의 거울 Ⅳ"
  },
  Stage_8036_Desc = {Text = "랜덤 5"},
  Stage_8036_Name = {
    Text = "달빛 늪의 거울 Ⅴ"
  },
  Stage_8037_Desc = {
    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_8037_Name = {
    Text = "혼돈의 영역·회전 간격Ⅰ"
  },
  Stage_8038_Desc = {Text = "랜덤 1"},
  Stage_8038_Name = {
    Text = "달빛 늪의 거울 Ⅰ"
  },
