  Stage_8040_Name = {
    Text = "혼돈의 영역·회전 간격Ⅰ"
  },
  Stage_8041_Desc = {
    Text = "라모나가 팀으로 돌아왔다. 미사그 조사원의 여정은 계속된다."
  },
  Stage_8041_Name = {
    Text = "어제의 재현"
  },
  Stage_8042_Desc = {
    Text = "황폐한 철교 아래에서 거대하고 비둔한 괴물이 기괴하게 으르렁거린다. 라이 정신병원에 도착하려면 반드시 이곳을 건너야 한다."
  },
  Stage_8042_Name = {
    Text = "궁하면 통한다"
  },
  Stage_8043_Desc = {
    Text = "당신이 알고 싶은 모든 것이 당신의 눈앞에 있지만, 발견하지 못했을 뿐이다."
  },
  Stage_8043_Name = {
    Text = "모자 아래에 숨겨진"
  },
  Stage_8044_Desc = {
    Text = "인생은 마치 나선과도 같아서, 한때 벗어났던 악몽은 늘 자정에 다시 찾아온다."
  },
  Stage_8044_Name = {
    Text = "제자리로 돌아오다"
  },
  Stage_8045_Desc = {
    Text = "라모나와 로탄의 대화 소리 속에서, 수호자는 철창 안의 꿈에 빠져들었다."
  },
  Stage_8045_Name = {
    Text = "긁어 부스럼"
  },
  Stage_8046_Desc = {
    Text = "신은 말한다, 그들이 태어날 때부터 고난을 겪고 피를 흘려야 한다고. \n태양이 떠오르고 비가 떨어져야 함처럼. \n모든 것이 가장 좋은 안배다."
  },
  Stage_8046_Name = {Text = "고우지"},
  Stage_8047_Desc = {
    Text = "로저스 밀랍인형관은 사우스워크 가의 깊은 곳에 자리하고 있으며, 템스 강의 지류와 가깝다. \n전혀 눈에 띄지 않는 곳이지만, 수많은 아방가르드 예술 애호가들이 그 명성을 듣고 찾아온다."
  },
  Stage_8047_Name = {
    Text = "광기의 박물관 Ⅱ"
  },
  Stage_8048_Desc = {
    Text = "그것은 이곳에서 유일한 생명체이며, 그것이 보는 모든 것은 그것의 지배를 받습니다. \n—그것은 최고의 왕입니다."
  },
  Stage_8048_Name = {
    Text = "야수의 왕국"
  },
  Stage_8049_Desc = {
    Text = "그분의 나라는 우주의 껍데기이며, 그분의 욕망은 끝이 없다."
  },
  Stage_8049_Name = {
    Text = "벌레의 소굴 Ⅰ"
  },
  Stage_8050_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8050_Name = {
    Text = "환몽 심잠 Ⅴ"
  },
  Stage_8051_Desc = {
    Text = "무너진 우상은 자신의 백성을 응시한다. \n 그들은 생존하고, 번식하고, 서로 싸우다가, 결국 자신을 완전히 잊는다. \n 무너진 우상은 그 백성을 그리워한다."
  },
  Stage_8051_Name = {
    Text = "환몽 심잠 Ⅱ"
  },
  Stage_8052_Desc = {
    Text = "무너진 우상은 자신의 백성을 응시한다. \n 그들은 생존하고, 번식하고, 서로 싸우다가, 결국 자신을 완전히 잊는다. \n 무너진 우상은 그 백성을 그리워한다."
  },
  Stage_8052_Name = {
    Text = "환몽 심잠 Ⅲ"
  },
  Stage_8053_Desc = {
