  },
  Stage_8060_Name = {
    Text = "폭우가 다가온다"
  },
  Stage_8062_Desc = {
    Text = "우리는 벌레, 뼈 그리고 눈물의 집합입니다. \n오늘 밤 우리는 무수한 무지개가 흐르는 강을 보기 위해 이곳에 모였습니다."
  },
  Stage_8062_Name = {
    Text = "수렵두개 집회"
  },
  Stage_8063_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_8063_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
