  },
  Stage_8095_Name = {
    Text = "초월의 여정·간격Ⅲ"
  },
  Stage_8096_Desc = {
    Text = "그것들은 어둠 속에서 뒤틀리고 융합한 후, 엄숙히 조각상 안에 보관되었다.\n이는 오래 전부터 계획되었던 재회였다."
  },
  Stage_8096_Name = {
    Text = "혼돈의 영역·간격Ⅵ"
  },
  Stage_8097_Desc = {
    Text = "그들은 종잡을 수 없는 마법사처럼 시공간의 틈새를 떠돌아다닌다. 증오도, 두려움도, 연민도 없다."
  },
  Stage_8097_Name = {
    Text = "차원 잔상 Ⅲ"
  },
  Stage_80984_Name = {
    Text = "현혹하는 곤충 체험 스테이지"
  },
  Stage_8098_Desc = {
    Text = "그녀는 몸으로 성스러운 유골을 품고, 교리로 신도들을 이끌며, 독니로 신앙을 퍼뜨렸다.\n그녀의 기도는 멈추지 않고, 그녀의 부름은 그치지 않는다."
  },
  Stage_8098_Name = {
    Text = "신앙의 손아귀 Ⅳ"
  },
  Stage_8099_Desc = {
    Text = "뭇별이 생겨나기 전부터, 그것들은 이미 이곳에 존재했다. 그들은 허무이자, 모든 것이기도 하다."
  },
  Stage_8099_Name = {
    Text = "혼돈 잔상 Ⅱ"
  },
  Stage_8100_Desc = {
    Text = "그들은 바다의 비밀을 말없이 지키며, 영혼은 우주만큼이나 깊다."
  },
  Stage_8100_Name = {
    Text = "해연 잔상 Ⅳ"
  },
  Stage_8101_Desc = {
    Text = "그것들은 어둠 속에서 뒤틀리고 융합한 후, 엄숙히 조각상 안에 보관되었다.\n이는 오래 전부터 계획되었던 재회였다."
  },
