    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_8102_Name = {
    Text = "심해의 유산·회전 간격Ⅰ"
  },
  Stage_8103_Name = {
    Text = "바다의 사도 체험 스테이지"
  },
  Stage_8104_Desc = {
    Text = "로저스 밀랍인형관은 사우스워크 가의 깊은 곳에 자리하고 있으며, 템스 강의 지류와 가깝다. \n전혀 눈에 띄지 않는 곳이지만, 수많은 아방가르드 예술 애호가들이 그 명성을 듣고 찾아온다."
  },
  Stage_8104_Name = {
    Text = "광기의 박물관 Ⅲ"
  },
  Stage_8105_Desc = {
    Text = "어찌 영원히 지지 않는 석양이 있을 수 있겠는가?"
  },
  Stage_8105_Name = {Text = "일몰"},
  Stage_8106_Desc = {
    Text = "예리한 가시가 완벽한 원을 찢었으나, 그것은 ‘케르베로스’의 것이 아니며, 균열 속에서 모습을 드러냈다."
  },
  Stage_8106_Name = {
    Text = "껍질 속 균열"
  },
  Stage_8107_Desc = {
    Text = "무엇이 그녀의 눈을 가렸는가? \n 사랑, 연민, 정의, 아니면 지나친 감사였나?"
  },
  Stage_8107_Name = {Text = "초월"},
  Stage_8108_Desc = {
    Text = "그들은 종잡을 수 없는 마법사처럼 시공간의 틈새를 떠돌아다닌다. 증오도, 두려움도, 연민도 없다."
  },
  Stage_8108_Name = {
    Text = "차원 잔상 Ⅳ"
  },
  Stage_8109_Desc = {
    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_8109_Name = {
    Text = "심해의 유산·회전 간격Ⅰ"
  },
  Stage_8110_Desc = {
    Text = "지옥견 \"케르베로스\"에 관한 소문을 추적하는 과정에서, 미사그 조사원들은 실타래종 사건의 진상을 파헤치기 위해 론디니움 외곽의 작은 마을 '라이'에 도착했다..."
  },
  Stage_8110_Name = {
    Text = "생각하고 행동하라"
  },
  Stage_8111_Desc = {
    Text = "좋은 소식과 나쁜 소식이 있다. 사라진 단서는 다시 나타나지 않겠지만, 새로운 사건들이 암암리에 준비되고 있다. 장담컨대, 조사원들은 빈손으로 돌아가지 않을 것이다."
  },
  Stage_8111_Name = {
    Text = "좋은 소식, 나쁜 소식"
  },
  Stage_8112_Desc = {
    Text = "신비로운 수선화 부인."
  },
  Stage_8112_Name = {
    Text = "안녕하세요, 다포딜 양"
  },
  Stage_8113_Desc = {
    Text = "광기 어린 어조와 강렬한 비린내, 이것이 라이의 환영 방식이다."
  },
  Stage_8113_Name = {
    Text = "라이에 오신 것을 환영합니다"
  },
  Stage_8114_Desc = {
    Text = "인간의 다리는 야생동물의 민첩한 네 발을 이길 수 없지만, 두뇌로는 가능하다. 하지만 \"헬하운드\"를 포획한 후, 일행을 기다리고 있는 것은 무엇일까?"
  },
  Stage_8114_Name = {
    Text = "비장의 카드"
  },
  Stage_8115_Desc = {
    Text = "다포딜이 \"답\"을 가져왔다. 새로운 말이 장기판 위에 오르며, 눈보라의 꿈을 불러왔다."
  },
  Stage_8115_Name = {
    Text = "가시방석"
  },
  Stage_8116_Desc = {
    Text = "즐거운 여정 되시길 바랍니다."
  },
  Stage_8116_Name = {
    Text = "좋은 여행 되세요"
  },
  Stage_8117_Desc = {
    Text = "당신들은 지하철 안에서 정체불명의 암살자에게 습격을 당했다…"
  },
  Stage_8117_Name = {Text = "고독"},
