    Text = "약한 혈육은 눈부신 빛불로 변하고, 그는 돛대 꼭대기에 서서 집을 떠난 수군들에게 나아갈 길을 비추고 있다.\n그녀는 방향을 지적했고, 그는 영원히 방향을 안내할 것이다."
  },
  Stage_81236_Name = {
    Text = "인도하는 빛·하나"
  },
