  Stage_8123_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8123_Name = {
    Text = "환몽 심잠 Ⅶ"
  },
  Stage_81240_Desc = {
    Text = "별의 판은 항해자의 두 눈이며, 그것은 우리가 밤하늘에서 방향을 찾도록 도와준다."
  },
  Stage_81240_Name = {
    Text = "얼룩진 별의 판·광란"
  },
  Stage_81241_Desc = {
    Text = "육분의가 빛나고, 해도가 선명하게 펼쳐지며 우리는 남십자성의 암호를 해독하고 대양의 비밀을 측정합니다……\n조각조각 부서져도, 나는 내 선택을 후회하지 않습니다. 항해사로서의 그 순간부터 내 결말은 이미 결정되었습니다."
  },
  Stage_81241_Name = {
    Text = "최종 추모곡·첫"
  },
