  Stage_81249_Desc = {
    Text = "광학 기기를 통해 정밀하게 조합하여, 사람들은 별들의 각도를 엿볼 수 있게 되었습니다."
  },
  Stage_81249_Name = {
    Text = "구식 육분의·세 번째"
  },
  Stage_8124_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8124_Name = {
    Text = "환몽 심잠 Ⅳ"
  },
  Stage_8125_Desc = {
    Text = "이곳에서 창궐하는 것은 보통 질병이 아니다."
  },
  Stage_8125_Name = {Text = "병"},
  Stage_8126_Desc = {
    Text = "당신은 라모나와 함께 론디니움 동부 지구의 릴리 빈민원으로 향해, 신입 수호자로서의 첫 조사를 시작한다. \n모든 일이 순조로울 것이다... 아마도?"
  },
  Stage_8126_Name = {
    Text = "겉모습에 속지 말라"
  },
  Stage_8127_Desc = {
    Text = "유령은 어두운 곳에 숨어 있다. 지하라든가, 사람의 마음속처럼."
  },
  Stage_8127_Name = {
    Text = "지하의 유령"
  },
  Stage_8128_Desc = {
    Text = "들이마실타래 산소도 없고, 성냥불만큼의 미약한 빛조차 없다. 이곳은 순수한 칠흑의 꿈이다."
  },
  Stage_8128_Name = {Text = "검은 꿈"},
  Stage_8129_Desc = {
    Text = "「각 열쇠에는 고유한 번호가 있으며, 단 한 명의 조사원만이 대응된다.」\n즉, 열쇠 하나가 사라진다는 것은 곧 그 조사원의 죽음을 의미한다.\n멋지지 않은가? 죽음마저 유일무이하다니."
  },
  Stage_8129_Name = {
    Text = "환몽 심잠 Ⅶ"
  },
  Stage_8130_Desc = {
    Text = "「각 열쇠에는 고유한 번호가 있으며, 단 한 명의 조사원만이 대응된다.」\n즉, 열쇠 하나가 사라진다는 것은 곧 그 조사원의 죽음을 의미한다.\n멋지지 않은가? 죽음마저 유일무이하다니."
