  },
  Stage_8135_Desc = {
    Text = "「각 열쇠에는 고유한 번호가 있으며, 단 한 명의 조사원만이 대응된다.」\n즉, 열쇠 하나가 사라진다는 것은 곧 그 조사원의 죽음을 의미한다.\n멋지지 않은가? 죽음마저 유일무이하다니."
  },
  Stage_8135_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
  Stage_8137_Desc = {
    Text = "그녀는 꿈과 현실타래이 교차하는 경계이며, 밤하늘을 바라보는 각 영혼의 깊은 내면의 반사입니다."
  },
  Stage_8137_Name = {
    Text = "뒤틀린 별들"
  },
  Stage_8138_Desc = {
    Text = "투박하고, 미처 소화되지 못한 물질 무더기. 사람들은 그것을 배설물, 혹은 혼돈이라고 부른다.\n세계는 배설물에서 탄생했다."
  },
  Stage_8138_Name = {
    Text = "혼돈 군집 Ⅱ"
  },
  Stage_8139_Desc = {
    Text = "꿈틀거리고, 흘러내린다... 족쇄의 틈새로 원생질 종양이 빠져나가고 있다.\n이것은 그녀가 '자유'를 위해 치른 대가이다."
  },
  Stage_8139_Name = {
    Text = "칠흑의 사슬 Ⅳ"
  },
  Stage_8140_Desc = {
    Text = "그것들은 어둠 속에서 뒤틀리고 융합한 후, 엄숙히 조각상 안에 보관되었다.\n이는 오래 전부터 계획되었던 재회였다."
  },
  Stage_8140_Name = {
    Text = "혼돈의 영역·간격Ⅴ"
  },
  Stage_8141_Desc = {
    Text = "여기 오래된 도시의 폐허가 잠들어 있다.\n그곳은 그 주인만큼이나 깊은 잠에 빠져 있다."
  },
  Stage_8141_Name = {
    Text = "포나페의 폐허 Ⅲ"
  },
  Stage_8142_Desc = {
    Text = "무엇이 그녀의 눈을 가렸는가? \n 사랑, 연민, 정의, 아니면 지나친 감사였나?"
  },
  Stage_8142_Name = {Text = "초월"},
  Stage_8143_Desc = {
    Text = "예리한 가시가 완벽한 원을 찢었으나, 그것은 ‘케르베로스’의 것이 아니며, 균열 속에서 모습을 드러냈다."
  },
  Stage_8143_Name = {
    Text = "껍질 속 균열"
  },
  Stage_8144_Desc = {
    Text = "어찌 영원히 지지 않는 석양이 있을 수 있겠는가?"
  },
  Stage_8144_Name = {Text = "일몰"},
  Stage_8145_Desc = {
    Text = "「손」은 밤의 장막을 열고, 소리 없이 이 세상에 도착했다."
  },
  Stage_8145_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
  Stage_8146_Desc = {
    Text = "정체불명의 조각상이 어둠 속을 떠돌아다니며 떨고 있다.\n그들은 오래된 리듬에 맞춰, 먼 곳에서 들려오는 피리 소리를 따라 춤을 추었다."
  },
  Stage_8146_Name = {
    Text = "심해의 유산·간격Ⅱ"
  },
  Stage_8147_Desc = {
    Text = "철벅철벅, 갈라졌네. 철벅철벅, 부러졌네."
  },
  Stage_8147_Name = {
    Text = "인형의 집"
  },
  Stage_8148_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_8148_Name = {
    Text = "혼돈의 영역·회전 간격Ⅳ"
  },
  Stage_8149_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_8149_Name = {
    Text = "혼돈의 영역·회전 간격Ⅳ"
  },
  Stage_8150_Desc = {
    Text = "「문」은 열렸고, 환상이 곧 깨어날 것이다.\n쉿... 자세히 보지도 말고 듣지도 마라."
  },
  Stage_8150_Name = {
    Text = "혼돈의 영역·회전 간격Ⅳ"
  },
  Stage_8151_Desc = {
    Text = "데자뷰와 현실타래이 수호자를 두 부분으로 찢어버리고 있다. 하나는 기억에, 다른 하나는 눈앞에 남겨두고 있다."
  },
  Stage_8151_Name = {Text = "단검"},
  Stage_8152_Desc = {
    Text = "밤의 항구, 친절한 주민들, 따뜻한 환대."
  },
  Stage_8152_Name = {Text = "매복"},
  Stage_8153_Desc = {
    Text = "진부한 시작: 기억을 잃은 수호자가 혼자 남겨져 있다. \n다른 점은, 이번에는 외로운 바다 위에서 깨어났다."
  },
  Stage_8153_Name = {
    Text = "폭풍의 눈"
  },
  Stage_8154_Desc = {
    Text = "여러 바다를 건너는 해의 사도."
  },
  Stage_8154_Name = {Text = "사도"},
  Stage_8155_Desc = {
    Text = "배에서 선장 외에 누구를 믿을 수 있을까?"
  },
  Stage_8155_Name = {Text = "선원"},
  Stage_8156_Desc = {
    Text = "후퇴할 곳이 없을 때, 훈련된 파트너가 주로 상황을 해결하는 열쇠가 된다는 것을 — 라몬나는 다시 한 번 당신에게 이 점을 가르쳐주었다."
  },
  Stage_8156_Name = {
    Text = "막다른 길"
  },
  Stage_8157_Desc = {
    Text = "각 바다를 밟고 지나가는 것은 적뿐만 아니라 희망의 약한 빛일 수도 있다."
  },
  Stage_8157_Name = {
    Text = "침몰한 자"
  },
  Stage_8158_Desc = {
    Text = "그것은 바다를 갈라놓으려는 의도를 가진 이의 거대한 검이며, 모든 바다를 평평하게 만들려는 의도를 지닌 이의 야심입니다."
  },
  Stage_8158_Name = {
    Text = "광신도의 거대한 칼"
  },
  Stage_8159_Desc = {
    Text = "그것은 그녀가 사라지지 않는 악몽이자, 그녀의 인생을 괴롭힌 왜곡된 현실타래이었습니다."
  },
  Stage_8159_Name = {
    Text = "왜곡된 현실타래"
  },
  Stage_8160_Desc = {
    Text = "그것들은 어둠 속에서 뒤틀리고 융합한 후, 엄숙히 조각상 안에 보관되었다.\n이는 오래 전부터 계획되었던 재회였다."
  },
  Stage_8160_Name = {
    Text = "초월의 여정·간격Ⅴ"
  },
  Stage_8161_Desc = {
    Text = "론디니움은 찬란한 산업 문명과 도시를 뒤덮은 회색 안개로 유명하다. \n안개는 어디에나 있으며, 지나가는 사람들에게는 그저 우연적이고 무의미한 불편함 정도에 불과하다."
  },
  Stage_8161_Name = {
    Text = "안개의 도시 Ⅳ"
  },
  Stage_8162_Desc = {
    Text = "우주 깊은 곳에 숨어 있는 구부러진 경계.\n당신을 한 어둠에서 또 다른 어둠으로 이끌 수 있다."
  },
  Stage_8162_Name = {
    Text = "블랙홀의 목구멍 Ⅳ"
  },
  Stage_8163_Desc = {
    Text = "허무는 우리의 근원이자 종착지다."
  },
  Stage_8163_Name = {
    Text = "불멸의 속삭임"
  },
  Stage_8164_Desc = {
    Text = "황폐한 철교 아래에서 거대하고 비둔한 괴물이 기괴하게 으르렁거린다. 라이 정신병원에 도착하려면 반드시 이곳을 건너야 한다."
  },
  Stage_8164_Name = {
    Text = "궁하면 통한다"
  },
  Stage_8165_Desc = {
    Text = "카다스의 극점에 위치한 엘워스는 일년 내내 녹지 않는 얼음과 눈으로 덮여 있고, \n두껍고 단단한 빙하 아래에는 생명의 맥동이 어렴풋이 느껴진다."
  },
  Stage_8165_Name = {
    Text = "무질서한 산맥 Ⅰ"
  },
  Stage_8166_Desc = {
    Text = "정체불명의 조각상이 어둠 속을 떠돌아다니며 떨고 있다.\n그들은 오래된 리듬에 맞춰, 먼 곳에서 들려오는 피리 소리를 따라 춤을 추었다."
  },
  Stage_8166_Name = {
    Text = "혼돈의 영역·간격Ⅷ"
  },
  Stage_8167_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_8167_Name = {
    Text = "환몽 심잠 Ⅳ"
  },
  Stage_8168_Desc = {
    Text = "곧 「문」이 열리고, 그 안에서 진리의 일부를 엿볼 수 있을 것이다.\n그것은 검은색도. 흰색도 아니다—진리는 온갖 빛깔이자, 동시에 혼탁하다."
  },
  Stage_8168_Name = {
    Text = "혈육의 늪지·간격Ⅲ"
  },
  Stage_8169_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_8169_Name = {
    Text = "환몽 심잠 Ⅵ"
  },
  Stage_8170_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_8170_Name = {
    Text = "환몽 심잠 Ⅶ"
  },
  Stage_8171_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_8171_Name = {
    Text = "환몽 심잠 Ⅰ"
  },
  Stage_8172_Desc = {
    Text = "「그것은 유일하고, 전부이며, 진실타래의 문을 여는 희망이다. 」\n수많은 열쇠가 원을 이루며 둘러싸고 있다. 그것들은 하늘에서 떨어져 사람들에게 무거운 희망을 안겨주었고, 동시에 무거운 무덤을 가져왔다."
  },
  Stage_8172_Name = {
    Text = "환몽 심잠 Ⅱ"
  },
  Stage_8173_Desc = {
    Text = "정체불명의 조각상이 어둠 속을 떠돌아다니며 떨고 있다.\n그들은 오래된 리듬에 맞춰, 먼 곳에서 들려오는 피리 소리를 따라 춤을 추었다."
  },
  Stage_8173_Name = {
    Text = "초월의 여정·간격Ⅱ"
  },
  Stage_8174_Desc = {
    Text = "그는 그분이 될 수 없고, 그분은 절대 그가 될 수 없다. \n맞아…… 맞아, 오직 나의 신성만이 진정한 그이다."
  },
  Stage_8174_Name = {
    Text = "잃어버린 빛"
  },
  Stage_81757_Desc = {
    Text = "찬란한 신국이 당신의 찢어진 눈 속에 서서히 드러납니다.\n거기에서 당신은 약속을 얻고 모든 것을 소유하게 될 것입니다."
  },
  Stage_81757_Name = {
    Text = "신국의 속삭임"
  },
  Stage_81758_Desc = {
    Text = "상아 조각상을 통해, 그의 시선이 지상을 내리쬡니다.\n그로 인해, 당신과 나는 모두 그의 의지에 빠져듭니다."
  },
  Stage_81758_Name = {
    Text = "성상의 주시"
  },
  Stage_81759_Desc = {
    Text = "무한한 우주가 당신의 몸속에 모이고, 마치 별들이 정위의 순간을 향해 나아가는 것처럼.\n이 허공에서 오는 소환에 응답하세요! 그의 자식. 그의 꼭두각시."
  },
  Stage_81759_Name = {
    Text = "공허의 소환"
  },
  Stage_8175_Desc = {
    Text = "현실타래은 화근을 심었으나, 운명은 만남을 이끌었다."
  },
  Stage_8175_Name = {
    Text = "운명의 씨앗"
  },
  Stage_81760_Desc = {
    Text = "환상과 현실타래의 틈새에서, 제례는 이미 시작되었습니다.\n환호하라, 외쳐라, 당신의 기쁨과 고통은 차원을 넘어 신국 강림의 찬송곡이 될 것입니다."
  },
  Stage_81760_Name = {
    Text = "제례의 응답"
  },
  Stage_81761_Desc = {
    Text = "모든 광란은 지나갔습니다.\n당신은 분열된 몸을 끌고 나와, 촉수를 뻗어 세상에 깨어남 후 첫 번째 공포와 모독의 외침을 내지릅니다.\n\n「신국은 반드시 강림할 것입니다.」"
  },
  Stage_81761_Name = {
    Text = "신실타래한 귀의"
  },
  Stage_81762_Desc = {
    Text = "아, 이 혼돈의 소리를 들어봐, 이 끝없는 환상의 음악을 들어봐.\n신은 성유를 내렸고, 너는 그의 자식이자 인형으로서, 충실타래히 수행할 것이다."
  },
  Stage_81762_Name = {
    Text = "신왕의 선언"
  },
  Stage_81763_Desc = {
    Text = "가속되는 심장은 혈육의 떨림의 전조일 뿐입니다.\n당황할 필요 없어요, 그것은 당신의 혈통이 깨어남하는 소리입니다."
  },
  Stage_81763_Name = {
    Text = "육신의 떨림"
  },
  Stage_8176_Desc = {
    Text = "두 번째 심장이 머피의 몸에서 뛰고 있어, 「탄생 의식」을 막아야 한다."
  },
  Stage_8176_Name = {
    Text = "또 다른 기적"
  },
  Stage_8177_Desc = {
    Text = "돌파구를 찾는 것은 언제나 단순하지 않다, 하지만 다행히도 이번에는 수호자가 가장 밝은 항성을 찾았습니다."
  },
  Stage_8177_Name = {
    Text = "추적하는 별빛"
  },
  Stage_81781_Desc = {
    Text = "보이지 않는 재앙이 부활하여, 물리적 세계의 역사와 존재를 심연으로 끌어내린다."
  },
  Stage_81781_Name = {
    Text = "융재 금지 구역·제3파·매드니스"
  },
  Stage_81782_Desc = {
    Text = "보이지 않는 재앙이 부활하여, 물리적 세계의 역사와 존재를 심연으로 끌어내린다."
  },
