  Stage_83250_Name = {
    Text = "융재 금지 구역·4번째 파도·일반"
  },
  Stage_88880_Desc = {
    Text = "나는 당신이 불러온 불꽃을 가지고 있다.\n당신이 나를 인도했으니, 나는 당신의 눈이 되어 당신을 다시 빛으로 인도하겠다.\n당신이 걸어갔던 길을 나는 대신 걸어가며, 모든 녹슨 울타리는 이 불 앞에서 무너질 것이다."
  },
  Stage_88880_Name = {
    Text = "전등자·셋째"
  },
  Stage_88881_Desc = {
    Text = "굳게 동결된 도시, 한 문명의 표본이 잠금되어 있습니다."
  },
  Stage_88881_Name = {Text = "표본"},
  Stage_88882_Desc = {
    Text = "그는 태어나길 어리석고 둔감하며, 단순한 삶에 갇혀 맹목적이고 고집이 세다.\n그러나 누가 어리석은 자가 새로운 길을 개척할 수 없다고 했는가? 모든 억압은 태어나지 않은 폭풍에 불과하다; 비록 그가 아무것도 모른다 해도, 여전히 두 날개로 두려움 없이 미지의 하늘을 향해 날아갈 것이다."
  },
  Stage_88882_Name = {
    Text = "우매자·광란"
  },
  Stage_88883_Desc = {
    Text = "나는 먼 옛날의 꿈을 꾸었다.\n그때 당신은 책 속에서 푸른 벨벳 천에 흩뿌려진 깊은 별들을 가리키며, 나중에 맑은 밤을 선택하여 함께 달 옆에서 날아 하늘 위에 어떤 광경이 있는지 보자고 말했다."
  },
  Stage_88883_Name = {
    Text = "어제의 꿈·여섯 번째"
  },
  Stage_88884_Desc = {
    Text = "그는 항상 두 개의 그림자를 가지고 있었지만, 이제 하나를 잃었습니다.\n 그는 외로운 밤하늘 아래 홀로 걸으며, 어린 시절 그와 함께 지은 노래를 부릅니다.\n 날아가는 새야, 새야, 너는 어디에……\n 그림자야, 그림자야, 빨리 집으로 돌아와……"
  },
  Stage_88884_Name = {
    Text = "외로운 여행·5"
  },
  Stage_88885_Desc = {
    Text = "나는 당신이 불러온 불꽃을 가지고 있다.\n당신이 나를 인도했으니, 나는 당신의 눈이 되어 당신을 다시 빛으로 인도하겠다.\n당신이 걸어갔던 길을 나는 대신 걸어가며, 모든 녹슨 울타리는 이 불 앞에서 무너질 것이다."
  },
  Stage_88885_Name = {
    Text = "전등자·넷째"
