    Text = "그 모래는 바다와 같고, 바람이 멈추면 파도는 잔잔해진다; 바람이 일면 생명이 사라진다.\n그는 끝없는 모래 바다에서 해양 제비처럼 굴하지 않고 날아다닌다."
  },
  Stage_88913_Name = {
    Text = "끝없는 모래·네 번째"
  },
  Stage_88914_Desc = {
    Text = "그가 눈을 뜨자, 그 눈은 다시는 닫힐 수 없었습니다.\n 그가 하늘을 보았을 때, 그 하늘은 항상 그의 마음 속에 있었습니다.\n 그 자유가 죽음을 요구한다면, 그는 주저하지 않고 자신의 생명을 바칠 것입니다."
  },
  Stage_88914_Name = {
    Text = "자유와 죽음·다섯째"
  },
  Stage_88915_Desc = {
    Text = "그 모래는 바다와 같고, 바람이 멈추면 파도는 잔잔해진다; 바람이 일면 생명이 사라진다.\n그는 끝없는 모래 바다에서 해양 제비처럼 굴하지 않고 날아다닌다."
  },
  Stage_88915_Name = {
    Text = "끝없는 모래·다섯 번째"
  },
  Stage_88916_Desc = {
    Text = "그가 눈을 뜨자, 그 눈은 다시는 닫힐 수 없었습니다.\n 그가 하늘을 보았을 때, 그 하늘은 항상 그의 마음 속에 있었습니다.\n 그 자유가 죽음을 요구한다면, 그는 주저하지 않고 자신의 생명을 바칠 것입니다."
  },
  Stage_88916_Name = {
    Text = "자유와 죽음·첫째"
  },
  Stage_88917_Desc = {
    Text = "그는 항상 두 개의 그림자를 가지고 있었지만, 이제 하나를 잃었습니다.\n 그는 외로운 밤하늘 아래 홀로 걸으며, 어린 시절 그와 함께 지은 노래를 부릅니다.\n 날아가는 새야, 새야, 너는 어디에……\n 그림자야, 그림자야, 빨리 집으로 돌아와……"
  },
  Stage_88917_Name = {
    Text = "고독의 여행·4"
  },
  Stage_88918_Desc = {
    Text = "우리의 태생이 감옥 속에서 태어났다면, 그 필연적으로 속박을 받아야 할까요?\n만약 깊은 땅에 묻혀 있다면, 반드시 땅 속에서 다시 태어나야죠."
  },
  Stage_88918_Name = {
    Text = "감금된 감옥·네 번째"
  },
  Stage_88919_Desc = {
    Text = "그는 태어나길 어리석고 둔감하며, 단순한 삶에 갇혀 맹목적이고 고집이 세다.\n그러나 누가 어리석은 자가 새로운 길을 개척할 수 없다고 했는가? 모든 억압은 태어나지 않은 폭풍에 불과하다; 비록 그가 아무것도 모른다 해도, 여전히 두 날개로 두려움 없이 미지의 하늘을 향해 날아갈 것이다."
  },
  Stage_88919_Name = {
    Text = "우매자·여섯"
  },
  Stage_88920_Desc = {
    Text = "그 모래는 바다와 같고, 바람이 멈추면 파도는 잔잔해진다; 바람이 일면 생명이 사라진다.\n그는 끝없는 모래 바다에서 해양 제비처럼 굴하지 않고 날아다닌다."
  },
