  },
  Stage_88923_Name = {
    Text = "우매자·셋"
  },
  Stage_88924_Desc = {
    Text = "사막의 구성은: 뜨거움, 건조함, 바람과 모래, 끝없이 이어지는 모래언덕, 민첩한 파충류, 선인장, 그리고 피부가 꿀처럼 닳은 미인 한 명입니다."
  },
  Stage_88924_Name = {
    Text = "모래와 꿀"
  },
  Stage_88925_Desc = {
    Text = "나는 당신이 불러온 불꽃을 가지고 있다.\n당신이 나를 인도했으니, 나는 당신의 눈이 되어 당신을 다시 빛으로 인도하겠다.\n당신이 걸어갔던 길을 나는 대신 걸어가며, 모든 녹슨 울타리는 이 불 앞에서 무너질 것이다."
  },
  Stage_88925_Name = {
    Text = "전등자·광란"
