  Stage_88932_Desc = {
    Text = "그는 태어나길 어리석고 둔감하며, 단순한 삶에 갇혀 맹목적이고 고집이 세다.\n그러나 누가 어리석은 자가 새로운 길을 개척할 수 없다고 했는가? 모든 억압은 태어나지 않은 폭풍에 불과하다; 비록 그가 아무것도 모른다 해도, 여전히 두 날개로 두려움 없이 미지의 하늘을 향해 날아갈 것이다."
  },
  Stage_88932_Name = {
    Text = "우매자·다섯"
  },
  Stage_89731_Desc = {
    Text = "그 천천히 떨어지는 눈물은 순수한 얼음 꽃처럼 맑다."
  },
  Stage_89731_Name = {
    Text = "한 방울의 눈물"
  },
  Stage_89732_Desc = {
    Text = "달리기, 숨기, 추적, 잡아당기기, 사냥꾼은 이미 검은 총구를 들었다."
  },
  Stage_89732_Name = {
    Text = "집단 사냥"
  },
  Stage_90490_Desc = {
    Text = "혼돈 속에서 탄생한 깨어남체가 당신 곁에 섰습니다. 당신의 은열쇠가 흥분에 찬 떨림을 울립니다.\n그들과 함께 싸우며, 은열쇠의 잠재력을 이끌어내는 방법을 익히세요."
  },
  Stage_90490_Name = {
    Text = "혼돈의 의념"
  },
  Stage_90662_Desc = {
    Text = "묘원의 종소리가 울리면, 퍼지는 검은 안개는 꿈속에서 사라질 것이다.\n무거운 관을 열어라, 그 웅장한 왕국이 너의 앞에 내리게 될 것이다."
  },
  Stage_90662_Name = {
    Text = "꿈의 저편"
  },
  Stage_90663_Desc = {
    Text = "들어라, 이 바다의 비통한 울음소리.\n신자들은 정성을 다해 간청한다. 주님께 그들의 기도를 응답해 달라고, 주께서 그들의 핏빛에 은총을 내리시길."
  },
  Stage_90663_Name = {
    Text = "피의 제사"
  },
  Stage_90664_Desc = {
    Text = "「이곳에 깊은 잠들어 있는 시체들, 밤하늘을 떠도는 영혼들이여——\n식인귀의 왕, 매장 도시의 주님의 이름으로, 당신들을 초대합니다. 당신들이 그리워하던 땅으로 돌아오세요. \n당신들을 초대하여 적이 주는 만족을 함께 누리도록 하겠습니다！」"
  },
  Stage_90664_Name = {
    Text = "만령의 춤"
  },
  Stage_90665_Desc = {
    Text = "지극한 충성의 맹세보다 훨씬 이전에, 서로의 곁을 영원히 지키겠다는 약속이 있었다."
  },
  Stage_90665_Name = {Text = "서약"},
  Stage_90666_Desc = {
    Text = "죄악? 음모? 죽음?\n화가는 그런 것에 관심이 없다. 그의 눈에는 시체들로 구성된 장대한 풍경만이 있다."
  },
  Stage_90666_Name = {Text = "화가"},
  Stage_90667_Desc = {
    Text = "지극한 충성의 맹세보다 훨씬 이전에, 서로의 곁을 영원히 지키겠다는 약속이 있었다."
  },
  Stage_90667_Name = {Text = "서약"},
  Stage_90670_Desc = {
    Text = "장신의 성격 중에서, 음식에 대한 취향이 가장 중요한 요소였다."
  },
  Stage_90670_Name = {
    Text = "망자의 요리법"
  },
  Stage_90671_Desc = {
    Text = "혈연의 기억. 한 도시 국가 왕실타래의 이야기. 무겁고 장엄한 역사.\n한 평범한 평민의 기억. 평범한 가문의 이야기. 필요 없는 주석.\n매장된 도시의 왕에게는 그들이 아무런 차이도 없어야 하고, 또한 그렇지 않을 것입니다."
  },
  Stage_90671_Name = {
    Text = "하찮은 주석"
  },
  Stage_90672_Desc = {
    Text = "「현악기는 이미 중천으로 올라갔고, 모든 번잡한 의식은 안개 속에서 사라졌다. \n내 사랑하는 신민들, 환호하라. 깃발을 찢고 신의 뭇 위선을 드러내라. \n오늘 밤, 시인의 목소리가 우리를 위해 노래할 것이다. \n오늘 밤, 어머니의 두 팔이 우리를 품어줄 것이다.」"
  },
  Stage_90672_Name = {
    Text = "달빛, 해골과 춤을"
  },
  Stage_90674_Desc = {
    Text = "그는 매장된 도시의 군주다. 그는 이 연회의 주인이다.\n그는 모든 손님을 두 팔을 벌려 맞이하며, 그들을 무도회장에서 떠나도록 초대한다.\n무덤 속의 시체들 사이에서 그는 심연과 함께 춤춘다."
  },
  Stage_90674_Name = {
    Text = "유해의 군주"
  },
  Stage_90676_Desc = {
    Text = "묘원의 종소리가 울리면, 퍼지는 검은 안개는 꿈속에서 사라질 것이다.\n무거운 관을 열어라, 그 웅장한 왕국이 너의 앞에 내리게 될 것이다."
  },
  Stage_90676_Name = {
    Text = "꿈의 저편"
  },
  Stage_90679_Desc = {
    Text = "장신의 성격 중에서, 음식에 대한 취향이 가장 중요한 요소였다."
  },
  Stage_90679_Name = {
    Text = "망자의 요리법"
  },
  Stage_90680_Desc = {
    Text = "꿈 안의 소리, 잊힌 문명, 오래된 친구의 흔적…\n너는 알고 싶어하는 모든 것이 먼 바다에서 너를 기다리고 있다."
  },
  Stage_90680_Name = {
    Text = "먼바다 위에서"
  },
  Stage_90681_Desc = {
    Text = "들어라, 이 바다의 비통한 울음소리.\n신자들은 정성을 다해 간청한다. 주님께 그들의 기도를 응답해 달라고, 주께서 그들의 핏빛에 은총을 내리시길."
  },
  Stage_90681_Name = {
    Text = "피의 제사"
  },
  Stage_90684_Desc = {
    Text = "눈앞의 이 노쇠한 시체의 괴물은 누구인가? 그는 왜 옷이 너덜너덜한가? 왜 그는 눈물을 흘리고 있는가?\n그는 왜 슬프게 울면서 가장 부드럽고 가장 쉰 목소리로 ‘엘레나’라는 이름을 부르는가?\n그녀는 아무것도 기억하지 못한다.\n달빛이 그녀의 시체 위에 떨어져, 결혼식 날처럼 아름답고 그녀의 몸 위에서 바람에 흩날리는 면사포처럼."
  },
  Stage_90684_Name = {
    Text = "웨딩드레스와 장례식"
  },
  Stage_90685_Desc = {
    Text = "눈앞의 이 노쇠한 시체의 괴물은 누구인가? 그는 왜 옷이 너덜너덜한가? 왜 그는 눈물을 흘리고 있는가?\n그는 왜 슬프게 울면서 가장 부드럽고 가장 쉰 목소리로 ‘엘레나’라는 이름을 부르는가?\n그녀는 아무것도 기억하지 못한다.\n달빛이 그녀의 시체 위에 떨어져, 결혼식 날처럼 아름답고 그녀의 몸 위에서 바람에 흩날리는 면사포처럼."
  },
  Stage_90685_Name = {
    Text = "웨딩드레스와 장례식"
  },
  Stage_90686_Desc = {
    Text = "혈연의 기억. 한 도시 국가 왕실타래의 이야기. 무겁고 장엄한 역사.\n한 평범한 평민의 기억. 평범한 가문의 이야기. 필요 없는 주석.\n매장된 도시의 왕에게는 그들이 아무런 차이도 없어야 하고, 또한 그렇지 않을 것입니다."
  },
  Stage_90686_Name = {
    Text = "하찮은 주석"
  },
  Stage_90687_Desc = {
    Text = "그는 매장된 도시의 군주다. 그는 이 연회의 주인이다.\n그는 모든 손님을 두 팔을 벌려 맞이하며, 그들을 무도회장에서 떠나도록 초대한다.\n무덤 속의 시체들 사이에서 그는 심연과 함께 춤춘다."
  },
  Stage_90687_Name = {
    Text = "유해의 군주"
  },
  Stage_90689_Desc = {
    Text = "죄악? 음모? 죽음?\n화가는 그런 것에 관심이 없다. 그의 눈에는 시체들로 구성된 장대한 풍경만이 있다."
  },
  Stage_90689_Name = {Text = "화가"},
  Stage_90690_Desc = {
    Text = "「이곳에 깊은 잠들어 있는 시체들, 밤하늘을 떠도는 영혼들이여——\n식인귀의 왕, 매장 도시의 주님의 이름으로, 당신들을 초대합니다. 당신들이 그리워하던 땅으로 돌아오세요. \n당신들을 초대하여 적이 주는 만족을 함께 누리도록 하겠습니다！」"
  },
  Stage_90690_Name = {
    Text = "만령의 춤"
  },
  Stage_90691_Desc = {
    Text = "「현악기는 이미 중천으로 올라갔고, 모든 번잡한 의식은 안개 속에서 사라졌다. \n내 사랑하는 신민들, 환호하라. 깃발을 찢고 신의 뭇 위선을 드러내라. \n오늘 밤, 시인의 목소리가 우리를 위해 노래할 것이다. \n오늘 밤, 어머니의 두 팔이 우리를 품어줄 것이다.」"
  },
  Stage_90691_Name = {
    Text = "달빛, 해골과 춤을"
  },
  Stage_90985_Desc = {
    Text = "모든 저항자는 두려움에 기어 다니고, 모든 빛은 로마로 돌아온다.\n그 순백의 화관과 월계수는 가장 용감한 전사에게 씌워질 것이다."
  },
  Stage_90985_Name = {
    Text = "용사의 월계관·다섯"
  },
  Stage_90986_Desc = {
    Text = "환호성과 꽃, 술과 연회, 금과 보물들.\n즐겨라, 크게 웃어라, 이는 전사가 누려야 할 영광이다!"
  },
  Stage_90986_Name = {
    Text = "영광의 귀환·제5편"
  },
  Stage_90987_Desc = {
    Text = "모든 저항자는 두려움에 기어 다니고, 모든 빛은 로마로 돌아온다.\n그 순백의 화관과 월계수는 가장 용감한 전사에게 씌워질 것이다."
  },
  Stage_90987_Name = {
    Text = "용사의 월계관·둘"
  },
  Stage_90988_Desc = {
    Text = "사냥감이 어디에 숨든, 전문 사냥꾼은 그 달콤한 향기를 맡을 것이다."
  },
  Stage_90988_Name = {
    Text = "사나운 사냥꾼·광란"
  },
  Stage_90989_Desc = {
    Text = "정복의 나팔이 울려 퍼지며, 전사들은 이미 여정을 시작했다.\n우리는 전진하고, 저항할 수 없으며, 반드시 승리할 것이다."
  },
  Stage_90989_Name = {
    Text = "원정 나팔·두 번째"
  },
  Stage_90990_Desc = {
    Text = "정복의 나팔이 울려 퍼지며, 전사들은 이미 여정을 시작했다.\n우리는 전진하고, 저항할 수 없으며, 반드시 승리할 것이다."
  },
  Stage_90990_Name = {
    Text = "원정 나팔·네 번째"
  },
  Stage_90991_Desc = {
    Text = "우리가 과거에 약간의 불화가 있었던 건 인정하지만, 그것은 우리가 잠시 이 끔찍하고, 증오스러운, 비열한 현대 기술을 향해 화살을 겨냥하는 것을 방해하지는 않는다."
  },
