  },
  Stage_91018_Name = {
    Text = "용사의 월계관·여섯"
  },
  Stage_91019_Desc = {
    Text = "환호성과 꽃, 술과 연회, 금과 보물들.\n즐겨라, 크게 웃어라, 이는 전사가 누려야 할 영광이다!"
  },
  Stage_91019_Name = {
    Text = "영광의 귀환·제6편"
  },
  Stage_91088_Desc = {
    Text = "그들은 주인과 하인, 범죄자와 희생자, 같은 폐허의 유물이다.\n혈맥의 갈증을 따라 그들은 같은 문 앞에서 우연히 마주쳤다."
  },
  Stage_91088_Name = {
    Text = "노예와 주인"
  },
  Stage_91091_Desc = {
    Text = "누가 옛 영광이 돌아올 수 없다고 말했나요?\n보세요, 그 지긋지긋한 현대 과학이여, 로마의 힘은 결국 모든 것을 정복할 것입니다!"
  },
  Stage_91091_Name = {
    Text = "로마의 힘"
  },
  Stage_94464_Desc = {
    Text = "심해에서 온 깨어남체가 해저에 잠든 위대한 힘을 지니고 당신 앞에 나타났습니다.\n그들과 함께 싸우며, 촉완의 힘을 사용하는 방법을 익히세요."
  },
  Stage_94464_Name = {
    Text = "심해의 촉수"
  },
  Stage_94465_Desc = {
    Text = "혈육은 생명의 시초이자 생명의 종말입니다. 죽음이 곧 삶이며, 순수한 혈육으로 구축된 깨어남체들은 이를 가장 잘 알고 있습니다.\n그들과 함께 싸우며, 혈육의 힘을 다루는 방법을 익히세요."
  },
  Stage_94465_Name = {
    Text = "혈육의 증식"
  },
  Stage_94466_Desc = {
    Text = "초차원을 관통하는 깨어남체들도 이 공간의 비밀을 완전히 이해하지는 못합니다. 그 비밀을 풀어내는 날, 당신은 경이로운 힘을 엿보게 될 것입니다.\n그들과 함께 싸우며, 초차원 공간을 활용한 전투 방법을 익히세요."
  },
  Stage_94466_Name = {
    Text = "초차원 영역"
  },
  Stage_94806_Desc = {
    Text = "아름다운 휴일을 무례함과 폭력으로 망칠 수는 없지. 싸우려면, 배구장에서 승부를 가리자!"
  },
  Stage_94806_Name = {
    Text = "문명 결투"
  },
  Stage_94808_Desc = {
    Text = "챔피언이라면, 작은 특권 정도는 있어야 하는 법이지."
  },
  Stage_94808_Name = {
    Text = "챔피언과 대난투"
  },
  Stage_94811_Desc = {
    Text = "1등을 차지할 사람이, 같은 곳에서 두 번이나 넘어질 리가 없어!"
  },
  Stage_94811_Name = {
    Text = "결승의 한 공"
  },
  Stage_94817_Desc = {
    Text = "사람들은 규칙으로 피할 수 없는 엔트로피 증가를 통제하려 한다. 사실타래 모든 사람에게는 자신만의 원칙이 있지만, 수십 개의 원칙이 충돌하면 최종 원칙은 결국——원칙 따윈 없다!"
  },
  Stage_94817_Name = {
    Text = "매칭 원칙"
  },
  Stage_94824_Desc = {
    Text = "고요한 밤, 부드러운 해풍, 별들의 온화한 빛 아래에서는 언제나 비밀스러운 마음을 털어놓기에 적합하다."
  },
  Stage_94824_Name = {
    Text = "밤바람만이 아는 것"
  },
  Stage_94832_Desc = {
    Text = "그녀의 마음속에는 분명히 알고 있었다: 홀로의 용기만으로는 무적의 승리를 얻을 수 없다는 것을. 과거에도 그랬고, 지금도 여전히."
  },
  Stage_94832_Name = {Text = "신승"},
  Stage_94837_Desc = {
    Text = "이 순간의 즐거움을 멈출 수 있다면, 그 기억의 유효기간이 영원이길 바란다."
  },
  Stage_94837_Name = {
    Text = "한 장의 사진"
  },
  Stage_94841_Desc = {
    Text = "해변이야말로 휴가의 정답이다. 무더위 속에서 시원한 파도를 밟으며 파라솔 아래에서 뜨거운 햇볕을 피하는 것을 누가 거부할 수 있겠는가? 잠깐……왜 태양이 떨어지는 거야?!"
  },
  Stage_94841_Name = {
    Text = "고온 경보"
  },
  Stage_94843_Desc = {
    Text = "열정 넘치는 경기장에서, 모든 선수가 자신의 매력을 뽐낼 것이다……감독님, 방송에 내보낼 수 없는 장면은 전부 잘라주세요."
  },
  Stage_94843_Name = {
    Text = "시작하자! 준결승!"
  },
  Stage_95332_Desc = {
    Text = "네가 그들에 합류하는 순간, 너는 죽음의 신과 계약을 체결하게 된다. 그들이 너에게 주는 모든 것을 잘 즐기라, 왜냐하면 계약이 언제 실타래행될지 너는 알지 못하기 때문이다."
  },
  Stage_95332_Name = {
    Text = "계약 목표·육"
  },
  Stage_95333_Desc = {
    Text = "네가 그들에 합류하는 순간, 너는 죽음의 신과 계약을 체결하게 된다. 그들이 너에게 주는 모든 것을 잘 즐기라, 왜냐하면 계약이 언제 실타래행될지 너는 알지 못하기 때문이다."
  },
  Stage_95333_Name = {
    Text = "계약 목표·오"
  },
  Stage_95334_Desc = {
    Text = "네가 그들에 합류하는 순간, 너는 죽음의 신과 계약을 체결하게 된다. 그들이 너에게 주는 모든 것을 잘 즐기라, 왜냐하면 계약이 언제 실타래행될지 너는 알지 못하기 때문이다."
  },
  Stage_95334_Name = {
    Text = "계약 목표·광란"
  },
  Stage_95335_Desc = {
    Text = "몸의 모든 세포가 반복되고 있다. 그저 같은 한 마디를 반복하며——빛이 왔다."
  },
  Stage_95335_Name = {
    Text = "세상의 빛·세 번째"
  },
  Stage_95336_Desc = {
    Text = "태양이 땅에 강림하듯, 심연에서 솟아오른다.\n모든 것이 서로 녹아들며, 위대한 존재에게 그들이 바쳐야 할 공물을 근헌합니다."
  },
  Stage_95336_Name = {
    Text = "지표의 태양·삼"
  },
  Stage_95337_Desc = {
    Text = "태양이 심연으로 돌아오는 순간, 세상은 고요해질 것이다.\n왜냐하면 이 세상은 재로 이뤄져서, 이제는 아무것도 남아 있지 않기 때문이다."
  },
  Stage_95337_Name = {
    Text = "침묵의 세계·첫 번째"
  },
  Stage_95338_Desc = {
    Text = "태양이 심연으로 돌아오는 순간, 세상은 고요해질 것이다.\n왜냐하면 이 세상은 재로 이뤄져서, 이제는 아무것도 남아 있지 않기 때문이다."
  },
  Stage_95338_Name = {
    Text = "침묵의 세계·세 번째"
  },
  Stage_95339_Desc = {
    Text = "태양이 심연으로 돌아오는 순간, 세상은 고요해질 것이다.\n왜냐하면 이 세상은 재로 이뤄져서, 이제는 아무것도 남아 있지 않기 때문이다."
  },
  Stage_95339_Name = {
    Text = "무언의 세계·광란"
  },
  Stage_95340_Desc = {
    Text = "그는 소리를 가져가지 않았으니, 그는 죄인이 지옥에서 신음하는 소리를 듣고 싶어했기 때문이다.\n무수한 빛 점들이 극주에서 춤추고, 공명하며, 그들의 목소리는 그 신음과 함께 엮여 완벽한 노래를 이루었다."
  },
  Stage_95340_Name = {
    Text = "지옥의 노래·첫 번째"
  },
