  },
  Stage_95373_Name = {
    Text = "타오르는 판결·두 번째"
  },
  Stage_95374_Desc = {
    Text = "그는 뜨거운 불꽃을 지니고 와서 너희의 죄를 판별한다. 너희는 가능한 한 저항해야 한다, 왜냐하면 그에게 오락을 제공하는 것은 너희의 마지막 구속이기 때문이다."
  },
  Stage_95374_Name = {
    Text = "타오르는 판결·광란"
  },
  Stage_95375_Desc = {
    Text = "상고의 맹세여, 나는 운명의 농담을 따르겠다. 이 의무를 이행하리라. 나는 무광의 혼돈 속에서 결코 꺼지지 않는 불사의 태양을 피울 것이다."
  },
  Stage_95375_Name = {
    Text = "영원한 맹세·제육"
  },
  Stage_95376_Desc = {
    Text = "몸의 모든 세포가 반복되고 있다. 그저 같은 한 마디를 반복하며——빛이 왔다."
  },
  Stage_95376_Name = {
    Text = "세상의 빛·첫 번째"
  },
  Stage_95377_Desc = {
    Text = "태양이 심연으로 돌아오는 순간, 세상은 고요해질 것이다.\n왜냐하면 이 세상은 재로 이뤄져서, 이제는 아무것도 남아 있지 않기 때문이다."
  },
  Stage_95377_Name = {
    Text = "침묵의 세계·다섯 번째"
  },
  Stage_95378_Desc = {
    Text = "그는 뜨거운 불꽃을 지니고 와서 너희의 죄를 판별한다. 너희는 가능한 한 저항해야 한다, 왜냐하면 그에게 오락을 제공하는 것은 너희의 마지막 구속이기 때문이다."
  },
  Stage_95378_Name = {
    Text = "타오르는 판결·여섯 번째"
  },
  Stage_95379_Desc = {
    Text = "몸의 모든 세포가 반복되고 있다. 그저 같은 한 마디를 반복하며——빛이 왔다."
  },
  Stage_95379_Name = {
    Text = "세상의 빛·다섯 번째"
  },
  Stage_95380_Desc = {
    Text = "그는 소리를 가져가지 않았으니, 그는 죄인이 지옥에서 신음하는 소리를 듣고 싶어했기 때문이다.\n무수한 빛 점들이 극주에서 춤추고, 공명하며, 그들의 목소리는 그 신음과 함께 엮여 완벽한 노래를 이루었다."
  },
  Stage_95380_Name = {
    Text = "지옥의 노래·다섯 번째"
  },
  Stage_95706_Desc = {
    Text = "그러한 슬프고 아름답고 너무 많은 기억을 담고 있는 영혼들이 바로 각 재료의 유일무이한 이유입니다.\n각 단계가 당신의 혀와 대결하고 싸운 후, 당신들은 하나로 융합됩니다.\n——모든 죽은 자가 평생 기다리는 것은 먹히는 바로 이 순간입니다."
  },
  Stage_95706_Name = {
    Text = "영혼의 제단 만찬·여섯 번째"
  },
  Stage_95707_Desc = {
    Text = "0.5인치 깊이, 경락의 방향과 수직입니다.\n목구멍과 날개뼈를 따라, 뼈와 살을 분리합니다.\n몸은 요리사의 체스판입니다."
  },
  Stage_95707_Name = {
    Text = "골혈 분리·여섯 번째"
  },
  Stage_95708_Desc = {
    Text = "냄새가 나? 참나무, 삼나무와 방울풀의 향긋함.\n그 주인은 이 아름다운 관 속에서 300년을 누웠습니다.\n그리하여 그 폐하가 이 연회의 주요 요리가 되는 영예를 얻었습니다."
  },
  Stage_95708_Name = {
    Text = "침묵의 관이 열렸다·여섯 번째"
  },
  Stage_95709_Desc = {
    Text = "냄새가 나? 참나무, 삼나무와 방울풀의 향긋함.\n그 주인은 이 아름다운 관 속에서 300년을 누웠습니다.\n그리하여 그 폐하가 이 연회의 주요 요리가 되는 영예를 얻었습니다."
  },
  Stage_95709_Name = {
    Text = "침묵의 관이 열렸다·두 번째"
  },
  Stage_95710_Desc = {
    Text = "소금 알갱이. 파슬리. 레몬그라스. 올리브. 로즈메리.\n하나의 충고: 아무리 좋은 재료라도 절대 향신료를 가볍게 보지 마십시오.\n이 체스판 위에서 향신료는 요리사의 말입니다."
  },
  Stage_95710_Name = {
    Text = "부패 조향·세 번째"
  },
  Stage_95711_Desc = {
    Text = "우리는 품격과 영원을 찬양하는데, 불꽃은 그것들의 반의어예요.\n하지만 이 세상에서 가장 영속적이고 가장 아름다운 풍미는 오히려 불꽃에서 온 것이죠.\n이런 절묘한 아이러니, 별로 재미있지 않나요?"
  },
  Stage_95711_Name = {
    Text = "저주받은 불꽃·첫 번째"
  },
