    Text = "0.5인치 깊이, 경락의 방향과 수직입니다.\n목구멍과 날개뼈를 따라, 뼈와 살을 분리합니다.\n몸은 요리사의 체스판입니다."
  },
  Stage_95739_Name = {
    Text = "골혈 분리·세 번째"
  },
  Stage_95740_Desc = {
    Text = "우리는 품격과 영원을 찬양하는데, 불꽃은 그것들의 반의어예요.\n하지만 이 세상에서 가장 영속적이고 가장 아름다운 풍미는 오히려 불꽃에서 온 것이죠.\n이런 절묘한 아이러니, 별로 재미있지 않나요?"
  },
  Stage_95740_Name = {
    Text = "저주받은 불꽃·광란"
  },
  Stage_95741_Desc = {
    Text = "그러한 슬프고 아름답고 너무 많은 기억을 담고 있는 영혼들이 바로 각 재료의 유일무이한 이유입니다.\n각 단계가 당신의 혀와 대결하고 싸운 후, 당신들은 하나로 융합됩니다.\n——모든 죽은 자가 평생 기다리는 것은 먹히는 바로 이 순간입니다."
  },
  Stage_95741_Name = {
    Text = "영혼의 제단 만찬·세 번째"
  },
  Stage_95742_Desc = {
    Text = "소금 알갱이. 파슬리. 레몬그라스. 올리브. 로즈메리.\n하나의 충고: 아무리 좋은 재료라도 절대 향신료를 가볍게 보지 마십시오.\n이 체스판 위에서 향신료는 요리사의 말입니다."
  },
  Stage_95742_Name = {
    Text = "부패 조향·네 번째"
  },
  Stage_97057_Desc = {
    Text = "열렬한 무용수들이 허상의 우상 주위를 돌고, 누구도 묻지 않는 신앙의 잔해 속에서, 오직 기쁨의 소용돌이만이 통제 불능으로 점점 더 짜여진다.\n이 순간, 모든 부끄러움과 걱정은 열광적인 회전 속에서 사라지고, 중생은 오직 환영을 위해 미친 듯이 춤춘다.\n픽맨은 크게 웃으며 너를 이 열광의 춤에 초대한다."
  },
  Stage_97057_Name = {
    Text = "황소의 광란·그 넷"
  },
  Stage_97058_Desc = {
    Text = "영감은 평범함에 만족하는 자의 금단의 열매이다.\n그리고 이 화폭 위에서 과장된 구도가 예술의 진리를 알려준다.\n영감은 돌풍처럼 찾아오며 초대받지 않고도 마음에 들어온다.\n그 순간, 숨겨진 불안과 갈망이 모두 깨어남하고, 어두운 밤을 뚫고 나오는 불꽃처럼 내면을 투명하고 열렬하게 비춘다."
  },
  Stage_97058_Name = {
    Text = "영감 감염·세 번째"
  },
  Stage_97059_Desc = {
    Text = "이렇게 미친 선을 본 적이 있습니까? \n각 궤적은 투시 법칙의 사슬을 벗어나고, 마치 폭동하는 죄수처럼 종이에 미친 듯이 달려갑니다.\n그들은 얽히고, 싸우고, 서로를 포식하며, 뒤틀린 춤으로 피크만이 보는 현실타래을 그려냅니다."
  },
  Stage_97059_Name = {
    Text = "선혼 난무·3"
  },
  Stage_97060_Desc = {
    Text = "이렇게 미친 선을 본 적이 있습니까? \n각 궤적은 투시 법칙의 사슬을 벗어나고, 마치 폭동하는 죄수처럼 종이에 미친 듯이 달려갑니다.\n그들은 얽히고, 싸우고, 서로를 포식하며, 뒤틀린 춤으로 피크만이 보는 현실타래을 그려냅니다."
  },
  Stage_97060_Name = {
    Text = "선혼 난무·5"
  },
  Stage_97061_Desc = {
    Text = "평범한 화가? 아니, 아니다.\n선홍색의 붓 터치가 넘쳐흘러 이상한 소용돌이가 빠르게 창백함과 맑음을 삼켜버린다.\n화려함과 음침함이 얽혀 있는 적색이 퍼져 나가며, 전체 작품에 소란함과 생명의 기운을 더해준다.\n오직 이 피와 같은 색만이 세상에서 가장 생생하고 진실타래한 존재이다!"
  },
  Stage_97061_Name = {
    Text = "피의 확산·광란"
  },
  Stage_97062_Desc = {
    Text = "평범한 화가? 아니, 아니다.\n선홍색의 붓 터치가 넘쳐흘러 이상한 소용돌이가 빠르게 창백함과 맑음을 삼켜버린다.\n화려함과 음침함이 얽혀 있는 적색이 퍼져 나가며, 전체 작품에 소란함과 생명의 기운을 더해준다.\n오직 이 피와 같은 색만이 세상에서 가장 생생하고 진실타래한 존재이다!"
  },
  Stage_97062_Name = {
    Text = "피의 확산·두 번째"
  },
  Stage_97063_Desc = {
    Text = "열렬한 무용수들이 허상의 우상 주위를 돌고, 누구도 묻지 않는 신앙의 잔해 속에서, 오직 기쁨의 소용돌이만이 통제 불능으로 점점 더 짜여진다.\n이 순간, 모든 부끄러움과 걱정은 열광적인 회전 속에서 사라지고, 중생은 오직 환영을 위해 미친 듯이 춤춘다.\n픽맨은 크게 웃으며 너를 이 열광의 춤에 초대한다."
  },
  Stage_97063_Name = {
    Text = "황소의 광란·그 다섯"
  },
  Stage_97064_Desc = {
    Text = "영감은 평범함에 만족하는 자의 금단의 열매이다.\n그리고 이 화폭 위에서 과장된 구도가 예술의 진리를 알려준다.\n영감은 돌풍처럼 찾아오며 초대받지 않고도 마음에 들어온다.\n그 순간, 숨겨진 불안과 갈망이 모두 깨어남하고, 어두운 밤을 뚫고 나오는 불꽃처럼 내면을 투명하고 열렬하게 비춘다."
  },
  Stage_97064_Name = {
    Text = "영감 감염·네 번째"
  },
  Stage_97065_Desc = {
    Text = "알 수 없는 고통이 색채의 깊이에서 포효하고 있습니다. 잔인한 장면이 떠오르고, 저편의 불꽃, 뒤틀린 그림자가 서로 얽혀 압도합니다.\n이때 캔버스는 죄와 벌의 감옥이 되어, 매 한치가 치열한 응징과 고통으로 반짝입니다.\n세상은 완전히 뒤집혀 모든 선함이 잠식되었고, 불타고 고통스러운 지옥에서 영혼의 진실타래이 드러납니다.\n보였나요? 이것이 예술의 아름다움입니다."
  },
  Stage_97065_Name = {
    Text = "지옥의 변혁·다섯 번째"
  },
  Stage_97066_Desc = {
    Text = "영혼은 캔버스 위에서 불타오르고, 투명한 유채가 서서히 흐르고, 피색은 영원의 세계로 잠금되며, 미친 짜증이 진정한 술로 존재한다.\n세속의 깨달음을 버리고 혼돈의 극락으로 뛰어들 때 비로소 예술 그 자체에 닿는다.\n아, 나는 이 궁극의 광기와 절망 속에 영원히 빠지고 싶다! \n와라, 이 광란의 잔치 후에 아름다운 신세계가 오길."
  },
  Stage_97066_Name = {
    Text = "환희 잠금·광란"
  },
  Stage_97067_Desc = {
    Text = "평범한 화가? 아니, 아니다.\n선홍색의 붓 터치가 넘쳐흘러 이상한 소용돌이가 빠르게 창백함과 맑음을 삼켜버린다.\n화려함과 음침함이 얽혀 있는 적색이 퍼져 나가며, 전체 작품에 소란함과 생명의 기운을 더해준다.\n오직 이 피와 같은 색만이 세상에서 가장 생생하고 진실타래한 존재이다!"
  },
  Stage_97067_Name = {
    Text = "피의 확산·세 번째"
  },
  Stage_97068_Desc = {
    Text = "피크맨의 광란의 붓질로 기름 색이 휘젓혀지고, 붓은 혈육과 혼의 쓴맛으로 가득 찹니다.\n광란 같은 궤적이 캔버스 위로 구불구불하게 이어지며, 악몽과 환상이 색채의 심연에서 조용히 떠오릅니다.\n그림 속 세계는 이 잃어버린 혼란 속에서 점점 뒤틀리고, 가라앉고 있습니다..."
  },
  Stage_97068_Name = {
    Text = "악몽의 중첩·네 번째"
  },
  Stage_97069_Desc = {
    Text = "영혼은 캔버스 위에서 불타오르고, 투명한 유채가 서서히 흐르고, 피색은 영원의 세계로 잠금되며, 미친 짜증이 진정한 술로 존재한다.\n세속의 깨달음을 버리고 혼돈의 극락으로 뛰어들 때 비로소 예술 그 자체에 닿는다.\n아, 나는 이 궁극의 광기와 절망 속에 영원히 빠지고 싶다! \n와라, 이 광란의 잔치 후에 아름다운 신세계가 오길."
  },
