  },
  Stage_97080_Desc = {
    Text = "알 수 없는 고통이 색채의 깊이에서 포효하고 있습니다. 잔인한 장면이 떠오르고, 저편의 불꽃, 뒤틀린 그림자가 서로 얽혀 압도합니다.\n이때 캔버스는 죄와 벌의 감옥이 되어, 매 한치가 치열한 응징과 고통으로 반짝입니다.\n세상은 완전히 뒤집혀 모든 선함이 잠식되었고, 불타고 고통스러운 지옥에서 영혼의 진실타래이 드러납니다.\n보였나요? 이것이 예술의 아름다움입니다."
  },
  Stage_97080_Name = {
    Text = "지옥의 변혁·첫 번째"
  },
  Stage_97081_Desc = {
    Text = "알 수 없는 고통이 색채의 깊이에서 포효하고 있습니다. 잔인한 장면이 떠오르고, 저편의 불꽃, 뒤틀린 그림자가 서로 얽혀 압도합니다.\n이때 캔버스는 죄와 벌의 감옥이 되어, 매 한치가 치열한 응징과 고통으로 반짝입니다.\n세상은 완전히 뒤집혀 모든 선함이 잠식되었고, 불타고 고통스러운 지옥에서 영혼의 진실타래이 드러납니다.\n보였나요? 이것이 예술의 아름다움입니다."
  },
  Stage_97081_Name = {
    Text = "지옥의 변혁·세 번째"
  },
  Stage_97082_Desc = {
    Text = "이렇게 미친 선을 본 적이 있습니까? \n각 궤적은 투시 법칙의 사슬을 벗어나고, 마치 폭동하는 죄수처럼 종이에 미친 듯이 달려갑니다.\n그들은 얽히고, 싸우고, 서로를 포식하며, 뒤틀린 춤으로 피크만이 보는 현실타래을 그려냅니다."
  },
  Stage_97082_Name = {
    Text = "선혼 난무·광란"
  },
  Stage_97083_Desc = {
    Text = "피크맨의 광란의 붓질로 기름 색이 휘젓혀지고, 붓은 혈육과 혼의 쓴맛으로 가득 찹니다.\n광란 같은 궤적이 캔버스 위로 구불구불하게 이어지며, 악몽과 환상이 색채의 심연에서 조용히 떠오릅니다.\n그림 속 세계는 이 잃어버린 혼란 속에서 점점 뒤틀리고, 가라앉고 있습니다..."
  },
  Stage_97083_Name = {
    Text = "악몽의 중첩·세 번째"
  },
  Stage_97084_Desc = {
    Text = "영혼은 캔버스 위에서 불타오르고, 투명한 유채가 서서히 흐르고, 피색은 영원의 세계로 잠금되며, 미친 짜증이 진정한 술로 존재한다.\n세속의 깨달음을 버리고 혼돈의 극락으로 뛰어들 때 비로소 예술 그 자체에 닿는다.\n아, 나는 이 궁극의 광기와 절망 속에 영원히 빠지고 싶다! \n와라, 이 광란의 잔치 후에 아름다운 신세계가 오길."
  },
  Stage_97084_Name = {
    Text = "환희 잠금·두 번째"
  },
