  Stage_97086_Name = {
    Text = "지옥의 변혁·두 번째"
  },
  Stage_97087_Desc = {
    Text = "알 수 없는 고통이 색채의 깊이에서 포효하고 있습니다. 잔인한 장면이 떠오르고, 저편의 불꽃, 뒤틀린 그림자가 서로 얽혀 압도합니다.\n이때 캔버스는 죄와 벌의 감옥이 되어, 매 한치가 치열한 응징과 고통으로 반짝입니다.\n세상은 완전히 뒤집혀 모든 선함이 잠식되었고, 불타고 고통스러운 지옥에서 영혼의 진실타래이 드러납니다.\n보였나요? 이것이 예술의 아름다움입니다."
  },
  Stage_97087_Name = {
    Text = "지옥의 변혁·여섯 번째"
  },
  Stage_97088_Desc = {
    Text = "열렬한 무용수들이 허상의 우상 주위를 돌고, 누구도 묻지 않는 신앙의 잔해 속에서, 오직 기쁨의 소용돌이만이 통제 불능으로 점점 더 짜여진다.\n이 순간, 모든 부끄러움과 걱정은 열광적인 회전 속에서 사라지고, 중생은 오직 환영을 위해 미친 듯이 춤춘다.\n픽맨은 크게 웃으며 너를 이 열광의 춤에 초대한다."
  },
  Stage_97088_Name = {
    Text = "황소의 광란·그 셋"
  },
  Stage_97089_Desc = {
    Text = "광적인 무용수들이 허망한 우상을 중심으로 회전하며, 아무도 신앙의 잔해를 돌보지 않는다. 오직 환희의 소용돌이만이 통제 불능 속에서 점점 더 조여든다.\n이 순간, 모든 수치와 거리낌이 광적인 회전 속에서 사라지고, 중생은 오직 환영을 위해 미친 듯이 춤춘다. \n피크먼이 크게 웃으며, 당신을 이 광적인 춤에 초대한다."
  },
  Stage_97089_Name = {
    Text = "황소의 광란·그 일부분"
  },
  Stage_97090_Desc = {
    Text = "평범한 화가? 아니, 아니다.\n선홍색의 붓 터치가 넘쳐흘러 이상한 소용돌이가 빠르게 창백함과 맑음을 삼켜버린다.\n화려함과 음침함이 얽혀 있는 적색이 퍼져 나가며, 전체 작품에 소란함과 생명의 기운을 더해준다.\n오직 이 피와 같은 색만이 세상에서 가장 생생하고 진실타래한 존재이다!"
  },
  Stage_97090_Name = {
    Text = "피의 확산·네 번째"
  },
  Stage_97091_Desc = {
