  },
  Stage_97105_Desc = {
    Text = "알 수 없는 고통이 색채의 깊이에서 포효하고 있습니다. 잔인한 장면이 떠오르고, 저편의 불꽃, 뒤틀린 그림자가 서로 얽혀 압도합니다.\n이때 캔버스는 죄와 벌의 감옥이 되어, 매 한치가 치열한 응징과 고통으로 반짝입니다.\n세상은 완전히 뒤집혀 모든 선함이 잠식되었고, 불타고 고통스러운 지옥에서 영혼의 진실타래이 드러납니다.\n보였나요? 이것이 예술의 아름다움입니다."
  },
  Stage_97105_Name = {
    Text = "지옥의 변혁·네 번째"
  },
  Stage_97227_Desc = {
    Text = "제물은 도착했고, 피가 가득 차 있으며, 우주를 지배하는 최고의 주님이여! 당신의 신자를 영원의 세계로 인도해주세요!"
  },
  Stage_97227_Name = {
    Text = "피의 제사"
  },
  Stage_97228_Desc = {
    Text = "검은 태양이 강림했군요, 그렇지 않나요?"
  },
  Stage_97228_Name = {
    Text = "검은 태양"
  },
  Stage_97229_Desc = {
    Text = "배신은 마침내 일어났고, 「혼란에 빠져서」,「어쩔 수 없이」,「생존을 위해」라는 얼마나 완벽한 배신의 이유인가.\n하지만 그것은 잘못된 배신자를 선택했습니다."
  },
  Stage_97229_Name = {
    Text = "배신의 소리"
  },
  Stage_97230_Desc = {
    Text = "수수께끼의 정체가 드러났어, 너 맞혔어? \n너무 진부하다고 느껴? 난 꽤 재밌다고 생각해, 어쨌든…… 난 재미있거나 없거나 상관없어~"
  },
  Stage_97230_Name = {
    Text = "배후의 주범"
  },
  Stage_97231_Desc = {
    Text = "우리는 모든 은혜를 잊지 않을 것이고, 모든 원한도 잊지 않을 것입니다. 이것이 우리가 이 잔인한 세상에서 살아가는 마지막 사치입니다."
  },
  Stage_97231_Name = {
    Text = "영원히 기억하다"
  },
  Stage_97232_Desc = {
    Text = "너의 숙취에 찌든 머리를 들고, 너의 더러운 술잔을 잡아라. 어젯밤의 모든 것을 잊고, 새로운 파티가 다가오고 있다. \n내 친구여, 표현주의의 천국에 오신 것을 환영합니다."
  },
  Stage_97232_Name = {
    Text = "야수주의 선술집"
  },
  Stage_97233_Desc = {
    Text = "마지막 한 방울의 술이 잔에서 떨어질 때, 모든 것을 묻는 총소리가 응답했다."
  },
  Stage_97233_Name = {Text = "마른 술"},
  Stage_97288_Desc = {
    Text = "모의 전투"
  },
  Stage_97288_Name = {
    Text = "모의전 3"
  },
  Stage_97615_Desc = {
    Text = "신께서는 만물이 각자의 길로 흩어지게 하셨다.\n굽이친 뿌리들은 썩은 흙을 파고들었고, 발톱과 송곳니, 비늘과 깃은 서로를 물어뜯으며 기어올랐다. 꽃은 백골 위에 피어났고, 약한 존재는 강한 이의 배 속으로 삼켜졌다.\n그분은 생명에게 서로 얽히고 싸울 권리를 주셨다."
  },
  Stage_97615_Name = {
    Text = "다섯째 날·광란"
  },
  Stage_97616_Desc = {
    Text = "신께서는 별들을 바른 자리에 두고, 태양과 달로 하여금 제 역할을 행하게 하셨다.\n광기 서린 궤도에 흩어진 광명과 암흔은, 아득한 세월 방황하던 혼백들에게 귀환의 길을 밝혀 주었다.\n그분은 신앙을 가진 자들에게 잃었던 권리를 돌려주셨다."
  },
  Stage_97616_Name = {
    Text = "셋째 날·광란"
  },
  Stage_97617_Desc = {
    Text = "신께서는 형체 없는 씨앗을 세상에 틔우셨다.\n지느러미를 지닌 자들은 바다를 거슬러 헤엄치고, 날개를 지닌 자들은 하늘을 가르며 날았다.\n그분은 은밀한 속삭임을 내려 그들이 깊은 바다 속에서 숨을 쉬게 하였고, 광기 어린 찬가를 내려 그들이 구름을 가로지를 수 있게 하셨다."
  },
  Stage_97617_Name = {
    Text = "넷째 날·4"
  },
  Stage_97618_Desc = {
    Text = "신께서는 형체 없는 씨앗을 세상에 틔우셨다.\n지느러미를 지닌 자들은 바다를 거슬러 헤엄치고, 날개를 지닌 자들은 하늘을 가르며 날았다.\n그분은 은밀한 속삭임을 내려 그들이 깊은 바다 속에서 숨을 쉬게 하였고, 광기 어린 찬가를 내려 그들이 구름을 가로지를 수 있게 하셨다."
  },
  Stage_97618_Name = {
    Text = "넷째 날·3"
  },
  Stage_97619_Desc = {
    Text = "신께서는 하늘과 땅, 땅과 바다를 구분지으셨다.\n푸른 하늘에는 끈적하고 맥동하는 장막이 드리워지고, 유황과 소금의 냄새가 심연 깊은 곳에서 피어올랐다.\n그분은 바다의 백성들에게 어디든지 걸을 수 있는 권리를 주셨다."
  },
  Stage_97619_Name = {
    Text = "둘째 날·3"
  },
  Stage_97620_Desc = {
    Text = "신께서는 만물이 각자의 길로 흩어지게 하셨다.\n굽이친 뿌리들은 썩은 흙을 파고들었고, 발톱과 송곳니, 비늘과 깃은 서로를 물어뜯으며 기어올랐다. 꽃은 백골 위에 피어났고, 약한 존재는 강한 이의 배 속으로 삼켜졌다.\n그분은 생명에게 서로 얽히고 싸울 권리를 주셨다."
  },
  Stage_97620_Name = {
    Text = "다섯째 날·6"
  },
  Stage_97621_Desc = {
    Text = "신께서는 만물이 각자의 길로 흩어지게 하셨다.\n굽이친 뿌리들은 썩은 흙을 파고들었고, 발톱과 송곳니, 비늘과 깃은 서로를 물어뜯으며 기어올랐다. 꽃은 백골 위에 피어났고, 약한 존재는 강한 이의 배 속으로 삼켜졌다.\n그분은 생명에게 서로 얽히고 싸울 권리를 주셨다."
  },
  Stage_97621_Name = {
    Text = "다섯째 날·4"
  },
  Stage_97622_Desc = {
    Text = "신께서는 하늘과 땅, 땅과 바다를 구분지으셨다.\n푸른 하늘에는 끈적하고 맥동하는 장막이 드리워지고, 유황과 소금의 냄새가 심연 깊은 곳에서 피어올랐다.\n그분은 바다의 백성들에게 어디든지 걸을 수 있는 권리를 주셨다."
  },
  Stage_97622_Name = {
    Text = "둘째 날·4"
  },
  Stage_97623_Desc = {
    Text = "신께서는 왜 썩어가고, 신께서는 왜 고름과 피를 흘리시는가.\n신이시여, 제게 길을 보여 주십시오, 깨어나 주십시오. 저를 구해 주십시오!\n아아, 신이시여, 신이시여...\n그러나 모든 것은 우스운 착각과 허망한 거짓일 뿐이었다."
  },
  Stage_97623_Name = {
    Text = "일곱째 날·6"
  },
  Stage_97624_Desc = {
    Text = "신께서는 형체 없는 씨앗을 세상에 틔우셨다.\n지느러미를 지닌 자들은 바다를 거슬러 헤엄치고, 날개를 지닌 자들은 하늘을 가르며 날았다.\n그분은 은밀한 속삭임을 내려 그들이 깊은 바다 속에서 숨을 쉬게 하였고, 광기 어린 찬가를 내려 그들이 구름을 가로지를 수 있게 하셨다."
  },
  Stage_97624_Name = {
    Text = "넷째 날·6"
  },
  Stage_97625_Desc = {
    Text = "신은 지혜도 지각도 없는 가짜를 창조하셨다.\n어둠 속으로 함께 가라앉은 제물들은 정해진 운명에서 벗어날 수 없었고, 그분은 아무런 계시도, 아무런 답도 주지 않았다. 눈도 입도 갖지 못한 유아는 거짓된 교리를 가져왔다.\n그분은 깨어 있는 자들에게 미혹될 권리를 주셨다."
  },
  Stage_97625_Name = {
    Text = "여섯째 날·6"
  },
  Stage_97626_Desc = {
    Text = "신께서는 하늘과 땅, 땅과 바다를 구분지으셨다.\n푸른 하늘에는 끈적하고 맥동하는 장막이 드리워지고, 유황과 소금의 냄새가 심연 깊은 곳에서 피어올랐다.\n그분은 바다의 백성들에게 어디든지 걸을 수 있는 권리를 주셨다."
  },
  Stage_97626_Name = {
    Text = "둘째 날·5"
  },
  Stage_97627_Desc = {
    Text = "신께서는 왜 썩어가고, 신께서는 왜 고름과 피를 흘리시는가.\n신이시여, 제게 길을 보여 주십시오, 깨어나 주십시오. 저를 구해 주십시오!\n아아, 신이시여, 신이시여...\n그러나 모든 것은 우스운 착각과 허망한 거짓일 뿐이었다."
  },
  Stage_97627_Name = {
    Text = "일곱째 날·1"
  },
  Stage_97628_Desc = {
    Text = "신께서는 하늘과 땅, 땅과 바다를 구분지으셨다.\n푸른 하늘에는 끈적하고 맥동하는 장막이 드리워지고, 유황과 소금의 냄새가 심연 깊은 곳에서 피어올랐다.\n그분은 바다의 백성들에게 어디든지 걸을 수 있는 권리를 주셨다."
  },
  Stage_97628_Name = {
    Text = "둘째 날·광란"
  },
  Stage_97629_Desc = {
    Text = "신께서는 혼돈 속에서 빛으로 낮과 밤을 구분지으셨다.\n꿈틀거리는 빛의 얼룩이 영원한 어둠을 몰아내었고, 그분의 백성은 더 이상 어둠의 위협을 걱정할 필요가 없게 되었다.\n그분은 모든 이들에게 밤에 안심하고 잠들 수 있는 권리를 주셨다."
  },
