  },
  Stage_97640_Desc = {
    Text = "신께서는 혼돈 속에서 빛으로 낮과 밤을 구분지으셨다.\n꿈틀거리는 빛의 얼룩이 영원한 어둠을 몰아내었고, 그분의 백성은 더 이상 어둠의 위협을 걱정할 필요가 없게 되었다.\n그분은 모든 이들에게 밤에 안심하고 잠들 수 있는 권리를 주셨다."
  },
  Stage_97640_Name = {
    Text = "첫째 날·6"
  },
  Stage_97641_Desc = {
    Text = "신께서는 하늘과 땅, 땅과 바다를 구분지으셨다.\n푸른 하늘에는 끈적하고 맥동하는 장막이 드리워지고, 유황과 소금의 냄새가 심연 깊은 곳에서 피어올랐다.\n그분은 바다의 백성들에게 어디든지 걸을 수 있는 권리를 주셨다."
  },
  Stage_97641_Name = {
    Text = "둘째 날·1"
  },
  Stage_97642_Desc = {
    Text = "신께서는 혼돈 속에서 빛으로 낮과 밤을 구분지으셨다.\n꿈틀거리는 빛의 얼룩이 영원한 어둠을 몰아내었고, 그분의 백성은 더 이상 어둠의 위협을 걱정할 필요가 없게 되었다.\n그분은 모든 이들에게 밤에 안심하고 잠들 수 있는 권리를 주셨다."
  },
  Stage_97642_Name = {
    Text = "첫째 날·2"
  },
  Stage_97643_Desc = {
    Text = "신께서는 별들을 바른 자리에 두고, 태양과 달로 하여금 제 역할을 행하게 하셨다.\n광기 서린 궤도에 흩어진 광명과 암흔은, 아득한 세월 방황하던 혼백들에게 귀환의 길을 밝혀 주었다.\n그분은 신앙을 가진 자들에게 잃었던 권리를 돌려주셨다."
  },
  Stage_97643_Name = {
    Text = "셋째 날·5"
  },
  Stage_97644_Desc = {
    Text = "신께서는 만물이 각자의 길로 흩어지게 하셨다.\n굽이친 뿌리들은 썩은 흙을 파고들었고, 발톱과 송곳니, 비늘과 깃은 서로를 물어뜯으며 기어올랐다. 꽃은 백골 위에 피어났고, 약한 존재는 강한 이의 배 속으로 삼켜졌다.\n그분은 생명에게 서로 얽히고 싸울 권리를 주셨다."
  },
  Stage_97644_Name = {
    Text = "다섯째 날·1"
  },
  Stage_97645_Desc = {
