  Stage_97646_Name = {
    Text = "셋째 날·4"
  },
  Stage_97647_Desc = {
    Text = "신께서는 별들을 바른 자리에 두고, 태양과 달로 하여금 제 역할을 행하게 하셨다.\n광기 서린 궤도에 흩어진 광명과 암흔은, 아득한 세월 방황하던 혼백들에게 귀환의 길을 밝혀 주었다.\n그분은 신앙을 가진 자들에게 잃었던 권리를 돌려주셨다."
  },
  Stage_97647_Name = {
    Text = "셋째 날·2"
  },
  Stage_97648_Desc = {
    Text = "신은 지혜도 지각도 없는 가짜를 창조하셨다.\n어둠 속으로 함께 가라앉은 제물들은 정해진 운명에서 벗어날 수 없었고, 그분은 아무런 계시도, 아무런 답도 주지 않았다. 눈도 입도 갖지 못한 유아는 거짓된 교리를 가져왔다.\n그분은 깨어 있는 자들에게 미혹될 권리를 주셨다."
  },
  Stage_97648_Name = {
    Text = "여섯째 날·4"
  },
  Stage_97649_Desc = {
    Text = "신은 지혜도 지각도 없는 가짜를 창조하셨다.\n어둠 속으로 함께 가라앉은 제물들은 정해진 운명에서 벗어날 수 없었고, 그분은 아무런 계시도, 아무런 답도 주지 않았다. 눈도 입도 갖지 못한 유아는 거짓된 교리를 가져왔다.\n그분은 깨어 있는 자들에게 미혹될 권리를 주셨다."
  },
  Stage_97649_Name = {
    Text = "여섯째 날·광란"
  },
  Stage_97650_Desc = {
    Text = "신께서는 왜 썩어가고, 신께서는 왜 고름과 피를 흘리시는가.\n신이시여, 제게 길을 보여 주십시오, 깨어나 주십시오. 저를 구해 주십시오!\n아아, 신이시여, 신이시여...\n그러나 모든 것은 우스운 착각과 허망한 거짓일 뿐이었다."
  },
  Stage_97650_Name = {
    Text = "일곱째 날·광란"
  },
  Stage_97651_Desc = {
    Text = "신께서는 하늘과 땅, 땅과 바다를 구분지으셨다.\n푸른 하늘에는 끈적하고 맥동하는 장막이 드리워지고, 유황과 소금의 냄새가 심연 깊은 곳에서 피어올랐다.\n그분은 바다의 백성들에게 어디든지 걸을 수 있는 권리를 주셨다."
  },
  Stage_97651_Name = {
    Text = "둘째 날·2"
  },
  Stage_97652_Desc = {
    Text = "신께서는 형체 없는 씨앗을 세상에 틔우셨다.\n지느러미를 지닌 자들은 바다를 거슬러 헤엄치고, 날개를 지닌 자들은 하늘을 가르며 날았다.\n그분은 은밀한 속삭임을 내려 그들이 깊은 바다 속에서 숨을 쉬게 하였고, 광기 어린 찬가를 내려 그들이 구름을 가로지를 수 있게 하셨다."
  },
