  Stage_97663_Name = {
    Text = "셋째 날·1"
  },
  Stage_97807_Desc = {
    Text = "어머니, 사람들은 태어나서 죽기까지 늘 속삭이는 주문이다.\n자신을 키우고 싶어하는 아이는 없고, 사랑이 넘치는 어머니의 품을 원하지 않는 아이는 없다.\n너는 그 잔인한 운명을 연기하며, 다시 한 번 그녀를 어머니의 품에서 끌어낼 것인가?"
  },
  Stage_97807_Name = {
    Text = "완벽한 동화·광란"
  },
  Stage_97808_Desc = {
    Text = "아름다운 글자는 종종 고통에서 태어난다.\n그녀는 그 아름다움을 느낄 때, 이미 그 잔혹한 현실타래의 그림자 속에 숨어 있는 비극을 알게 된다.\n아름다운 것, 그것은 덧없고 부서진 모든 것이다."
  },
  Stage_97808_Name = {
    Text = "시적인 정원·육"
  },
  Stage_97809_Desc = {
    Text = "이 순간의 즐거움을 멈출 수 있다면, 그 기억의 유효기간이 영원이길 바란다."
  },
  Stage_97809_Name = {
    Text = "한 장의 사진"
  },
  Stage_97810_Desc = {
    Text = "아름다운 글자는 종종 고통에서 태어난다.\n그녀는 그 아름다움을 느낄 때, 이미 그 잔혹한 현실타래의 그림자 속에 숨어 있는 비극을 알게 된다.\n아름다운 것, 그것은 덧없고 부서진 모든 것이다."
  },
  Stage_97810_Name = {
    Text = "시적인 정원·이"
  },
  Stage_97811_Desc = {
    Text = "그녀는 영혼을 잃은 이후에도 자신의 이상을 잊지 않았다.\n과학으로 죽은 사람은 한때 과학을 위해 열심히 살아왔다."
  },
  Stage_97811_Name = {
    Text = "기계의 꿈· 광란"
  },
  Stage_97812_Desc = {
    Text = "너는 익숙하면서도 낯선 캠퍼스에서 열렬하고 평범한 모든 것을 바라보며, 이를 즐거워하며 매료될까? 아니면 이러한 것들을 단 한 번도 가져본 적이 없음을 애통하게 여길까?"
  },
  Stage_97812_Name = {
    Text = "고향을 다시 찾다·5"
  },
  Stage_97813_Desc = {
    Text = "어머니, 사람들은 태어나서 죽기까지 늘 속삭이는 주문이다.\n자신을 키우고 싶어하는 아이는 없고, 사랑이 넘치는 어머니의 품을 원하지 않는 아이는 없다.\n너는 그 잔인한 운명을 연기하며, 다시 한 번 그녀를 어머니의 품에서 끌어낼 것인가?"
  },
  Stage_97813_Name = {
    Text = "완벽한 동화·두 번째"
  },
  Stage_97814_Desc = {
    Text = "1등을 차지할 사람이, 같은 곳에서 두 번이나 넘어질 리가 없어!"
  },
  Stage_97814_Name = {
    Text = "결승의 한 공"
