  Stage_97815_Name = {
    Text = "기계의 꿈· 첫 번째"
  },
  Stage_97816_Desc = {
    Text = "그녀는 영혼을 잃은 이후에도 자신의 이상을 잊지 않았다.\n과학으로 죽은 사람은 한때 과학을 위해 열심히 살아왔다."
