  Stage_97816_Name = {
    Text = "기계의 꿈· 네 번째"
  },
  Stage_97817_Desc = {
    Text = "태양은 이미 죽었고, 하늘에 남아 있는 것은 바람에 부서진 시체일 뿐이다.\n이 고장 난 세상이 두꺼운 먼지 속에 남은 것은, 과연 생명인가, 아니면 생명이 죽기 전의 환영인가?"
  },
  Stage_97817_Name = {
