  },
  Stage_97819_Name = {
    Text = "고향을 다시 찾다·1"
  },
  Stage_97820_Desc = {
    Text = "어머니, 사람들은 태어나서 죽기까지 늘 속삭이는 주문이다.\n자신을 키우고 싶어하는 아이는 없고, 사랑이 넘치는 어머니의 품을 원하지 않는 아이는 없다.\n너는 그 잔인한 운명을 연기하며, 다시 한 번 그녀를 어머니의 품에서 끌어낼 것인가?"
  },
