  Stage_97903_Desc = {
    Text = "오랜만에 고향에 돌아갔을 때, 너는 가장 어울리지 않는 「타국인」이 되어 있었다."
  },
  Stage_97903_Name = {Text = "귀향"},
  Stage_97904_Desc = {
    Text = "당신이 원하고 싶은 삶의 장소를 묘사해야 한다면, 어떤 집과 무성한 숲, 그리고 어떤 자신을 그릴 것인가요?\n당신이 그린 모든 것은 결코 결점 없는 이상인가, 깊이 묻힌 상처인가요?"
  },
  Stage_97904_Name = {
    Text = "심령 묘사"
  },
  Stage_97905_Desc = {
    Text = "희망을 향해 나아가는 길은 먼저 희망을 직접 끊어야 합니다."
  },
  Stage_97905_Name = {Text = "자각몽"},
  Stage_97906_Desc = {
    Text = "그들과 작별하렴, 그리고 그들과 재회할 길을 걸어가."
  },
  Stage_97906_Name = {Text = "너의 꿈"},
  Stage_97907_Desc = {
    Text = "가장 완벽한 결말은 가장 허위의 결말이기도 하며, 모든 행복한 미소 속에서 너는 깨어남과 진실타래을 선택해야 한다.\n왜냐하면 너는 그 유일한 비밀 지키는 사람이기 때문이다."
  },
  Stage_97907_Name = {
    Text = "허위 결말"
  },
  Stage_97908_Desc = {
    Text = "그 떨어지는 꽃잎은 마치 붉은 불꽃처럼."
  },
  Stage_97908_Name = {
    Text = "꽃잎이 떨어질 때"
  },
  Stage_97909_Desc = {
    Text = "만약 운명이 잔인하지 않았다면, 그녀들은 이상적인 처음의 모습으로 살아갈 수 있었을까요?"
  },
  Stage_97909_Name = {
    Text = "최초의 소원"
  },
  Stage_97910_Desc = {
    Text = "하얀 드레스, 침대, 방, 그리고 아름다운 꿈."
  },
  Stage_97910_Name = {
    Text = "순백의 동화"
  },
  Stage_98000_Desc = {
    Text = "허상은 결국 깨질 것이고, 진정한 불멸의 위대한 것 앞에서는 모든 음모와 계산은 무력하고 미약해 보일 것입니다.\n낮이 밝아오고, 불은 호박색 북롭게서 떨어져 내려와 모든 것에 평등한 파괴와 죽음을 가져옵니다."
  },
  Stage_98000_Name = {
    Text = "영원히 꺼지지 않는 태양"
  },
  Stage_98829_Desc = {
    Text = "고통은 사람을 깨우게 하는 좋은 약이다."
