  Stage_99725_Desc = {
    Text = "비판은 예술가의 책임이 아니다, 창조가 진정한 임무이다."
  },
  Stage_99725_Name = {
    Text = "진흙 위의 살롱"
  },
  Stage_99726_Desc = {
    Text = "우리는 항상 같은 저울 위에서 서로를 짓밟아왔지만, 친애하는 동생이여, 설령 그것을 파괴할 수 없더라도, 우리는 원래 저울에서 뛰어내릴 수 있었다."
  },
  Stage_99726_Name = {
    Text = "무너진 저울"
  },
  Stage_99727_Desc = {
    Text = "서로를 기대고 있는 두 마리 새, 태어날 때부터 격리된 새장은 노래할 수밖에 없습니다."
  },
  Stage_99727_Name = {Text = "쌍생조"},
  Stage_99728_Desc = {
    Text = "진실타래을 목격한 사람은 허구를 어떻게 참아야 할까요?"
  },
  Stage_99728_Name = {
    Text = "보라, 달이여"
  },
  Stage_99729_Desc = {
    Text = "운명은 최악의 시계를 가지고 있어, 잃는 건 너무 일찍 오고, 가지는 건 너무 늦게 오게 하지."
  },
  Stage_99729_Name = {
    Text = "무질서한 운명"
  },
  Stage_99730_Desc = {
    Text = "날아라, 날아라, 자유를 그리워하는 새야.\n부드러운 바람이 너를 지지해주었고, 폭우와 천둥을 뚫고 날아가라, 그 검은 날개는 결국 붉은 태양을 비춘다."
  },
  Stage_99730_Name = {
    Text = "순흑의 날개"
  },
  Stage_99731_Desc = {
    Text = "그들은 함께 춤추고, 어우러지며, 서로 물어뜯습니다.\n그들은 모든 고급 동물들이 하는 모든 일을 합니다."
  },
  Stage_99731_Name = {
    Text = "고급 동물"
  },
  Stage_99732_Desc = {
    Text = "한 번 날개의 날개를 뽑아내면, 그 새는 점차 비행하는 방법을 잊게 될 것입니다."
  },
  Stage_99732_Name = {
    Text = "좁은 문 밖"
  },
  Stage_99733_Desc = {
    Text = "그 검은 심지를 점화하여 모든 것을 그에게 바치십시오; 그 등불이 영원한 빛을 발하게 하여 세상의 모든 죄를 정화하십시오."
  },
  Stage_99733_Name = {Text = "봉헌"}
